function showFatal(kind, detail) {
  BOOT.failed = true;
  const info = ERRORS[kind] || ERRORS.runtime;
  const text = detail ? `${info.text}\n\nТехнічні деталі: ${detail}` : info.text;
  console.error(`[WILD HUNT] ${info.title}: ${text}`);
  if (typeof BOOT.showError === 'function') {
    BOOT.showError(info.title, text, info.tips);
    return;
  }
  const screen = document.getElementById('error-screen');
  if (!screen) return;
  document.getElementById('error-title').textContent = info.title;
  document.getElementById('error-text').textContent = text;
  const list = document.getElementById('error-tips');
  list.innerHTML = '';
  for (const tip of info.tips) {
    const li = document.createElement('li');
    li.textContent = tip;
    list.appendChild(li);
  }
  screen.classList.remove('hidden');
}

// Усі елементи з id потрапляють в об'єкт ui під іменами в camelCase (btn-start → ui.btnStart).
function cacheDom() {
  for (const el of document.querySelectorAll('[id]')) {
    ui[el.id.replace(/-([a-z0-9])/g, (m, c) => c.toUpperCase())] = el;
  }
}

function setLoading(progress, text) {
  if (ui.loadingFill) ui.loadingFill.style.transform = `scaleX(${clamp(progress, 0, 1)})`;
  if (ui.loadingText && text) ui.loadingText.textContent = text;
}

// Дає браузеру перемалювати індикатор завантаження між важкими кроками.
function yieldFrame() {
  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (!done) {
        done = true;
        resolve();
      }
    };
    requestAnimationFrame(() => setTimeout(finish, 0));
    setTimeout(finish, 80);
  });
}

async function loadingStep(progress, text) {
  setLoading(progress, text);
  await yieldFrame();
}

// Перевірка WebGL 2 і назва графічного процесора (для автоматичного вибору якості).
function probeWebGL() {
  const out = { ok: false, gpu: '' };
  try {
    if (!window.WebGL2RenderingContext) return out;
    const canvas = document.createElement('canvas');
    const gl = canvas.getContext('webgl2');
    if (!gl) return out;
    out.ok = true;
    const info = gl.getExtension('WEBGL_debug_renderer_info');
    if (info) out.gpu = String(gl.getParameter(info.UNMASKED_RENDERER_WEBGL) || '');
    const lose = gl.getExtension('WEBGL_lose_context');
    if (lose) lose.loseContext();
  } catch (err) {
    out.ok = false;
  }
  return out;
}

// Автовибір профілю: слабкі GPU та пристрої з малою пам'яттю — «Низький», більшість телефонів —
// «Середній», флагмани — «Високий», комп'ютери — «Ультра». Далі графіку підлаштовує адаптивний
// режим за реальним FPS. Гравець може змінити профіль у налаштуваннях.
function detectQuality(isTouch, gpu) {
  const mem = navigator.deviceMemory || 4;
  const cores = navigator.hardwareConcurrency || 4;
  const weakGpu = /Mali-(4|T|G3\d|G5[0-2])|Adreno \(TM\) ([2-5]\d\d|60\d|61\d)|PowerVR|SwiftShader|llvmpipe|Software/i.test(gpu);
  if (!isTouch) return weakGpu ? 'high' : 'ultra';
  if (weakGpu || mem <= 3 || cores <= 4) return 'low';
  const flagship = /Apple GPU|Adreno \(TM\) (7[3-9]\d|8\d\d)|Mali-G(7[1-9]|[6-9]1\d)|Immortalis/i.test(gpu);
  return flagship && mem >= 6 ? 'high' : 'medium';
}

async function loadThree() {
  try {
    const mod = await import('three');
    if (mod && typeof mod.WebGLRenderer === 'function') {
      BOOT.threeSource = 'importmap';
      return mod;
    }
  } catch (err) {
    console.warn('[WILD HUNT] Карта імпорту недоступна, пробую пряме посилання на Three.js:', err && err.message ? err.message : err);
  }
  for (const url of THREE_URLS) {
    try {
      const mod = await import(url);
      if (mod && typeof mod.WebGLRenderer === 'function') {
        BOOT.threeSource = 'direct';
        return mod;
      }
    } catch (err) {
      console.warn('[WILD HUNT] Three.js не завантажився з', url, err);
    }
  }
  return null;
}

// Додатки three/addons завантажуються тільки через карту імпорту (вони імпортують «three»).
async function loadAddons(names) {
  if (BOOT.threeSource !== 'importmap') return false;
  const paths = {
    GLTFLoader: 'three/addons/loaders/GLTFLoader.js',
    DRACOLoader: 'three/addons/loaders/DRACOLoader.js',
    SkeletonUtils: 'three/addons/utils/SkeletonUtils.js',
  };
  let ok = true;
  await Promise.all(names.map(async (name) => {
    if (ADDONS[name]) return;
    try {
      const mod = await import(paths[name]);
      ADDONS[name] = name === 'SkeletonUtils' ? mod : (mod[name] || mod);
    } catch (err) {
      ok = false;
      console.warn(`[WILD HUNT] Додаток ${name} не завантажився — гра працюватиме без нього.`, err);
    }
  }));
  return ok;
}

// assets/manifest.json — список зовнішніх моделей і текстур. Без нього гра використовує процедурні.
async function loadManifest() {
  // Однофайлова версія: маніфест (разом із вбудованими моделями) лежить прямо в HTML.
  const inline = document.getElementById('wh-manifest');
  if (inline) {
    try {
      const json = JSON.parse(inline.textContent);
      if (json && typeof json === 'object') return json;
    } catch (err) {
      console.warn('[WILD HUNT] Вбудований маніфест ресурсів пошкоджено — використовуються процедурні моделі.', err);
    }
  }
  try {
    const res = await fetch(MANIFEST_URL, { cache: 'no-cache' });
    if (!res.ok) return {};
    const json = await res.json();
    return json && typeof json === 'object' ? json : {};
  } catch (err) {
    console.warn('[WILD HUNT] assets/manifest.json не прочитано — використовуються процедурні моделі й текстури.', err);
    return {};
  }
}

// ═══ Натискання кнопок на сенсорних екранах (Safari на iPhone і Chrome на Android) ═══
// Дія виконується на touchend звичайного дотику, а синтетичний click після нього пригнічується
// (preventDefault на touchend). Так кнопка не залежить від того, чи надішле iOS Safari click,
// не спрацьовує двічі (дотик + click) і не «клацає» вдруге по вікну, що відкрилося під пальцем.
// Миша, стилус без дотику та клавіатура (Enter/Пробіл) працюють через звичайний click.
// Зсув пальця понад TAP_SLOP — це прокручування списку, а не натискання.
const TAP_SLOP = 12;
const TAP_CLICK_GUARD = 800;   // мс: click одразу після обробленого дотику ігнорується

function onTap(el, fn) {
  if (!el || typeof fn !== 'function') return;
  let id = null;
  let x0 = 0;
  let y0 = 0;
  let moved = false;
  let lastTouch = -1e9;
  const find = (list) => {
    for (let i = 0; i < list.length; i++) if (list[i].identifier === id) return list[i];
    return null;
  };
  const run = (e) => {
    if (el.disabled) return;
    try {
      fn(e);
    } catch (err) {
      console.error('[WILD HUNT] Помилка обробника кнопки:', err);
    }
  };
  el.addEventListener('touchstart', (e) => {
    const t = e.changedTouches[0];
    if (!t || e.touches.length > 1) {
      id = null;
      return;
    }
    id = t.identifier;
    x0 = t.clientX;
    y0 = t.clientY;
    moved = false;
  }, { passive: true });
  el.addEventListener('touchmove', (e) => {
    const t = id === null ? null : find(e.changedTouches);
    if (t && Math.hypot(t.clientX - x0, t.clientY - y0) > TAP_SLOP) moved = true;
  }, { passive: true });
  el.addEventListener('touchcancel', () => {
    id = null;
  }, { passive: true });
  el.addEventListener('touchend', (e) => {
    const t = id === null ? null : find(e.changedTouches);
    id = null;
    if (!t || moved || Math.hypot(t.clientX - x0, t.clientY - y0) > TAP_SLOP) return;
    const r = el.getBoundingClientRect();   // палець відпущено поза кнопкою — не натискання
    if (t.clientX < r.left - TAP_SLOP || t.clientX > r.right + TAP_SLOP || t.clientY < r.top - TAP_SLOP || t.clientY > r.bottom + TAP_SLOP) return;
    if (e.cancelable) e.preventDefault();
    lastTouch = performance.now();
    run(e);
  }, { passive: false });
  el.addEventListener('click', (e) => {
    if (performance.now() - lastTouch < TAP_CLICK_GUARD) {
      e.preventDefault();
      return;
    }
    run(e);
  });
}

// Головне меню з'являється одразу: профіль, спорядження, магазин, карта й налаштування працюють
// ще без 3D. Three.js і світ завантажуються лише після натискання «Полювати».
// Кроки, без яких меню може обійтися, виконуються кожен окремо: збій одного з них (сховище,
// визначення пристрою, профіль) більше не лишає всі кнопки без обробників.
function boot() {
  cacheDom();
  if (typeof BOOT.disarm === 'function') BOOT.disarm();   // game.js завантажено, меню готове
  if (BOOT.failed) return;
  if (BOOT.timeoutShown) {
    BOOT.timeoutShown = false;
    ui.errorScreen.classList.add('hidden');
  }
  const safe = (label, fn, fallback) => {
    try {
      return fn();
    } catch (err) {
      console.error(`[WILD HUNT] Запуск меню, крок «${label}»:`, err);
      return fallback;
    }
  };
  const isTouch = safe('сенсорний екран', detectTouch, navigator.maxTouchPoints > 0 || 'ontouchstart' in window);
  document.body.classList.toggle('is-touch', isTouch);
  const gl = probeWebGL();
  if (!gl.ok) {
    showFatal('webgl');
    return;
  }
  const settings = safe('налаштування', () => loadSettings(isTouch), null)
    || { sensitivity: 1, quality: 'auto', autoRes: true, sound: true, showFps: true, debug: false, time: 'auto', weather: 'auto', fpsCap: FPS_CAP_DEFAULT };
  const autoQuality = safe('якість', () => detectQuality(isTouch, gl.gpu), 'medium');
  const audio = new ForestAudio();
  audio.enabled = settings.sound;
  const profile = safe('профіль', loadProfile, null) || JSON.parse(JSON.stringify(PROFILE_DEFAULT));
  const env = { isTouch, settings, audio, gpu: gl.gpu, autoQuality, profile };
  // «Полювати» отримує обробник першим — до розділів меню.
  onTap(ui.btnStart, () => onPlay(env));
  try {
    env.menu = new Menu(env);
  } catch (err) {
    showFatal('init', `меню: ${err && err.message ? err.message : err}`);
    return;
  }
  ui.btnStart.disabled = false;
  // Індикатор «Завантаження гри…» з index.html (поки завантажувався game.js) більше не потрібен.
  ui.loading.classList.add('hidden');
  ui.loadingText.textContent = 'Підготовка…';
  BOOT.menuReady = true;
}

// «Полювати»: перше натискання завантажує Three.js і будує світ (з індикатором), потім починається
// полювання. Після повернення в головне меню світ лишається в пам'яті — наступний старт миттєвий.
function onPlay(env) {
  if (game) {
    if (game.state === 'menu') game.start();
    return;
  }
  if (worldLoading) return;
  worldLoading = true;
  // Звук і повноекранний режим браузер дозволяє вмикати лише в обробнику натискання.
  // Збій будь-якого з них (обмеження Safari на iPhone) не повинен зупиняти запуск гри.
  try {
    env.audio.init();
  } catch (err) {
    console.warn('[WILD HUNT] Звук не ввімкнено:', err);
  }
  try {
    if (env.isTouch) requestFullscreenIfUseful();
  } catch (err) {
    console.warn('[WILD HUNT] Повноекранний режим недоступний:', err);
  }
  ui.btnStart.classList.add('hidden');
  ui.loading.classList.remove('hidden');
  if (typeof BOOT.arm === 'function') BOOT.arm();
  loadWorld(env);
}

async function loadWorld(env) {
  setLoading(0.04, 'Завантаження Three.js…');
  THREE = await loadThree();
  if (!THREE) {
    showFatal('cdn');
    return;
  }
  setLoading(0.07, 'Читання списку ресурсів…');
  ASSET_MANIFEST = await loadManifest();
  try {
    await initGame(env);
  } catch (err) {
    console.error(err);
    showFatal('init', err && err.message ? err.message : String(err));
  }
}

function loadSettings(isTouch) {
  const defaults = {
    sensitivity: 1,
    quality: 'auto',
    autoRes: true,
    sound: true,
    showFps: true,
    debug: false,
    time: 'auto',
    weather: 'auto',
    fpsCap: FPS_CAP_DEFAULT,
  };
  const read = (key) => {
    try {
      const raw = window.localStorage.getItem(key);
      return raw ? JSON.parse(raw) : null;
    } catch (err) {
      return null;
    }
  };
  let s = read(SETTINGS_KEY);
  if (!s) {
    // Перенесення налаштувань першої версії (якість medium/high → «Високий»).
    const old = read(SETTINGS_KEY_V1);
    if (old) s = { ...old, quality: old.quality === 'low' ? 'low' : old.quality ? 'high' : 'auto' };
  }
  if (!s) return defaults;
  const quality = s.quality === 'max' ? 'ultra' : s.quality;   // «Максимальний» попередньої версії → «Ультра»
  return {
    sensitivity: clamp(Number(s.sensitivity) || 1, 0.3, 2.5),
    quality: quality === 'auto' || QUALITY[quality] ? quality : defaults.quality,
    autoRes: s.autoRes !== false,
    sound: s.sound !== false,
    showFps: s.showFps !== false,
    debug: s.debug === true,
    time: TIMES[s.time] ? s.time : defaults.time,
    weather: WEATHER[s.weather] || s.weather === 'auto' ? s.weather : defaults.weather,
    fpsCap: FPS_CAPS.includes(Number(s.fpsCap)) ? Number(s.fpsCap) : defaults.fpsCap,
  };
}

function saveSettings(settings) {
  try {
    window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  } catch (err) {
    console.warn('[WILD HUNT] Налаштування не збережено (сховище недоступне):', err);
  }
}

function detectTouch() {
  const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
  const mobileUA = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
  return (navigator.maxTouchPoints > 0 && coarse) || ('ontouchstart' in window && mobileUA);
}

// ═══════════════════════════ 3. МАТЕМАТИКА І ШУМ ═══════════════════════════

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const fract = (x) => x - Math.floor(x);
// Довжина вектора. Math.hypot не використовується: він виділяє пам'ять під аргументи при кожному виклику.
const len2 = (x, y) => Math.sqrt(x * x + y * y);
const len3 = (x, y, z) => Math.sqrt(x * x + y * y + z * z);
function smoothstep(e0, e1, x) {
  const t = clamp((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}
function wrapAngle(a) {
  let r = (a + Math.PI) % (Math.PI * 2);
  if (r < 0) r += Math.PI * 2;
  return r - Math.PI;
}
function damp(current, target, rate, dt) {
  return current + (target - current) * (1 - Math.exp(-rate * dt));
}
function pick(list, rand) {
  return list[Math.floor(rand() * list.length) % list.length];
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return function rand() {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Класичний 2D simplex-шум (Stefan Gustavson), значення приблизно в [-1, 1].
function createSimplex2D(rand) {
  const p = new Uint8Array(256);
  for (let i = 0; i < 256; i++) p[i] = i;
  for (let i = 255; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const t = p[i];
    p[i] = p[j];
    p[j] = t;
  }
  const perm = new Uint8Array(512);
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  const GX = [1, -1, 1, -1, 1, -1, 0, 0];
  const GY = [1, 1, -1, -1, 0, 0, 1, -1];
  const F2 = 0.5 * (Math.sqrt(3) - 1);
  const G2 = (3 - Math.sqrt(3)) / 6;
  return function noise(xin, yin) {
    const s = (xin + yin) * F2;
    const i = Math.floor(xin + s);
    const j = Math.floor(yin + s);
    const t = (i + j) * G2;
    const x0 = xin - (i - t);
    const y0 = yin - (j - t);
    const i1 = x0 > y0 ? 1 : 0;
    const j1 = x0 > y0 ? 0 : 1;
    const x1 = x0 - i1 + G2;
    const y1 = y0 - j1 + G2;
    const x2 = x0 - 1 + 2 * G2;
    const y2 = y0 - 1 + 2 * G2;
    const ii = i & 255;
    const jj = j & 255;
    let n = 0;
    let t0 = 0.5 - x0 * x0 - y0 * y0;
    if (t0 > 0) {
      const g = perm[ii + perm[jj]] & 7;
      t0 *= t0;
      n += t0 * t0 * (GX[g] * x0 + GY[g] * y0);
    }
    let t1 = 0.5 - x1 * x1 - y1 * y1;
    if (t1 > 0) {
      const g = perm[ii + i1 + perm[jj + j1]] & 7;
      t1 *= t1;
      n += t1 * t1 * (GX[g] * x1 + GY[g] * y1);
    }
    let t2 = 0.5 - x2 * x2 - y2 * y2;
    if (t2 > 0) {
      const g = perm[ii + 1 + perm[jj + 1]] & 7;
      t2 *= t2;
      n += t2 * t2 * (GX[g] * x2 + GY[g] * y2);
    }
    return 70 * n;
  };
}

function fbm(noise, x, y, octaves) {
  let amp = 1;
  let freq = 1;
  let sum = 0;
  let norm = 0;
  for (let o = 0; o < octaves; o++) {
    sum += amp * noise(x * freq, y * freq);
    norm += amp;
    amp *= 0.5;
    freq *= 2.03;
  }
  return sum / norm;
}

function hash3(x, y, z) {
  let h = (Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(z, 1440662683)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

// 3D value-шум у [0, 1] — для деформації каміння, крон і плям на корі.
function valueNoise3(x, y, z) {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const iz = Math.floor(z);
  const fx = x - ix;
  const fy = y - iy;
  const fz = z - iz;
  const ux = fx * fx * (3 - 2 * fx);
  const uy = fy * fy * (3 - 2 * fy);
  const uz = fz * fz * (3 - 2 * fz);
  const a = lerp(hash3(ix, iy, iz), hash3(ix + 1, iy, iz), ux);
  const b = lerp(hash3(ix, iy + 1, iz), hash3(ix + 1, iy + 1, iz), ux);
  const c = lerp(hash3(ix, iy, iz + 1), hash3(ix + 1, iy, iz + 1), ux);
  const d = lerp(hash3(ix, iy + 1, iz + 1), hash3(ix + 1, iy + 1, iz + 1), ux);
  return lerp(lerp(a, b, uy), lerp(c, d, uy), uz);
}

// Безшовний (тайловий) value-шум для текстур: значення [0, 1].
function tileableNoise(size, periodX, periodY, octaves, rand) {
  const out = new Float32Array(size * size);
  let amp = 1;
  for (let o = 0; o < octaves; o++) {
    const px = periodX << o;
    const py = periodY << o;
    const lattice = new Float32Array(px * py);
    for (let i = 0; i < lattice.length; i++) lattice[i] = rand();
    for (let y = 0; y < size; y++) {
      const fy = (y / size) * py;
      const iy = Math.floor(fy);
      const ty = fy - iy;
      const sy = ty * ty * (3 - 2 * ty);
      const y0 = (iy % py) * px;
      const y1 = ((iy + 1) % py) * px;
      for (let x = 0; x < size; x++) {
        const fx = (x / size) * px;
        const ix = Math.floor(fx);
        const tx = fx - ix;
        const sx = tx * tx * (3 - 2 * tx);
        const x0 = ix % px;
        const x1 = (ix + 1) % px;
        const top = lattice[y0 + x0] + (lattice[y0 + x1] - lattice[y0 + x0]) * sx;
        const bottom = lattice[y1 + x0] + (lattice[y1 + x1] - lattice[y1 + x0]) * sx;
        out[y * size + x] += amp * (top + (bottom - top) * sy);
      }
    }
    amp *= 0.5;
  }
  let min = Infinity;
  let max = -Infinity;
  for (let i = 0; i < out.length; i++) {
    if (out[i] < min) min = out[i];
    if (out[i] > max) max = out[i];
  }
  const range = max - min || 1;
  for (let i = 0; i < out.length; i++) out[i] = (out[i] - min) / range;
  return out;
}

function sampleTile(arr, size, x, y) {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const tx = x - x0;
  const ty = y - y0;
  const xi = ((x0 % size) + size) % size;
  const yi = ((y0 % size) + size) % size;
  const x1 = (xi + 1) % size;
  const y1 = (yi + 1) % size;
  const a = arr[yi * size + xi];
  const b = arr[yi * size + x1];
  const c = arr[y1 * size + xi];
  const d = arr[y1 * size + x1];
  return (a + (b - a) * tx) * (1 - ty) + (c + (d - c) * tx) * ty;
}

// ═══════════════════════════ 4. ПРОЦЕДУРНІ ТЕКСТУРИ ═══════════════════════════
/*
 * Усі текстури малюються кодом під час завантаження (без файлів): безшовні карти кольору з висотою
 * в альфа-каналі, карти нормалей із шорсткістю в альфа-каналі, картки хвої та листя з прозорістю.
 * Будь-яку з них можна замінити справжньою текстурою через assets/manifest.json.
 */

function makeCanvas(w, h) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  return canvas;
}

function canvasToTexture(canvas, { srgb = false, wrap = true, anisotropy = 1, flipY = true } = {}) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  if (wrap) {
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
  }
  tex.flipY = flipY;
  tex.anisotropy = anisotropy;
  tex.needsUpdate = true;
  return tex;
}

function grayTexture(size, valueFn, options) {
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const v = Math.round(clamp(valueFn(x, y), 0, 1) * 255);
      const o = (y * size + x) * 4;
      img.data[o] = v;
      img.data[o + 1] = v;
      img.data[o + 2] = v;
      img.data[o + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return canvasToTexture(canvas, options);
}

function dataTexture(data, w, h, { srgb = false, anisotropy = 1, wrap = true } = {}) {
  const tex = new THREE.DataTexture(data, w, h, THREE.RGBAFormat, THREE.UnsignedByteType);
  tex.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  tex.wrapS = wrap ? THREE.RepeatWrapping : THREE.ClampToEdgeWrapping;
  tex.wrapT = wrap ? THREE.RepeatWrapping : THREE.ClampToEdgeWrapping;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  tex.anisotropy = anisotropy;
  tex.needsUpdate = true;
  return tex;
}

// Безшовне малювання: примітиви біля краю повторюються з протилежного боку.
function createPainter(size, base) {
  const color = makeCanvas(size, size);
  const height = makeCanvas(size, size);
  const c = color.getContext('2d');
  const h = height.getContext('2d');
  c.fillStyle = base;
  c.fillRect(0, 0, size, size);
  h.fillStyle = '#808080';
  h.fillRect(0, 0, size, size);
  c.lineCap = 'round';
  h.lineCap = 'round';
  const wrap = (x, y, r, fn) => {
    for (let ox = -size; ox <= size; ox += size) {
      const px = x + ox;
      if (px < -r || px > size + r) continue;
      for (let oy = -size; oy <= size; oy += size) {
        const py = y + oy;
        if (py < -r || py > size + r) continue;
        fn(px, py);
      }
    }
  };
  return { size, color, height, c, h, wrap, k: (size / 512) * (size / 512), S: size / 512 };
}

// Пакетне малювання: один шлях на колір — тисячі штрихів малюються швидко.
function batchLines(p, list, colors, width, heightStyle) {
  const byColor = colors.map(() => []);
  for (const seg of list) byColor[seg[4]].push(seg);
  for (let ci = 0; ci < colors.length; ci++) {
    const segs = byColor[ci];
    if (!segs.length) continue;
    p.c.strokeStyle = colors[ci];
    p.c.lineWidth = width;
    p.c.beginPath();
    for (const [x0, y0, x1, y1] of segs) {
      p.wrap(Math.min(x0, x1), Math.min(y0, y1), Math.abs(x1 - x0) + Math.abs(y1 - y0) + width, (px, py) => {
        const dx = px - Math.min(x0, x1);
        const dy = py - Math.min(y0, y1);
        p.c.moveTo(x0 + dx, y0 + dy);
        p.c.lineTo(x1 + dx, y1 + dy);
      });
    }
    p.c.stroke();
  }
  if (heightStyle) {
    p.h.strokeStyle = heightStyle;
    p.h.lineWidth = width;
    p.h.beginPath();
    for (const [x0, y0, x1, y1] of list) {
      p.wrap(Math.min(x0, x1), Math.min(y0, y1), Math.abs(x1 - x0) + Math.abs(y1 - y0) + width, (px, py) => {
        const dx = px - Math.min(x0, x1);
        const dy = py - Math.min(y0, y1);
        p.h.moveTo(x0 + dx, y0 + dy);
        p.h.lineTo(x1 + dx, y1 + dy);
      });
    }
    p.h.stroke();
  }
}

function batchEllipses(p, list, colors, heightStyle) {
  const byColor = colors.map(() => []);
  for (const e of list) byColor[e[5]].push(e);
  const draw = (ctx, items) => {
    ctx.beginPath();
    for (const [x, y, rx, ry, rot] of items) {
      p.wrap(x, y, Math.max(rx, ry), (px, py) => {
        ctx.moveTo(px + Math.cos(rot) * rx, py + Math.sin(rot) * rx);
        ctx.ellipse(px, py, rx, ry, rot, 0, Math.PI * 2);
      });
    }
    ctx.fill();
  };
  for (let ci = 0; ci < colors.length; ci++) {
    if (!byColor[ci].length) continue;
    p.c.fillStyle = colors[ci];
    draw(p.c, byColor[ci]);
  }
  if (heightStyle) {
    p.h.fillStyle = heightStyle;
    draw(p.h, list);
  }
}

// Карта висот → нормалі (RGB) + шорсткість (A); колір + висота (A) — для змішування шарів землі.
function finishLayer(p, rand, opts) {
  const size = p.size;
  const {
    noise = 0.12, noisePeriod = 8, heightNoise = 0.2, strength = 3, rough = [0.88, 0.96], roughByHeight = 0,
    anisotropy = 1, extra = null,
  } = opts;
  const cd = p.c.getImageData(0, 0, size, size).data;
  const hd = p.h.getImageData(0, 0, size, size).data;
  const n1 = tileableNoise(size, noisePeriod, noisePeriod, 4, rand);
  const n2 = tileableNoise(size, noisePeriod * 4, noisePeriod * 4, 2, rand);
  const H = new Float32Array(size * size);
  const albedo = new Uint8Array(size * size * 4);
  for (let i = 0; i < size * size; i++) {
    const k = 1 + ((n1[i] - 0.5) * 2 * noise) + (n2[i] - 0.5) * noise * 0.6;
    let r = cd[i * 4] * k;
    let g = cd[i * 4 + 1] * k;
    let b = cd[i * 4 + 2] * k;
    let hv = hd[i * 4] / 255 + (n1[i] - 0.5) * heightNoise + (n2[i] - 0.5) * heightNoise * 0.4;
    if (extra) {
      const o = extra(i, n1[i], n2[i], r, g, b, hv);
      if (o) {
        r = o[0];
        g = o[1];
        b = o[2];
        hv = o[3];
      }
    }
    albedo[i * 4] = clamp(r, 0, 255);
    albedo[i * 4 + 1] = clamp(g, 0, 255);
    albedo[i * 4 + 2] = clamp(b, 0, 255);
    H[i] = clamp(hv, 0, 1);
    albedo[i * 4 + 3] = H[i] * 255;
  }
  const normal = new Uint8Array(size * size * 4);
  const mask = size - 1;
  for (let y = 0; y < size; y++) {
    const yu = ((y - 1) & mask) * size;
    const yd = ((y + 1) & mask) * size;
    const yr = y * size;
    for (let x = 0; x < size; x++) {
      const i = yr + x;
      const nx = (H[yr + ((x - 1) & mask)] - H[yr + ((x + 1) & mask)]) * strength;
      const ny = (H[yu + x] - H[yd + x]) * strength;
      const l = len3(nx, ny, 1);
      normal[i * 4] = (nx / l * 0.5 + 0.5) * 255;
      normal[i * 4 + 1] = (ny / l * 0.5 + 0.5) * 255;
      normal[i * 4 + 2] = (1 / l * 0.5 + 0.5) * 255;
      const rv = lerp(rough[0], rough[1], n1[i]) - roughByHeight * (H[i] - 0.5);
      normal[i * 4 + 3] = clamp(rv, 0.05, 1) * 255;
    }
  }
  return {
    albedo: dataTexture(albedo, size, size, { srgb: true, anisotropy }),
    normal: dataTexture(normal, size, size, { anisotropy }),
  };
}

function rndSeg(rand, size, count, minLen, maxLen, colorCount, angle = null, spread = Math.PI) {
  const out = [];
  for (let i = 0; i < count; i++) {
    const x = rand() * size;
    const y = rand() * size;
    const a = angle === null ? rand() * Math.PI * 2 : angle + (rand() - 0.5) * spread;
    const l = minLen + rand() * (maxLen - minLen);
    out.push([x, y, x + Math.cos(a) * l, y + Math.sin(a) * l, Math.floor(rand() * colorCount)]);
  }
  return out;
}

function rndEllipses(rand, size, count, minR, maxR, colorCount, squash = 0.6) {
  const out = [];
  for (let i = 0; i < count; i++) {
    const r = minR + rand() * (maxR - minR);
    out.push([rand() * size, rand() * size, r, r * (squash + rand() * (1 - squash)), rand() * Math.PI, Math.floor(rand() * colorCount)]);
  }
  return out;
}

// Шар 0: ґрунт луки з дрібною травою й конюшиною.
function paintGrassGround(size, rand, anisotropy) {
  const p = createPainter(size, '#3c4a20');
  const { k, S } = p;
  batchEllipses(p, rndEllipses(rand, size, 240 * k, 6 * S, 22 * S, 3, 0.5), ['#34401d', '#4a5a27', '#56552e'], null);
  const greens = ['#4d6a26', '#5b7a2c', '#3e5a22', '#66862f', '#728c36', '#56702a', '#7f8a46'];
  batchLines(p, rndSeg(rand, size, 2600 * k, 5 * S, 15 * S, greens.length), greens, 1.3 * S, 'rgba(255,255,255,0.22)');
  batchLines(p, rndSeg(rand, size, 2600 * k, 4 * S, 11 * S, greens.length), greens, 0.9 * S, 'rgba(255,255,255,0.16)');
  batchEllipses(p, rndEllipses(rand, size, 220 * k, 1.6 * S, 3.2 * S, 2, 0.8), ['#5d7d30', '#6f8f38'], 'rgba(255,255,255,0.25)');
  return finishLayer(p, rand, { noise: 0.14, strength: 3, rough: [0.86, 0.97], anisotropy });
}

// Шар 1: лісова підстилка — хвоя, опале листя, гілочки, мох.
function paintForestFloor(size, rand, anisotropy) {
  const p = createPainter(size, '#45362a');
  const { k, S } = p;
  batchEllipses(p, rndEllipses(rand, size, 180 * k, 8 * S, 26 * S, 2, 0.5), ['#3a2d22', '#54422f'], null);
  const needles = ['#8a5a2e', '#6e4a2a', '#a0703a', '#3a2a1a', '#7e5c36'];
  batchLines(p, rndSeg(rand, size, 5200 * k, 5 * S, 12 * S, needles.length), needles, 1.0 * S, 'rgba(255,255,255,0.14)');
  const leaves = rndEllipses(rand, size, 420 * k, 3 * S, 7.5 * S, 4, 0.45);
  batchEllipses(p, leaves, ['#7a5a30', '#9a7a3a', '#5a4426', '#86622e'], 'rgba(255,255,255,0.3)');
  const ribs = leaves.map(([x, y, rx, , rot]) => [x - Math.cos(rot) * rx * 0.85, y - Math.sin(rot) * rx * 0.85, x + Math.cos(rot) * rx * 0.85, y + Math.sin(rot) * rx * 0.85, 0]);
  batchLines(p, ribs, ['rgba(50,34,20,0.55)'], 0.7 * S, null);
  batchLines(p, rndSeg(rand, size, 90 * k, 18 * S, 40 * S, 2), ['#2f241a', '#4a3826'], 2.4 * S, 'rgba(255,255,255,0.35)');
  return finishLayer(p, rand, {
    noise: 0.12, strength: 3.4, rough: [0.8, 0.95], anisotropy,
    extra: (i, n1, n2, r, g, b, hv) => {
      const moss = smoothstep(0.6, 0.75, n2 * 0.7 + n1 * 0.3);
      if (moss <= 0) return null;
      return [lerp(r, 72, moss), lerp(g, 92, moss), lerp(b, 40, moss), hv + moss * 0.1];
    },
  });
}

// Шар 2: утоптана ґрунтова стежка з камінцями.
function paintDirt(size, rand, anisotropy) {
  const p = createPainter(size, '#6f5a41');
  const { k, S } = p;
  batchEllipses(p, rndEllipses(rand, size, 220 * k, 6 * S, 20 * S, 2, 0.5), ['#5f4c37', '#7d6850'], null);
  const pebbles = rndEllipses(rand, size, 1100 * k, 1.2 * S, 3.8 * S, 4, 0.55);
  batchEllipses(p, pebbles, ['#8a7d6b', '#6b6052', '#9c8f7c', '#5d544a'], 'rgba(255,255,255,0.45)');
  batchEllipses(p, pebbles.map(([x, y, rx, ry, rot]) => [x - rx * 0.2, y - ry * 0.25, rx * 0.45, ry * 0.4, rot, 0]), ['rgba(255,250,235,0.18)'], 'rgba(255,255,255,0.25)');
  batchLines(p, rndSeg(rand, size, 70 * k, 8 * S, 22 * S, 1), ['rgba(40,30,20,0.6)'], 1.1 * S, 'rgba(0,0,0,0.35)');
  return finishLayer(p, rand, { noise: 0.1, strength: 4, rough: [0.84, 0.96], roughByHeight: 0.3, anisotropy });
}

// Шар 3: скеля з тріщинами й лишайником.
function paintRock(size, rand, anisotropy) {
  const p = createPainter(size, '#57544e');
  const { k, S } = p;
  batchEllipses(p, rndEllipses(rand, size, 160 * k, 10 * S, 40 * S, 3, 0.4), ['#4a4743', '#69655e', '#55524c'], null);
  const cracks = [];
  for (let i = 0; i < 60 * k; i++) {
    let x = rand() * size;
    let y = rand() * size;
    let a = rand() * Math.PI * 2;
    const n = 4 + Math.floor(rand() * 5);
    for (let s = 0; s < n; s++) {
      a += (rand() - 0.5) * 1.1;
      const l = (8 + rand() * 16) * S;
      const nx = x + Math.cos(a) * l;
      const ny = y + Math.sin(a) * l;
      cracks.push([x, y, nx, ny, 0]);
      x = nx;
      y = ny;
    }
  }
  batchLines(p, cracks, ['#3c3a36'], 1.6 * S, 'rgba(0,0,0,0.55)');
  batchEllipses(p, rndEllipses(rand, size, 300 * k, 1.5 * S, 4.5 * S, 3, 0.6), ['rgba(120,124,70,0.75)', 'rgba(140,128,82,0.6)', 'rgba(84,104,52,0.8)'], null);
  batchEllipses(p, rndEllipses(rand, size, 70 * k, 8 * S, 22 * S, 1, 0.5), ['rgba(62,84,38,0.55)'], null);
  return finishLayer(p, rand, { noise: 0.16, noisePeriod: 6, heightNoise: 0.45, strength: 5, rough: [0.76, 0.92], anisotropy });
}

// Кора хвойних і дуба: вертикальні пластини з борознами (видовжений шум).
function paintBark(size, rand, anisotropy) {
  const n = tileableNoise(size, 14, 3, 4, rand);
  const f = tileableNoise(size, 48, 12, 2, rand);
  const albedo = new Uint8Array(size * size * 4);
  const H = new Float32Array(size * size);
  for (let i = 0; i < size * size; i++) {
    const plate = smoothstep(0.32, 0.7, n[i]);
    const h = plate * 0.75 + f[i] * 0.25;
    H[i] = h;
    const shade = 0.55 + 0.6 * h;
    albedo[i * 4] = clamp(112 * shade + (f[i] - 0.5) * 30, 0, 255);
    albedo[i * 4 + 1] = clamp(92 * shade + (f[i] - 0.5) * 24, 0, 255);
    albedo[i * 4 + 2] = clamp(74 * shade + (f[i] - 0.5) * 18, 0, 255);
    albedo[i * 4 + 3] = h * 255;
  }
  return { albedo: dataTexture(albedo, size, size, { srgb: true, anisotropy }), normal: normalFromHeight(H, size, 7, [0.86, 0.97], anisotropy) };
}

// Кора берези: біла з горизонтальними темними сочевичками й плямами.
function paintBirchBark(size, rand, anisotropy) {
  const p = createPainter(size, '#e6e2d6');
  const { k, S } = p;
  batchEllipses(p, rndEllipses(rand, size, 120 * k, 6 * S, 18 * S, 2, 0.5), ['#d8d3c6', '#f0ede4'], null);
  const dashes = [];
  for (let i = 0; i < 420 * k; i++) {
    const x = rand() * size;
    const y = rand() * size;
    const l = (5 + rand() * 18) * S;
    dashes.push([x, y, x + l, y + (rand() - 0.5) * 1.5 * S, rand() < 0.75 ? 0 : 1]);
  }
  batchLines(p, dashes, ['#2a2622', '#5a544c'], 1.6 * S, 'rgba(0,0,0,0.4)');
  const patches = [];
  for (let i = 0; i < 26 * k; i++) {
    const r = (6 + rand() * 18) * S;
    patches.push([rand() * size, rand() * size, r * (1.4 + rand()), r * (0.35 + rand() * 0.3), (rand() - 0.5) * 0.3, 0]);
  }
  batchEllipses(p, patches, ['#35302b'], 'rgba(0,0,0,0.3)');
  return finishLayer(p, rand, { noise: 0.06, strength: 2.5, rough: [0.7, 0.86], anisotropy });
}

function normalFromHeight(H, size, strength, rough, anisotropy, roughNoise = null) {
  const normal = new Uint8Array(size * size * 4);
  const mask = size - 1;
  for (let y = 0; y < size; y++) {
    const yu = ((y - 1) & mask) * size;
    const yd = ((y + 1) & mask) * size;
    const yr = y * size;
    for (let x = 0; x < size; x++) {
      const i = yr + x;
      const nx = (H[yr + ((x - 1) & mask)] - H[yr + ((x + 1) & mask)]) * strength;
      const ny = (H[yu + x] - H[yd + x]) * strength;
      const l = len3(nx, ny, 1);
      normal[i * 4] = (nx / l * 0.5 + 0.5) * 255;
      normal[i * 4 + 1] = (ny / l * 0.5 + 0.5) * 255;
      normal[i * 4 + 2] = (1 / l * 0.5 + 0.5) * 255;
      const t = roughNoise ? roughNoise[i] : 1 - H[i];
      normal[i * 4 + 3] = clamp(lerp(rough[0], rough[1], t), 0.05, 1) * 255;
    }
  }
  return dataTexture(normal, size, size, { anisotropy });
}

// Деревина (приклад гвинтівки, дошки й колоди бази): сірувато-тепла, колір задає матеріал.
function paintWood(size, rand, anisotropy) {
  const n = tileableNoise(size, 2, 20, 3, rand);
  const f = tileableNoise(size, 8, 64, 2, rand);
  const albedo = new Uint8Array(size * size * 4);
  const H = new Float32Array(size * size);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = y * size + x;
      const ring = 0.5 + 0.5 * Math.sin((y / size * 34 + n[i] * 7) * Math.PI * 2);
      const grain = Math.pow(ring, 3) * 0.6 + f[i] * 0.4;
      H[i] = 0.6 - grain * 0.25;
      const v = 0.72 + 0.28 * (1 - grain);
      albedo[i * 4] = clamp(205 * v, 0, 255);
      albedo[i * 4 + 1] = clamp(180 * v, 0, 255);
      albedo[i * 4 + 2] = clamp(150 * v, 0, 255);
      albedo[i * 4 + 3] = 255;
    }
  }
  return { albedo: dataTexture(albedo, size, size, { srgb: true, anisotropy }), normal: normalFromHeight(H, size, 2.2, [0.55, 0.8], anisotropy) };
}

// Хвилі для води: сума синусоїд із цілими частотами (безшовно) + дрібний шум.
function paintWaterNormal(size, rand) {
  const H = new Float32Array(size * size);
  const n = tileableNoise(size, 16, 16, 3, rand);
  const waves = [];
  for (let i = 0; i < 9; i++) {
    waves.push({ fx: Math.round((rand() - 0.5) * 14), fy: Math.round((rand() - 0.5) * 14) || 1, a: 0.4 / (1 + i * 0.35), ph: rand() * Math.PI * 2 });
  }
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      let h = 0;
      for (const w of waves) h += w.a * Math.sin(((w.fx * x + w.fy * y) / size) * Math.PI * 2 + w.ph);
      H[y * size + x] = h * 0.25 + 0.5 + (n[y * size + x] - 0.5) * 0.3;
    }
  }
  return normalFromHeight(H, size, 3.2, [0.1, 0.1], 1);
}

// ── Картки рослин: малюються на canvas із прозорістю, потім кольори «розтікаються» в прозорі
// пікселі (щоб на краях листя не з'являлись темні ореоли), а mip-рівні будуються зі збереженням
// покриття: інакше на відстані альфа-тест «з'їдає» хвою й листя, і крони стають прозорими.

const FOLIAGE_CUTOFF = 0.5;          // поріг альфа-тесту для листя, хвої та імпостерів

function foliageCanvas(w, h) {
  const cv = makeCanvas(w, h);
  const ctx = cv.getContext('2d');
  ctx.clearRect(0, 0, w, h);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  return { cv, ctx, w, h };
}

// Колір прозорих пікселів = середнє сусідніх непрозорих (кілька проходів).
function dilateColors(data, w, h, passes) {
  let filled = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) filled[i] = data[i * 4 + 3] > 12 ? 1 : 0;
  for (let pass = 0; pass < passes; pass++) {
    const next = filled.slice();
    let changed = false;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (filled[i]) continue;
        let r = 0;
        let g = 0;
        let b = 0;
        let n = 0;
        for (let dy = -1; dy <= 1; dy++) {
          const yy = y + dy;
          if (yy < 0 || yy >= h) continue;
          for (let dx = -1; dx <= 1; dx++) {
            const xx = x + dx;
            if (xx < 0 || xx >= w) continue;
            const j = yy * w + xx;
            if (!filled[j]) continue;
            r += data[j * 4];
            g += data[j * 4 + 1];
            b += data[j * 4 + 2];
            n++;
          }
        }
        if (n) {
          data[i * 4] = r / n;
          data[i * 4 + 1] = g / n;
          data[i * 4 + 2] = b / n;
          next[i] = 1;
          changed = true;
        }
      }
    }
    filled = next;
    if (!changed) break;
  }
}

// Mip-рівні з корекцією альфи (метод І. Castaño): частка пікселів, що проходять альфа-тест,
// на кожному рівні така сама, як на повному розмірі.
function coverageMipmaps(data, w, h, cutoff) {
  const passRate = (d, n, scale) => {
    const lim = cutoff * 255;
    let c = 0;
    for (let i = 3; i < n * 4; i += 4) if (d[i] * scale > lim) c++;
    return c / n;
  };
  const target = passRate(data, w * h, 1);
  const levels = [{ data, width: w, height: h }];
  let src = data;
  let sw = w;
  let sh = h;
  while (sw > 1 || sh > 1) {
    const dw = Math.max(1, sw >> 1);
    const dh = Math.max(1, sh >> 1);
    const dst = new Uint8Array(dw * dh * 4);
    for (let y = 0; y < dh; y++) {
      for (let x = 0; x < dw; x++) {
        let r = 0;
        let g = 0;
        let b = 0;
        let a = 0;
        let ws = 0;
        for (let oy = 0; oy < 2; oy++) {
          const sy = Math.min(sh - 1, y * 2 + oy);
          for (let ox = 0; ox < 2; ox++) {
            const sx = Math.min(sw - 1, x * 2 + ox);
            const i = (sy * sw + sx) * 4;
            const wgt = src[i + 3] + 6;
            r += src[i] * wgt;
            g += src[i + 1] * wgt;
            b += src[i + 2] * wgt;
            a += src[i + 3];
            ws += wgt;
          }
        }
        const o = (y * dw + x) * 4;
        dst[o] = r / ws;
        dst[o + 1] = g / ws;
        dst[o + 2] = b / ws;
        dst[o + 3] = a / 4;
      }
    }
    // Масштаб альфи, за якого покриття збігається з початковим (бінарний пошук).
    let lo = 0.6;
    let hi = 6;
    for (let it = 0; it < 14; it++) {
      const m = (lo + hi) / 2;
      if (passRate(dst, dw * dh, m) < target) lo = m;
      else hi = m;
    }
    const scale = dw * dh <= 4 ? 1 : (lo + hi) / 2;
    const out = dst.slice();
    for (let i = 3; i < out.length; i += 4) out[i] = Math.min(255, out[i] * scale);
    levels.push({ data: out, width: dw, height: dh });
    src = dst;
    sw = dw;
    sh = dh;
  }
  return levels;
}

// Текстура з прозорістю: «розтікання» кольору + mip-рівні зі збереженням покриття.
function alphaTexture(data, w, h, anisotropy, srgb = true) {
  dilateColors(data, w, h, 8);
  const tex = new THREE.DataTexture(data, w, h, THREE.RGBAFormat, THREE.UnsignedByteType);
  tex.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.mipmaps = coverageMipmaps(data, w, h, FOLIAGE_CUTOFF);
  tex.generateMipmaps = false;
  tex.anisotropy = anisotropy;
  tex.needsUpdate = true;
  return tex;
}

function finishFoliage(f, anisotropy) {
  const { w, h } = f;
  const src = f.ctx.getImageData(0, 0, w, h).data;
  const data = new Uint8Array(w * h * 4);
  // Перевертаємо рядки: низ малюнка — v = 0 (як у звичайних текстур).
  for (let y = 0; y < h; y++) data.set(src.subarray((h - 1 - y) * w * 4, (h - y) * w * 4), y * w * 4);
  return alphaTexture(data, w, h, anisotropy);
}

// Колір із палітри (від темного до світлого) за t ∈ [0, 1] з невеликим випадковим відхиленням.
function paletteColor(pal, t, rand, jitter = 0.06) {
  const x = clamp(t, 0, 1) * (pal.length - 1);
  const i = Math.min(pal.length - 2, Math.floor(x));
  const f = x - i;
  const a = pal[i];
  const b = pal[i + 1];
  const j = 1 + (rand() - 0.5) * jitter * 2;
  const hue = (rand() - 0.5) * jitter * 40;
  const r = clamp((a[0] + (b[0] - a[0]) * f) * j + hue, 0, 255);
  const g = clamp((a[1] + (b[1] - a[1]) * f) * j, 0, 255);
  const bl = clamp((a[2] + (b[2] - a[2]) * f) * j - hue * 0.5, 0, 255);
  return `rgb(${r | 0},${g | 0},${bl | 0})`;
}

const hexRgb = (hex) => [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];

// Обрис листка вздовж жилки довжиною len: дуб — лопатевий, береза — трикутно-яйцеподібний
// з пилчастим краєм, інші — яйцеподібний із загостреним кінчиком.
function leafShape(ctx, x, y, len, wid, ang, kind) {
  const ca = Math.cos(ang);
  const sa = Math.sin(ang);
  const N = kind === 'oak' ? 22 : 12;
  const half = [];
  for (let i = 1; i < N; i++) {
    const t = i / N;
    let w;
    if (kind === 'oak') w = wid * Math.sin(Math.PI * Math.pow(t, 0.7)) * (0.58 + 0.42 * Math.abs(Math.cos(Math.PI * 4.5 * t)));
    else if (kind === 'birch') w = wid * Math.sin(Math.PI * Math.pow(t, 0.5)) * (i % 2 ? 1 : 0.9);
    else w = wid * Math.sin(Math.PI * Math.pow(t, 0.78)) * (i % 2 ? 1 : 0.95);
    half.push([t * len, w]);
  }
  ctx.moveTo(x, y);
  for (const [u, v] of half) ctx.lineTo(x + ca * u - sa * v, y + sa * u + ca * v);
  ctx.lineTo(x + ca * len, y + sa * len);
  for (let i = half.length - 1; i >= 0; i--) {
    const [u, v] = half[i];
    ctx.lineTo(x + ca * u + sa * v, y + sa * u - ca * v);
  }
  ctx.closePath();
}

// Пакет відрізків одного кольору — тисячі хвоїнок малюються кількома викликами stroke().
function strokeBatches(ctx, batches, width) {
  ctx.lineWidth = width;
  for (const [color, segs] of batches) {
    if (!segs.length) continue;
    ctx.strokeStyle = color;
    ctx.beginPath();
    for (let i = 0; i < segs.length; i += 4) {
      ctx.moveTo(segs[i], segs[i + 1]);
      ctx.lineTo(segs[i + 2], segs[i + 3]);
    }
    ctx.stroke();
  }
}

// Гілка ялини (картка 256×128): основа ліворуч (u = 0), кінчик праворуч. Пласка «лапа» з бічних
// гілочок, густа темна хвоя, світліші молоді прирости на кінцях; під хвоєю — темна підкладка,
// щоб гілка лишалася щільною й на відстані.
function paintSpruceBranch(rand, anisotropy) {
  const W = 256;
  const H = 128;
  const f = foliageCanvas(W, H);
  const ctx = f.ctx;
  const mid = H / 2;
  const axisY = (x) => mid + Math.sin((x / W) * 2.4) * 4 - (x / W) * 4;
  const main = [];
  for (let i = 0; i <= 16; i++) {
    const x = 2 + i * 15.4;
    main.push([x, axisY(x)]);
  }
  const twigs = [{ pts: main, w: 2.4, young: 0.12 }];
  for (let i = 2; i < 16; i++) {
    const [bx, by] = main[i];
    const tp = i / 16;
    const env = Math.sin(Math.PI * Math.pow(tp, 0.72));
    for (const side of [-1, 1]) {
      if (rand() < 0.08) continue;
      const len = (12 + 48 * env) * (0.82 + rand() * 0.3);
      const a = side * (0.8 + rand() * 0.3);
      const a2 = a * (0.55 + rand() * 0.2);
      const p1 = [bx + Math.cos(a) * len * 0.5, by + Math.sin(a) * len * 0.5];
      const p2 = [p1[0] + Math.cos(a2) * len * 0.5, p1[1] + Math.sin(a2) * len * 0.5];
      twigs.push({ pts: [[bx, by], p1, p2], w: 1.1, young: 0.32 });
      if (len > 26) {
        for (let k = 0; k < 2; k++) {
          const t = 0.35 + k * 0.3 + rand() * 0.1;
          const sx = bx + (p2[0] - bx) * t;
          const sy = by + (p2[1] - by) * t;
          const a3 = a + side * (0.7 + rand() * 0.3);
          const l3 = len * (0.28 + rand() * 0.12);
          twigs.push({ pts: [[sx, sy], [sx + Math.cos(a3) * l3, sy + Math.sin(a3) * l3]], w: 0.8, young: 0.45 });
        }
      }
    }
  }
  // Підкладка.
  ctx.strokeStyle = '#142616';
  for (const tw of twigs) {
    if (tw === twigs[0]) continue;
    ctx.lineWidth = tw.w > 1 ? 7 : 5;
    ctx.beginPath();
    ctx.moveTo(tw.pts[0][0], tw.pts[0][1]);
    for (const pt of tw.pts.slice(1)) ctx.lineTo(pt[0], pt[1]);
    ctx.stroke();
  }
  // Хвоя.
  const old = ['#1b3219', '#22401f', '#2a4a24', '#1f3a1d', '#304f28', '#284524'].map((c) => [c, []]);
  const young = ['#3f6a33', '#4c7a3a', '#5a8642', '#46703a'].map((c) => [c, []]);
  for (const tw of twigs) {
    let total = 0;
    for (let s = 0; s < tw.pts.length - 1; s++) total += len2(tw.pts[s + 1][0] - tw.pts[s][0], tw.pts[s + 1][1] - tw.pts[s][1]);
    let run = 0;
    for (let s = 0; s < tw.pts.length - 1; s++) {
      const [x0, y0] = tw.pts[s];
      const [x1, y1] = tw.pts[s + 1];
      const seg = len2(x1 - x0, y1 - y0);
      const a = Math.atan2(y1 - y0, x1 - x0);
      for (let d = 0; d < seg; d += 1.4) {
        const along = (run + d) / Math.max(total, 1);
        const x = x0 + Math.cos(a) * d;
        const y = y0 + Math.sin(a) * d;
        const isYoung = along > 1 - tw.young && rand() < 0.85;
        const pool = isYoung ? young : old;
        const nl = (4.5 + rand() * 3.5) * (1 - along * 0.3) * (tw === twigs[0] ? 1.15 : 1);
        for (const sgn of [-1, 1]) {
          const na = a + sgn * (0.95 + rand() * 0.45) * 0.9;
          const segs = pool[Math.floor(rand() * pool.length)][1];
          segs.push(x, y, x + Math.cos(na) * nl, y + Math.sin(na) * nl);
        }
      }
      run += seg;
    }
  }
  strokeBatches(ctx, old, 1.25);
  strokeBatches(ctx, young, 1.2);
  // Гілочки місцями проглядають крізь хвою.
  ctx.strokeStyle = '#3a2a1c';
  for (const tw of twigs) {
    ctx.lineWidth = tw.w;
    ctx.beginPath();
    ctx.moveTo(tw.pts[0][0], tw.pts[0][1]);
    for (const pt of tw.pts.slice(1)) ctx.lineTo(pt[0], pt[1]);
    ctx.globalAlpha = tw === twigs[0] ? 0.9 : 0.45;
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  return finishFoliage(f, anisotropy);
}

// «Спідниця» ялини (256×256, безшовна по горизонталі): угорі — стовбур, донизу розходяться
// гілки з густою темною хвоєю, світлі молоді прирости на кінцях, рваний нижній край.
// Кожен ярус крони — конус, обгорнутий цією текстурою: з будь-якого боку видно щільну хвою.
function paintSpruceSkirt(rand, anisotropy) {
  const W = 256;
  const H = 256;
  const f = foliageCanvas(W, H);
  const ctx = f.ctx;
  const wrapX = (fn) => {
    for (const ox of [-W, 0, W]) fn(ox);
  };
  // Темна глибина крони з нерівним нижнім краєм.
  const edge = [];
  for (let x = 0; x <= W; x += 8) edge.push([x, H * (0.62 + 0.08 * Math.sin(x * 0.07 + 1.3) + 0.05 * (rand() - 0.5))]);
  edge[edge.length - 1][1] = edge[0][1];
  const grad = ctx.createLinearGradient(0, 0, 0, H * 0.72);
  grad.addColorStop(0, '#0b160c');
  grad.addColorStop(1, '#16291a');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(W, 0);
  for (let i = edge.length - 1; i >= 0; i--) ctx.lineTo(edge[i][0], edge[i][1]);
  ctx.closePath();
  ctx.fill();
  // Гілки: від верху (стовбура) вниз, з бічними гілочками.
  const twigs = [];
  const B = 7;
  for (let b = 0; b < B; b++) {
    const x0 = (b + 0.5) / B * W + (rand() - 0.5) * 14;
    const sway = (rand() - 0.5) * 30;
    const len = H * (0.86 + rand() * 0.12);
    const pts = [];
    for (let i = 0; i <= 10; i++) {
      const t = i / 10;
      pts.push([x0 + sway * t * t, t * len]);
    }
    twigs.push({ pts, w: 2.2, young: 0.14, main: true });
    for (let i = 2; i < 10; i++) {
      const [bx, by] = pts[i];
      const t = i / 10;
      for (const side of [-1, 1]) {
        if (rand() < 0.15) continue;
        const l = (14 + 22 * Math.sin(Math.PI * t)) * (0.8 + rand() * 0.4);
        const a = Math.PI / 2 + side * (0.75 + rand() * 0.3);
        const p1 = [bx + Math.cos(a) * l * 0.55, by + Math.sin(a) * l * 0.55];
        const a2 = a - side * 0.35;
        const p2 = [p1[0] + Math.cos(a2) * l * 0.45, p1[1] + Math.sin(a2) * l * 0.45];
        twigs.push({ pts: [[bx, by], p1, p2], w: 1.0, young: 0.4 });
      }
    }
  }
  // Підкладка під хвою — щоб гілки не просвічували на відстані.
  ctx.strokeStyle = '#122414';
  for (const tw of twigs) {
    ctx.lineWidth = tw.main ? 9 : 6;
    wrapX((ox) => {
      ctx.beginPath();
      ctx.moveTo(tw.pts[0][0] + ox, tw.pts[0][1]);
      for (const pt of tw.pts.slice(1)) ctx.lineTo(pt[0] + ox, pt[1]);
      ctx.stroke();
    });
  }
  const old = ['#172c16', '#1d371b', '#24411f', '#1a3219', '#2b4a24', '#22401e'].map((c) => [c, []]);
  const young = ['#3a6530', '#477437', '#55833f', '#41693a'].map((c) => [c, []]);
  for (const tw of twigs) {
    let total = 0;
    for (let k = 0; k < tw.pts.length - 1; k++) total += len2(tw.pts[k + 1][0] - tw.pts[k][0], tw.pts[k + 1][1] - tw.pts[k][1]);
    let run = 0;
    for (let k = 0; k < tw.pts.length - 1; k++) {
      const [x0, y0] = tw.pts[k];
      const [x1, y1] = tw.pts[k + 1];
      const seg = len2(x1 - x0, y1 - y0);
      const a = Math.atan2(y1 - y0, x1 - x0);
      for (let d = 0; d < seg; d += 1.5) {
        const along = (run + d) / Math.max(total, 1);
        const x = x0 + Math.cos(a) * d;
        const y = y0 + Math.sin(a) * d;
        const isYoung = along > 1 - tw.young && rand() < 0.85 && y > H * 0.45;
        const pool = isYoung ? young : old;
        const nl = (5 + rand() * 3.5) * (1 - along * 0.25);
        for (const sgn of [-1, 1]) {
          const na = a + sgn * (0.9 + rand() * 0.5) * 0.9 + 0.25;
          const segs = pool[Math.floor(rand() * pool.length)][1];
          for (const ox of [-W, 0, W]) segs.push(x + ox, y, x + ox + Math.cos(na) * nl, y + Math.sin(na) * nl);
        }
      }
      run += seg;
    }
  }
  strokeBatches(ctx, old, 1.35);
  strokeBatches(ctx, young, 1.25);
  return finishFoliage(f, anisotropy);
}

// Гілка сосни (256×256): основа знизу посередині, гілочки закінчуються «щітками» довгої
// сизувато-зеленої хвої (тонкі штрихи, сотні голок у кожній щітці).
function paintPineTuft(rand, anisotropy) {
  const W = 256;
  const H = 256;
  const f = foliageCanvas(W, H);
  const ctx = f.ctx;
  const brushes = [];
  for (let i = 0; i < 9; i++) {
    const a = -Math.PI / 2 + (i / 8 - 0.5) * 2.3 + (rand() - 0.5) * 0.25;
    const d = 46 + rand() * 50 + (i % 2) * 18;
    brushes.push([128 + Math.cos(a) * d, 150 + Math.sin(a) * d * 1.05, a, 0.7 + rand() * 0.35]);
  }
  ctx.strokeStyle = '#4a3322';
  ctx.lineWidth = 3.2;
  ctx.beginPath();
  for (const [bx, by] of brushes) {
    ctx.moveTo(128, 254);
    ctx.quadraticCurveTo(128 + (bx - 128) * 0.3, 200, bx, by + 6);
  }
  ctx.stroke();
  for (const [bx, by, ang, sc] of brushes) {
    ctx.fillStyle = '#1a2e1b';
    ctx.beginPath();
    ctx.ellipse(bx, by, 17 * sc, 22 * sc, ang + Math.PI / 2, 0, Math.PI * 2);
    ctx.fill();
  }
  const pal = ['#22392200', '#2a4229', '#344f30', '#3f5c38', '#4a6a40', '#56764a', '#638350'].slice(1).map((c) => [c, []]);
  for (const [bx, by, ang, sc] of brushes) {
    const ax = Math.cos(ang);
    const ay = Math.sin(ang);
    for (let i = 0; i < 420 * sc; i++) {
      const t = rand() * 1.15 - 0.4;
      const sx = bx + ax * t * 22 * sc;
      const sy = by + ay * t * 22 * sc;
      const a = ang + (rand() - 0.5) * 3.0;
      const l = (16 + rand() * 13) * sc;
      const shade = clamp(0.2 + rand() * 0.55 + Math.cos(a - ang) * 0.22 - Math.max(0, Math.sin(a)) * 0.15, 0, 0.999);
      pal[Math.floor(shade * pal.length)][1].push(sx, sy, sx + Math.cos(a) * l, sy + Math.sin(a) * l);
    }
  }
  strokeBatches(ctx, pal, 0.9);
  return finishFoliage(f, anisotropy);
}

// Гроно листя (256×256, ≈1 см на піксель): гілочки віялом від основи (дуб, кущ) або звисають
// згори (береза); сотні дрібних листків — від темних у глибині до світлих зовні.
function paintLeafCluster(rand, anisotropy, kind) {
  const W = 256;
  const H = 256;
  const f = foliageCanvas(W, H);
  const ctx = f.ctx;
  const birch = kind === 'birch';
  const bush = kind === 'bush';
  const pal = (birch
    ? ['#263f16', '#36561d', '#4b6d26', '#628532', '#7e9d40', '#99b052']
    : bush
      ? ['#1a3014', '#27441c', '#375a25', '#4b6f2e', '#628638', '#7a9a44']
      : ['#1b3013', '#28431a', '#385a22', '#4b712b', '#618838', '#7c9c45']).map(hexRgb);
  const twigs = [];
  const branches = birch ? 9 : 8;
  for (let b = 0; b < branches; b++) {
    const pts = [];
    if (birch) {
      let x = 128 + (rand() - 0.5) * 90;
      let y = 6 + rand() * 30;
      let a = Math.PI / 2 + (rand() - 0.5) * 1.2;
      pts.push([x, y]);
      const len = 170 + rand() * 70;
      for (let k = 1; k <= 8; k++) {
        a += (Math.PI / 2 - a) * 0.22 + (rand() - 0.5) * 0.18;
        x += Math.cos(a) * len / 8;
        y += Math.sin(a) * len / 8;
        pts.push([x, y]);
      }
    } else {
      const a0 = -Math.PI / 2 + ((b + 0.5) / branches - 0.5) * 2.6 + (rand() - 0.5) * 0.3;
      const len = 100 + rand() * 40;
      let x = 128 + (rand() - 0.5) * 14;
      let y = 254;
      let a = a0;
      pts.push([x, y]);
      for (let k = 1; k <= 6; k++) {
        a += (rand() - 0.5) * 0.4;
        x += Math.cos(a) * len / 6;
        y += Math.sin(a) * len / 6;
        pts.push([x, y]);
      }
    }
    twigs.push(pts);
    // Бічні гілочки.
    for (let k = 2; k < pts.length - 1; k += 2) {
      const [x0, y0] = pts[k];
      const dir = Math.atan2(pts[k + 1][1] - y0, pts[k + 1][0] - x0) + (rand() < 0.5 ? -1 : 1) * (0.6 + rand() * 0.5);
      const l = 26 + rand() * 24;
      twigs.push([[x0, y0], [x0 + Math.cos(dir) * l * 0.5, y0 + Math.sin(dir) * l * 0.5], [x0 + Math.cos(dir) * l, y0 + Math.sin(dir) * l + (birch ? 10 : 0)]]);
    }
  }
  const center = [128, birch ? 132 : 118];
  const radius = birch ? 124 : 112;
  ctx.strokeStyle = '#3a2c1e';
  for (const pts of twigs) {
    ctx.lineWidth = birch ? 1.0 : 1.6;
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (const pt of pts.slice(1)) ctx.lineTo(pt[0], pt[1]);
    ctx.stroke();
  }
  const count = birch ? 1100 : bush ? 760 : 820;
  const leaves = [];
  for (let i = 0; i < count; i++) {
    const tw = twigs[Math.floor(rand() * twigs.length)];
    const along = birch ? Math.pow(rand(), 0.8) : 0.15 + Math.pow(rand(), 0.7) * 0.85;
    const sf = along * (tw.length - 1);
    const sIdx = Math.min(tw.length - 2, Math.floor(sf));
    const t = sf - sIdx;
    const spread = birch ? 9 : 13;
    const x = tw[sIdx][0] + (tw[sIdx + 1][0] - tw[sIdx][0]) * t + (rand() - 0.5) * spread;
    const y = tw[sIdx][1] + (tw[sIdx + 1][1] - tw[sIdx][1]) * t + (rand() - 0.5) * spread;
    const dc = len2(x - center[0], (y - center[1]) * 0.95) / radius;
    if (dc > 1.02) continue;
    const segA = Math.atan2(tw[sIdx + 1][1] - tw[sIdx][1], tw[sIdx + 1][0] - tw[sIdx][0]);
    const len = birch ? 7 + rand() * 4 : bush ? 9 + rand() * 5 : 11 + rand() * 6;
    const wid = len * (birch ? 0.55 : bush ? 0.45 : 0.42);
    const ang = birch ? Math.PI / 2 + (rand() - 0.5) * 1.9 : segA + (rand() < 0.5 ? -1 : 1) * (0.4 + rand() * 1.0);
    const light = clamp(rand() * 0.6 + dc * 0.35 + (center[1] - y) / radius * 0.12, 0, 1);
    leaves.push({ x, y, len, wid, ang, light });
  }
  leaves.sort((a, b) => a.light - b.light);
  for (const lf of leaves) {
    ctx.fillStyle = paletteColor(pal, lf.light, rand, 0.08);
    ctx.beginPath();
    leafShape(ctx, lf.x, lf.y, lf.len, lf.wid, lf.ang, birch ? 'birch' : bush ? 'ovate' : 'oak');
    ctx.fill();
  }
  return finishFoliage(f, anisotropy);
}

// Безшовна «глибина» крони (256×256): густе дрібне листя для внутрішніх об'ємів крони —
// щоб вона не просвічувалася наскрізь. Між листками лишаються невеликі прозорі просвіти.
function paintCanopy(rand, anisotropy, kind) {
  const W = 256;
  const f = foliageCanvas(W, W);
  const ctx = f.ctx;
  const pine = kind === 'pine';
  const pal = (kind === 'birch'
    ? ['#20361a', '#2c4a1c', '#3d6024', '#52772e', '#6a8f3a']
    : pine
      ? ['#172917', '#203820', '#2b4729', '#375634', '#46663e']
      : ['#152812', '#203a18', '#2e4f20', '#3f6528', '#557c33']).map(hexRgb);
  if (pine) {
    const batches = pal.map((c) => [`rgb(${c[0]},${c[1]},${c[2]})`, []]);
    for (let i = 0; i < 5200; i++) {
      const x = rand() * W;
      const y = rand() * W;
      const a = rand() * Math.PI * 2;
      const l = 9 + rand() * 9;
      const b = batches[Math.floor(rand() * batches.length)][1];
      for (const ox of [-W, 0, W]) for (const oy of [-W, 0, W]) b.push(x + ox, y + oy, x + ox + Math.cos(a) * l, y + oy + Math.sin(a) * l);
    }
    strokeBatches(ctx, batches, 1.1);
  } else {
    const birch = kind === 'birch';
    for (let i = 0; i < (birch ? 2300 : 1700); i++) {
      const x = rand() * W;
      const y = rand() * W;
      const len = birch ? 7 + rand() * 4 : 10 + rand() * 6;
      const ang = rand() * Math.PI * 2;
      ctx.fillStyle = paletteColor(pal, rand(), rand, 0.08);
      for (const ox of [-W, 0, W]) {
        for (const oy of [-W, 0, W]) {
          if (x + ox < -20 || x + ox > W + 20 || y + oy < -20 || y + oy > W + 20) continue;
          ctx.beginPath();
          leafShape(ctx, x + ox, y + oy, len, len * 0.45, ang, birch ? 'birch' : 'oak');
          ctx.fill();
        }
      }
    }
  }
  const tex = finishFoliage(f, anisotropy);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

// Вайя папороті: стрижень знизу вгору, пір'їнки зменшуються до кінчика.
function paintFernFrond(rand, anisotropy) {
  const W = 128;
  const H = 256;
  const f = foliageCanvas(W, H);
  const ctx = f.ctx;
  const greens = ['#4f7a2e', '#5f8a34', '#46702a', '#6b9238'];
  const pts = [];
  for (let i = 0; i <= 20; i++) {
    const t = i / 20;
    pts.push([64 + Math.sin(t * 2.2) * 8 * t, 252 - t * 244]);
  }
  for (let i = 1; i < 20; i++) {
    const t = i / 20;
    const [x, y] = pts[i];
    const len = 44 * Math.pow(1 - t, 0.85) + 5;
    for (const side of [-1, 1]) {
      const ang = (side < 0 ? Math.PI : 0) - side * (0.25 + t * 0.35);
      ctx.fillStyle = greens[Math.floor(rand() * greens.length)];
      ctx.beginPath();
      leafShape(ctx, x, y, len, Math.max(3, len * 0.2), ang, 'ovate');
      ctx.fill();
    }
  }
  ctx.strokeStyle = '#4f6a2a';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(...pts[0]);
  for (const pt of pts.slice(1)) ctx.lineTo(...pt);
  ctx.stroke();
  return finishFoliage(f, anisotropy);
}

// Атлас із 4 квітів (ромашка, жовтець, дзвоники, конюшина) по 64×64 пікселі; стебла знизу.
function paintFlowers(rand, anisotropy) {
  const W = 256;
  const H = 64;
  const f = foliageCanvas(W, H);
  const ctx = f.ctx;
  const stem = (cx, top) => {
    ctx.strokeStyle = '#4f6e2a';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx, 63);
    ctx.quadraticCurveTo(cx + 3, (63 + top) / 2, cx, top);
    ctx.stroke();
    ctx.fillStyle = '#56782e';
    ctx.beginPath();
    leafShape(ctx, cx, 50, 14, 4, -2.4, 'ovate');
    ctx.fill();
  };
  // Ромашка
  stem(32, 20);
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2;
    ctx.fillStyle = i % 2 ? '#f4f2ea' : '#e8e6dc';
    ctx.beginPath();
    leafShape(ctx, 32, 18, 11, 3, a, 'ovate');
    ctx.fill();
  }
  ctx.fillStyle = '#e1b52c';
  ctx.beginPath();
  ctx.arc(32, 18, 4, 0, Math.PI * 2);
  ctx.fill();
  // Жовтець
  stem(96, 22);
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2 - Math.PI / 2;
    ctx.fillStyle = '#f2cf2a';
    ctx.beginPath();
    ctx.ellipse(96 + Math.cos(a) * 5, 20 + Math.sin(a) * 5, 6, 4.5, a, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = '#c99a1c';
  ctx.beginPath();
  ctx.arc(96, 20, 2.5, 0, Math.PI * 2);
  ctx.fill();
  // Дзвоники
  stem(160, 12);
  for (let i = 0; i < 4; i++) {
    const x = 160 + (i % 2 ? 8 : -6);
    const y = 16 + i * 9;
    ctx.fillStyle = i % 2 ? '#7a5ab8' : '#6a4aa8';
    ctx.beginPath();
    ctx.moveTo(x - 4, y);
    ctx.quadraticCurveTo(x, y - 6, x + 4, y);
    ctx.lineTo(x + 5, y + 7);
    ctx.lineTo(x - 5, y + 7);
    ctx.closePath();
    ctx.fill();
  }
  // Конюшина
  stem(224, 22);
  for (let i = 0; i < 26; i++) {
    const a = rand() * Math.PI * 2;
    const r = rand() * 7;
    ctx.fillStyle = rand() < 0.5 ? '#c4507a' : '#d8789a';
    ctx.beginPath();
    ctx.ellipse(224 + Math.cos(a) * r, 18 + Math.sin(a) * r * 0.9, 2.6, 1.8, a, 0, Math.PI * 2);
    ctx.fill();
  }
  return finishFoliage(f, anisotropy);
}

function createTextures(rand, anisotropy, texSize) {
  const coarse = tileableNoise(256, 8, 8, 5, rand);
  const fine = tileableNoise(256, 64, 64, 2, rand);
  const cloudNoise = tileableNoise(256, 4, 4, 6, rand);
  const detail = grayTexture(256, (x, y) => {
    const i = y * 256 + x;
    return 0.12 + 0.76 * (coarse[i] * 0.62 + fine[i] * 0.38);
  }, { anisotropy });
  const fur = grayTexture(128, (x, y) => 0.84 + 0.16 * sampleTile(fine, 256, x * 2, y * 2), { anisotropy });
  const clouds = grayTexture(256, (x, y) => cloudNoise[y * 256 + x], { anisotropy: 1 });
  const size = texSize;
  const grass = paintGrassGround(size, rand, anisotropy);
  const forest = paintForestFloor(size, rand, anisotropy);
  const dirt = paintDirt(size, rand, anisotropy);
  const rock = paintRock(size, rand, anisotropy);
  return {
    detail,
    fur,
    clouds,
    coarseNoise: coarse,
    fineNoise: fine,
    ground: {
      albedo: [grass.albedo, forest.albedo, dirt.albedo, rock.albedo],
      normal: [grass.normal, forest.normal, dirt.normal, rock.normal],
    },
    rock,
    bark: paintBark(size, rand, anisotropy),
    birch: paintBirchBark(Math.min(size, 256), rand, anisotropy),
    wood: paintWood(256, rand, anisotropy),
    waterNormal: paintWaterNormal(256, rand),
    foliage: {
      spruce: paintSpruceBranch(rand, anisotropy),
      spruceSkirt: paintSpruceSkirt(rand, anisotropy),
      pine: paintPineTuft(rand, anisotropy),
      oak: paintLeafCluster(rand, anisotropy, 'oak'),
      birch: paintLeafCluster(rand, anisotropy, 'birch'),
      bush: paintLeafCluster(rand, anisotropy, 'bush'),
      fern: paintFernFrond(rand, anisotropy),
      canopyOak: paintCanopy(rand, anisotropy, 'oak'),
      canopyBirch: paintCanopy(rand, anisotropy, 'birch'),
      canopyPine: paintCanopy(rand, anisotropy, 'pine'),
      flowers: paintFlowers(rand, anisotropy),
    },
  };
}

// ═══════════════════════════ 5. ГЕОМЕТРІЯ ═══════════════════════════

const V3 = (x, y, z) => new THREE.Vector3(x, y, z);

/**
 * «Лофт»: трубка вздовж ламаної з еліптичними перерізами.
 * Використовується для стовбурів, гілок, тулуба, шиї, ніг і рогів оленя.
 * sections[i] — число (радіус) або [rx, ryВерх, ryНиз].
 */
function loft(points, sections, opts = {}) {
  const radial = opts.radial || 8;
  const n = points.length;
  const ring = radial + 1;
  const capStart = !!opts.capStart;
  const capEnd = !!opts.capEnd;
  const total = n * ring + (capStart ? 1 : 0) + (capEnd ? 1 : 0);
  const pos = new Float32Array(total * 3);
  const uv = new Float32Array(total * 2);
  const index = [];
  const tangents = [];
  for (let i = 0; i < n; i++) {
    const a = points[Math.max(0, i - 1)];
    const b = points[Math.min(n - 1, i + 1)];
    tangents.push(new THREE.Vector3().subVectors(b, a).normalize());
  }
  const up = opts.up
    ? opts.up.clone()
    : (Math.abs(tangents[0].y) > 0.9 ? V3(0, 0, 1) : V3(0, 1, 0));
  up.addScaledVector(tangents[0], -up.dot(tangents[0])).normalize();
  const side = new THREE.Vector3();
  const q = new THREE.Quaternion();
  const tmp = new THREE.Vector3();
  const vScale = opts.vScale || 1;
  let vAcc = 0;
  for (let i = 0; i < n; i++) {
    const t = tangents[i];
    if (i > 0) {
      q.setFromUnitVectors(tangents[i - 1], t);
      up.applyQuaternion(q);
      up.addScaledVector(t, -up.dot(t)).normalize();
      vAcc += points[i].distanceTo(points[i - 1]);
    }
    side.crossVectors(t, up).normalize();
    const sec = sections[i];
    let rx;
    let ryTop;
    let ryBottom;
    if (typeof sec === 'number') {
      rx = sec;
      ryTop = sec;
      ryBottom = sec;
    } else {
      rx = sec[0];
      ryTop = sec[1];
      ryBottom = sec.length > 2 ? sec[2] : sec[1];
    }
    for (let k = 0; k <= radial; k++) {
      const ang = (k / radial) * Math.PI * 2;
      const c = Math.cos(ang);
      const s = Math.sin(ang);
      const ry = s >= 0 ? ryTop : ryBottom;
      tmp.copy(points[i]).addScaledVector(side, c * rx).addScaledVector(up, s * ry);
      const vi = i * ring + k;
      pos[vi * 3] = tmp.x;
      pos[vi * 3 + 1] = tmp.y;
      pos[vi * 3 + 2] = tmp.z;
      uv[vi * 2] = k / radial;
      uv[vi * 2 + 1] = vAcc / vScale;
    }
  }
  for (let i = 0; i < n - 1; i++) {
    for (let k = 0; k < radial; k++) {
      const a = i * ring + k;
      const b = (i + 1) * ring + k;
      index.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }
  let vi = n * ring;
  if (capStart) {
    const p = points[0];
    pos[vi * 3] = p.x;
    pos[vi * 3 + 1] = p.y;
    pos[vi * 3 + 2] = p.z;
    uv[vi * 2] = 0.5;
    for (let k = 0; k < radial; k++) index.push(vi, k, k + 1);
    vi++;
  }
  if (capEnd) {
    const p = points[n - 1];
    const base = (n - 1) * ring;
    pos[vi * 3] = p.x;
    pos[vi * 3 + 1] = p.y;
    pos[vi * 3 + 2] = p.z;
    uv[vi * 2] = 0.5;
    uv[vi * 2 + 1] = vAcc / vScale;
    for (let k = 0; k < radial; k++) index.push(vi, base + k + 1, base + k);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  g.setIndex(index);
  g.computeVertexNormals();
  // Згладжуємо шов (перша й остання вершина кожного кільця збігаються).
  const nor = g.attributes.normal;
  for (let i = 0; i < n; i++) {
    const a = i * ring;
    const b = a + radial;
    const x = nor.getX(a) + nor.getX(b);
    const y = nor.getY(a) + nor.getY(b);
    const z = nor.getZ(a) + nor.getZ(b);
    const l = len3(x, y, z) || 1;
    nor.setXYZ(a, x / l, y / l, z / l);
    nor.setXYZ(b, x / l, y / l, z / l);
  }
  return g;
}

function paintGeometry(geometry, fn) {
  const pos = geometry.attributes.position;
  const nor = geometry.attributes.normal;
  const count = pos.count;
  const col = new Float32Array(count * 3);
  const p = new THREE.Vector3();
  const n = new THREE.Vector3();
  const c = new THREE.Color();
  for (let i = 0; i < count; i++) {
    p.fromBufferAttribute(pos, i);
    n.fromBufferAttribute(nor, i);
    c.setRGB(1, 1, 1);
    fn(p, n, c, i);
    col[i * 3] = c.r;
    col[i * 3 + 1] = c.g;
    col[i * 3 + 2] = c.b;
  }
  geometry.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return geometry;
}

function mergeGeometries(list) {
  let vCount = 0;
  let iCount = 0;
  for (const g of list) {
    vCount += g.attributes.position.count;
    iCount += g.index ? g.index.count : g.attributes.position.count;
  }
  const pos = new Float32Array(vCount * 3);
  const nor = new Float32Array(vCount * 3);
  const uv = new Float32Array(vCount * 2);
  const col = new Float32Array(vCount * 3);
  const idx = vCount > 65535 ? new Uint32Array(iCount) : new Uint16Array(iCount);
  let vo = 0;
  let io = 0;
  for (const g of list) {
    const n = g.attributes.position.count;
    pos.set(g.attributes.position.array.subarray(0, n * 3), vo * 3);
    if (g.attributes.normal) nor.set(g.attributes.normal.array.subarray(0, n * 3), vo * 3);
    if (g.attributes.uv) uv.set(g.attributes.uv.array.subarray(0, n * 2), vo * 2);
    if (g.attributes.color) col.set(g.attributes.color.array.subarray(0, n * 3), vo * 3);
    else col.fill(1, vo * 3, (vo + n) * 3);
    if (g.index) {
      const src = g.index.array;
      for (let i = 0; i < g.index.count; i++) idx[io + i] = src[i] + vo;
      io += g.index.count;
    } else {
      for (let i = 0; i < n; i++) idx[io + i] = vo + i;
      io += n;
    }
    vo += n;
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  out.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  out.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  out.setAttribute('color', new THREE.BufferAttribute(col, 3));
  out.setIndex(new THREE.BufferAttribute(idx, 1));
  out.computeBoundingSphere();
  out.computeBoundingBox();
  return out;
}

const ICO_CACHE = new Map();
function icosphere(detail) {
  if (ICO_CACHE.has(detail)) return ICO_CACHE.get(detail);
  const t = (1 + Math.sqrt(5)) / 2;
  const verts = [
    [-1, t, 0], [1, t, 0], [-1, -t, 0], [1, -t, 0], [0, -1, t], [0, 1, t],
    [0, -1, -t], [0, 1, -t], [t, 0, -1], [t, 0, 1], [-t, 0, -1], [-t, 0, 1],
  ].map((v) => {
    const l = len3(v[0], v[1], v[2]);
    return [v[0] / l, v[1] / l, v[2] / l];
  });
  let faces = [
    [0, 11, 5], [0, 5, 1], [0, 1, 7], [0, 7, 10], [0, 10, 11], [1, 5, 9], [5, 11, 4], [11, 10, 2],
    [10, 7, 6], [7, 1, 8], [3, 9, 4], [3, 4, 2], [3, 2, 6], [3, 6, 8], [3, 8, 9], [4, 9, 5],
    [2, 4, 11], [6, 2, 10], [8, 6, 7], [9, 8, 1],
  ];
  for (let d = 0; d < detail; d++) {
    const cache = new Map();
    const mid = (a, b) => {
      const key = a < b ? a * 100000 + b : b * 100000 + a;
      let m = cache.get(key);
      if (m === undefined) {
        const va = verts[a];
        const vb = verts[b];
        const x = va[0] + vb[0];
        const y = va[1] + vb[1];
        const z = va[2] + vb[2];
        const l = len3(x, y, z);
        m = verts.length;
        verts.push([x / l, y / l, z / l]);
        cache.set(key, m);
      }
      return m;
    };
    const next = [];
    for (const [a, b, c] of faces) {
      const ab = mid(a, b);
      const bc = mid(b, c);
      const ca = mid(c, a);
      next.push([a, ab, ca], [b, bc, ab], [c, ca, bc], [ab, bc, ca]);
    }
    faces = next;
  }
  const result = { positions: new Float32Array(verts.flat()), index: new Uint16Array(faces.flat()) };
  ICO_CACHE.set(detail, result);
  return result;
}

// Деформована ікосфера — «грудка» листя, кущ або основа каменя.
function blobGeometry(detail, rx, ry, rz, amp, seed, soften = 0.5) {
  const base = icosphere(detail);
  const src = base.positions;
  const count = src.length / 3;
  const pos = new Float32Array(src.length);
  for (let i = 0; i < count; i++) {
    const x = src[i * 3];
    const y = src[i * 3 + 1];
    const z = src[i * 3 + 2];
    const n = valueNoise3(x * 1.8 + seed, y * 1.8 + seed * 0.37, z * 1.8 - seed * 0.71) * 0.7 +
      valueNoise3(x * 4.3 - seed, y * 4.3 + seed, z * 4.3) * 0.3;
    const r = 1 + amp * (n - 0.5) * 2;
    pos[i * 3] = x * r * rx;
    pos[i * 3 + 1] = y * r * ry;
    pos[i * 3 + 2] = z * r * rz;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setIndex(new THREE.BufferAttribute(base.index.slice(), 1));
  g.computeVertexNormals();
  const nor = g.attributes.normal;
  for (let i = 0; i < count; i++) {
    const nx = nor.getX(i) * (1 - soften) + src[i * 3] * soften;
    const ny = nor.getY(i) * (1 - soften) + src[i * 3 + 1] * soften;
    const nz = nor.getZ(i) * (1 - soften) + src[i * 3 + 2] * soften;
    const l = len3(nx, ny, nz) || 1;
    nor.setXYZ(i, nx / l, ny / l, nz / l);
  }
  const uv = new Float32Array(count * 2);
  for (let i = 0; i < count; i++) {
    uv[i * 2] = pos[i * 3] * 0.5 + pos[i * 3 + 2] * 0.33;
    uv[i * 2 + 1] = pos[i * 3 + 1] * 0.5 + pos[i * 3 + 2] * 0.21;
  }
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  return g;
}

function makeTriangleGeometry(positions, normals, colors) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
  g.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(normals), 3));
  g.setAttribute('color', new THREE.BufferAttribute(new Float32Array(colors), 3));
  g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array((positions.length / 3) * 2), 2));
  return g;
}

// ═══════════════════════════ 6. РЕЛЬЄФ ДОЛИНИ Й ГІР ═══════════════════════════

function catmullRom2D(points, samplesPerSegment) {
  const out = [];
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[Math.max(i - 1, 0)];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[Math.min(i + 2, points.length - 1)];
    for (let s = 0; s < samplesPerSegment; s++) {
      const t = s / samplesPerSegment;
      const t2 = t * t;
      const t3 = t2 * t;
      const f = (a, b, c, d) => 0.5 * (2 * b + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t2 + (-a + 3 * b - 3 * c + d) * t3);
      out.push([f(p0[0], p1[0], p2[0], p3[0]), f(p0[1], p1[1], p2[1], p3[1])]);
    }
  }
  out.push(points[points.length - 1].slice());
  return out;
}

// Просторовий індекс відрізків стежки: швидка відстань до стежки (точна до maxDist).
function buildSegmentIndex(pts, cell, maxDist) {
  const cols = Math.ceil(WORLD_SIZE / cell);
  const buckets = Array.from({ length: cols * cols }, () => []);
  const segs = [];
  const toCell = (v) => clamp(Math.floor((v + WORLD_HALF) / cell), 0, cols - 1);
  for (let s = 0; s < pts.length - 1; s++) {
    const [ax, az] = pts[s];
    const [bx, bz] = pts[s + 1];
    segs.push(ax, az, bx, bz);
    const x0 = toCell(Math.min(ax, bx) - maxDist);
    const x1 = toCell(Math.max(ax, bx) + maxDist);
    const z0 = toCell(Math.min(az, bz) - maxDist);
    const z1 = toCell(Math.max(az, bz) + maxDist);
    for (let cz = z0; cz <= z1; cz++) for (let cx = x0; cx <= x1; cx++) buckets[cz * cols + cx].push(s);
  }
  return {
    distance(x, z) {
      const cx = Math.floor((x + WORLD_HALF) / cell);
      const cz = Math.floor((z + WORLD_HALF) / cell);
      if (cx < 0 || cz < 0 || cx >= cols || cz >= cols) return maxDist + 1;
      const list = buckets[cz * cols + cx];
      let best = maxDist + 1;
      for (let i = 0; i < list.length; i++) {
        const o = list[i] * 4;
        const ax = segs[o];
        const az = segs[o + 1];
        const dx = segs[o + 2] - ax;
        const dz = segs[o + 3] - az;
        const lenSq = dx * dx + dz * dz || 1e-6;
        const t = clamp(((x - ax) * dx + (z - az) * dz) / lenSq, 0, 1);
        const d = len2(x - ax - dx * t, z - az - dz * t);
        if (d < best) best = d;
      }
      return best;
    },
  };
}

function hill(x, z, cx, cz, radius, height) {
  const dx = x - cx;
  const dz = z - cz;
  return height * Math.exp(-(dx * dx + dz * dz) / (radius * radius));
}

function edgeRatio(x, z) {
  return Math.max((len2(x, z) / WORLD_HALF) * 0.82, Math.max(Math.abs(x), Math.abs(z)) / WORLD_HALF);
}

function baseHeight(noise, x, z) {
  let h = fbm(noise.a, x * 0.0062, z * 0.0062, 4) * 8;
  h += hill(x, z, 128, -118, 58, 13) + hill(x, z, -146, 6, 46, 10) + hill(x, z, 154, 44, 40, 9) +
    hill(x, z, -64, -150, 52, 11) + hill(x, z, 40, 150, 40, 6);
  const rise = smoothstep(0.6, 1.02, edgeRatio(x, z));
  h += rise * rise * (24 + 16 * (fbm(noise.b, x * 0.011, z * 0.011, 3) * 0.5 + 0.5));
  return h;
}

// Гребеневий шум: гострі хребти й ущелини для гір.
function ridgedNoise(noiseFn, x, z, octaves) {
  let sum = 0;
  let amp = 0.55;
  let freq = 1;
  let weight = 1;
  for (let o = 0; o < octaves; o++) {
    let n = 1 - Math.abs(noiseFn(x * freq, z * freq));
    n *= n * weight;
    weight = clamp(n * 1.7, 0, 1);
    sum += n * amp;
    freq *= 2.03;
    amp *= 0.5;
  }
  return sum;
}

// Головні вершини (м). Північ (−z) — найвищий масив зі снігом: його видно від бази над оленячою
// галявиною й озером. Полудневе сонце світить із півдня, тож північні гори освітлені спереду.
const PEAKS = [
  { x: 250, z: -3700, h: 1150, r: 1250 },
  { x: -1500, z: -3100, h: 880, r: 950 },
  { x: 1700, z: -2900, h: 920, r: 950 },
  { x: -500, z: -2500, h: 420, r: 650 },
  { x: 3300, z: -1000, h: 760, r: 1000 },
  { x: -3300, z: -400, h: 800, r: 1000 },
  { x: 2800, z: 1700, h: 600, r: 950 },
  { x: -2700, z: 2100, h: 560, r: 950 },
  { x: 300, z: 3600, h: 480, r: 1100 },
]

// Висота гірського кільця над рельєфом долини. На межі долини (квадрат 480 м) дорівнює нулю,
// тож гори плавно продовжують її схили. Ближче — лісисті передгір'я, далі — масиви навколо
// вершин; гребеневий шум прорізає на масивах хребти й кулуари.
function mountainHeight(noise, x, z) {
  const dq = Math.max(Math.abs(x), Math.abs(z));
  const ring = smoothstep(WORLD_HALF, WORLD_HALF + 900, dq);
  if (ring <= 0) return 0;
  const d = len2(x, z);
  const wx = x + noise.f(x * 0.0005, z * 0.0005) * 300;
  const wz = z + noise.f(x * 0.0005 + 7.3, z * 0.0005 - 3.1) * 300;
  let peaks = 0;
  for (const p of PEAKS) {
    const dx = wx - p.x;
    const dz = wz - p.z;
    const q = Math.sqrt(dx * dx + dz * dz) / p.r;
    peaks += p.h * Math.exp(-Math.pow(q, 1.6));
  }
  const rugged = smoothstep(150, 900, peaks);
  // Широкі хребти (≈1,8 км) змінюють форму масивів, дрібні (≈450 м) прорізають кулуари на схилах.
  const broad = ridgedNoise(noise.g, wx * 0.00055 + 3.1, wz * 0.00055 - 1.7, 3);
  const fine = ridgedNoise(noise.g, wx * 0.0022 - 5.3, wz * 0.0022 + 2.9, 3);
  const hills = (0.55 + 0.45 * fbm(noise.f, x * 0.0016 + 1.3, z * 0.0016 - 2.2, 4)) * (45 + 150 * smoothstep(300, 1600, d));
  const relief = (broad - 0.5) * (70 + 260 * rugged) + (fine - 0.45) * (18 + 75 * rugged);
  return ring * (hills + peaks * (0.8 + 0.28 * broad) + relief * smoothstep(400, 1300, d));
}

function farHeight(noise, x, z) {
  return baseHeight(noise, x, z) + mountainHeight(noise, x, z);
}

function lakeDistance(noise, x, z) {
  const dx = x - LAKE.x;
  const dz = z - LAKE.z;
  const a = Math.atan2(dz, dx);
  const wobble = 1 + 0.16 * noise.c(Math.cos(a) * 1.2 + 5.3, Math.sin(a) * 1.2 - 2.1) +
    0.06 * noise.c(Math.cos(a) * 3.1 - 1.7, Math.sin(a) * 3.1 + 4.4);
  return len2(dx, dz) / (LAKE.r * wobble);
}

function clearingFactor(noise, x, z) {
  let c = 0;
  for (const cl of CLEARINGS) {
    const d = len2(x - cl.x, z - cl.z);
    const edge = cl.r * (1 + 0.18 * noise.c(x * 0.05, z * 0.05));
    c = Math.max(c, 1 - smoothstep(edge * 0.6, edge * 1.05, d));
  }
  return c;
}

function generateTerrain(noise) {
  const N = TERRAIN_N;
  const count = N * N;
  const pathPts = catmullRom2D(PATH_POINTS, 26);
  const pathIndex = buildSegmentIndex(pathPts, 12, 14);
  const height = new Float32Array(count);
  const pathDist = new Float32Array(count);
  const lake = new Float32Array(count);
  const forest = new Float32Array(count);
  const grass = new Float32Array(count);
  const dryness = new Float32Array(count);
  const slope = new Float32Array(count);
  const waterLevel = baseHeight(noise, LAKE.x, LAKE.z) - 0.6;
  const lodgeY = baseHeight(noise, LODGE.x, LODGE.z) + 0.1;

  for (let j = 0; j < N; j++) {
    const z = -WORLD_HALF + j * TERRAIN_STEP;
    for (let i = 0; i < N; i++) {
      const x = -WORLD_HALF + i * TERRAIN_STEP;
      const k = j * N + i;
      const pd = pathIndex.distance(x, z);
      const ld = lakeDistance(noise, x, z);
      const clear = clearingFactor(noise, x, z);
      const small = fbm(noise.b, x * 0.045, z * 0.045, 3) * 0.95 + noise.c(x * 0.17, z * 0.17) * 0.12;
      const pathMask = 1 - smoothstep(1.4, 4.4, pd);
      let h = baseHeight(noise, x, z) + small * (1 - pathMask * 0.85) * (1 - clear * 0.35) - pathMask * 0.12;
      if (ld < 1.9) {
        const shore = waterLevel + 0.4 + small * 0.15;
        if (ld >= 1) h = lerp(shore, Math.max(h, shore), smoothstep(1, 1.9, ld));
        else h = lerp(shore, waterLevel - 3.6, smoothstep(1, 0.18, ld));
      }
      // Рівний двір мисливської бази.
      const lodgeD = len2(x - LODGE.x, z - LODGE.z);
      const flat = 1 - smoothstep(LODGE.r * 0.75, LODGE.r + 9, lodgeD);
      if (flat > 0) h = lerp(h, lodgeY + small * 0.12, flat);
      height[k] = h;
      pathDist[k] = pd;
      lake[k] = ld;
      let f = smoothstep(-0.3, 0.3, fbm(noise.d, x * 0.0115 + 3.1, z * 0.0115 - 7.7, 3));
      f = Math.max(f, smoothstep(0.64, 0.88, edgeRatio(x, z)));
      f *= 1 - clear;
      f *= smoothstep(1.1, 1.5, ld);
      f *= smoothstep(LODGE.r * 0.9, LODGE.r + 12, lodgeD);
      forest[k] = f;
      dryness[k] = clamp(0.3 + 0.55 * noise.e(x * 0.021, z * 0.021) + 0.25 * noise.e(x * 0.09 + 7, z * 0.09), 0, 1);
    }
  }

  for (let j = 0; j < N; j++) {
    for (let i = 0; i < N; i++) {
      const k = j * N + i;
      const hx = height[j * N + Math.min(i + 1, N - 1)] - height[j * N + Math.max(i - 1, 0)];
      const hz = height[Math.min(j + 1, N - 1) * N + i] - height[Math.max(j - 1, 0) * N + i];
      const s = len2(hx, hz) / (2 * TERRAIN_STEP);
      slope[k] = s;
      let g = (1 - forest[k] * 0.78) * smoothstep(0.6, 1.7, pathDist[k]) * smoothstep(0.98, 1.1, lake[k]) *
        (1 - smoothstep(0.6, 0.95, s));
      if (lake[k] < 1.05 && height[k] < waterLevel + 0.05) g = 0;
      const yard = len2(-WORLD_HALF + i * TERRAIN_STEP - LODGE.x, -WORLD_HALF + j * TERRAIN_STEP - LODGE.z);
      g *= 0.25 + 0.75 * smoothstep(LODGE.r * 0.45, LODGE.r * 0.95, yard);
      grass[k] = g;
      dryness[k] = clamp(dryness[k] + s * 0.3, 0, 1);
    }
  }

  const sample = (arr, x, z) => {
    const fx = clamp((x + WORLD_HALF) / TERRAIN_STEP, 0, TERRAIN_SEG - 1e-4);
    const fz = clamp((z + WORLD_HALF) / TERRAIN_STEP, 0, TERRAIN_SEG - 1e-4);
    const i = fx | 0;
    const j = fz | 0;
    const u = fx - i;
    const v = fz - j;
    const k = j * N + i;
    return (arr[k] * (1 - u) + arr[k + 1] * u) * (1 - v) + (arr[k + N] * (1 - u) + arr[k + N + 1] * u) * v;
  };

  // Висота точно повторює трикутники сітки рельєфу (діагональ від (i+1, j) до (i, j+1)).
  const heightAt = (x, z) => {
    const fx = clamp((x + WORLD_HALF) / TERRAIN_STEP, 0, TERRAIN_SEG - 1e-4);
    const fz = clamp((z + WORLD_HALF) / TERRAIN_STEP, 0, TERRAIN_SEG - 1e-4);
    const i = fx | 0;
    const j = fz | 0;
    const u = fx - i;
    const v = fz - j;
    const k = j * N + i;
    if (u + v <= 1) return height[k] + (height[k + 1] - height[k]) * u + (height[k + N] - height[k]) * v;
    const h11 = height[k + N + 1];
    return h11 + (height[k + N] - h11) * (1 - u) + (height[k + 1] - h11) * (1 - v);
  };

  return {
    height, pathDist, lake, forest, grass, dryness, slope, waterLevel, pathPts, lodgeY, noise,
    sample,
    heightAt,
    farHeightAt: (x, z) => farHeight(noise, x, z),
    slopeAt: (x, z) => sample(slope, x, z),
    pathDistanceAt: (x, z) => pathIndex.distance(x, z),
    lakeAt: (x, z) => lakeDistance(noise, x, z),
    // Глибина води (м) лише в межах озера; поза озером — від'ємне значення.
    waterDepthAt: (x, z) => (lakeDistance(noise, x, z) < 1.05 ? waterLevel - heightAt(x, z) : -10),
  };
}

// ═══════════════════════════ 7. РОЗМІЩЕННЯ ТА КОЛІЗІЇ ═══════════════════════════

class ColliderGrid {
  constructor() {
    this.cell = 8;
    this.cols = Math.ceil(WORLD_SIZE / this.cell);
    this.cells = Array.from({ length: this.cols * this.cols }, () => []);
    this.items = [];
    this.marks = new Uint32Array(0);
    this.stamp = 0;
    this.tmp = [];
    this.tmpN = 0;
    this.tmpC = { x: 0, z: 0 };
    this.ray = { best: null, bestT: 0 };
    this.rayHit = { item: null, dist: 0 };
  }

  toCell(v) {
    return clamp(Math.floor((v + WORLD_HALF) / this.cell), 0, this.cols - 1);
  }

  insert(item, minx, minz, maxx, maxz) {
    const id = this.items.length;
    this.items.push(item);
    for (let cz = this.toCell(minz); cz <= this.toCell(maxz); cz++) {
      for (let cx = this.toCell(minx); cx <= this.toCell(maxx); cx++) this.cells[cz * this.cols + cx].push(id);
    }
  }

  addCircle(x, z, r, kind, label, height) {
    this.insert({ type: 0, x, z, r, kind, label, h: height }, x - r, z - r, x + r, z + r);
  }

  addSegment(ax, az, bx, bz, r, kind, label, height) {
    this.insert({ type: 1, ax, az, bx, bz, r, kind, label, h: height, x: (ax + bx) / 2, z: (az + bz) / 2 },
      Math.min(ax, bx) - r, Math.min(az, bz) - r, Math.max(ax, bx) + r, Math.max(az, bz) + r);
  }

  query(minx, minz, maxx, maxz) {
    // Масив не вкорочується (щоб не виділяти пам'ять щоразу): кількість знайдених — у this.tmpN.
    const out = this.tmp;
    let n = 0;
    if (this.marks.length < this.items.length) this.marks = new Uint32Array(this.items.length + 64);
    this.stamp = (this.stamp + 1) >>> 0;
    if (this.stamp === 0) {
      this.marks.fill(0);
      this.stamp = 1;
    }
    for (let cz = this.toCell(minz); cz <= this.toCell(maxz); cz++) {
      for (let cx = this.toCell(minx); cx <= this.toCell(maxx); cx++) {
        const list = this.cells[cz * this.cols + cx];
        for (let i = 0; i < list.length; i++) {
          const id = list[i];
          if (this.marks[id] !== this.stamp) {
            this.marks[id] = this.stamp;
            out[n++] = id;
          }
        }
      }
    }
    this.tmpN = n;
    return out;
  }

  closest(item, x, z, out) {
    if (item.type === 0) {
      out.x = item.x;
      out.z = item.z;
      return;
    }
    const dx = item.bx - item.ax;
    const dz = item.bz - item.az;
    const t = clamp(((x - item.ax) * dx + (z - item.az) * dz) / (dx * dx + dz * dz || 1e-6), 0, 1);
    out.x = item.ax + dx * t;
    out.z = item.az + dz * t;
  }

  // Виштовхує коло (p.x, p.z, radius) з усіх перешкод. Повертає true, якщо був контакт.
  resolve(p, radius) {
    const list = this.query(p.x - radius - 1, p.z - radius - 1, p.x + radius + 1, p.z + radius + 1);
    const c = this.tmpC;
    let hit = false;
    for (let iter = 0; iter < 2; iter++) {
      for (let i = 0; i < this.tmpN; i++) {
        const it = this.items[list[i]];
        this.closest(it, p.x, p.z, c);
        const dx = p.x - c.x;
        const dz = p.z - c.z;
        const minD = it.r + radius;
        const d2 = dx * dx + dz * dz;
        if (d2 < minD * minD) {
          const d = Math.sqrt(d2);
          if (d < 1e-5) {
            p.x += minD;
          } else {
            p.x += (dx / d) * (minD - d);
            p.z += (dz / d) * (minD - d);
          }
          hit = true;
        }
      }
    }
    return hit;
  }

  blocked(x, z, radius) {
    const list = this.query(x - radius - 1, z - radius - 1, x + radius + 1, z + radius + 1);
    const c = this.tmpC;
    for (let i = 0; i < this.tmpN; i++) {
      const it = this.items[list[i]];
      this.closest(it, x, z, c);
      const minD = it.r + radius;
      if ((x - c.x) * (x - c.x) + (z - c.z) * (z - c.z) < minD * minD) return true;
    }
    return false;
  }

  // Промінь проти «циліндрів» перешкод (для взаємодії, прицілу й куль).
  // Результат — спільний об'єкт (без створення нових у кожному кадрі): поля треба прочитати одразу.
  raycast(ox, oy, oz, dx, dy, dz, maxDist, heightAt) {
    const a = dx * dx + dz * dz;
    if (a < 1e-6) return null;
    const ex = ox + dx * maxDist;
    const ez = oz + dz * maxDist;
    const list = this.query(Math.min(ox, ex) - 4, Math.min(oz, ez) - 4, Math.max(ox, ex) + 4, Math.max(oz, ez) + 4);
    const R = this.ray;
    R.best = null;
    R.bestT = maxDist;
    for (let i = 0; i < this.tmpN; i++) {
      const it = this.items[list[i]];
      if (it.type === 0) {
        this.rayTest(it, it.x, it.z, it.r, ox, oy, oz, dx, dy, dz, a, heightAt);
      } else {
        const len = len2(it.bx - it.ax, it.bz - it.az);
        const steps = Math.max(2, Math.ceil(len / 0.8));
        for (let s = 0; s <= steps; s++) {
          const t = s / steps;
          this.rayTest(it, it.ax + (it.bx - it.ax) * t, it.az + (it.bz - it.az) * t, it.r, ox, oy, oz, dx, dy, dz, a, heightAt);
        }
      }
    }
    if (!R.best) return null;
    this.rayHit.item = R.best;
    this.rayHit.dist = R.bestT;
    return this.rayHit;
  }

  rayTest(it, cx, cz, r, ox, oy, oz, dx, dy, dz, a, heightAt) {
    const R = this.ray;
    const fx = ox - cx;
    const fz = oz - cz;
    const b = 2 * (fx * dx + fz * dz);
    const c = fx * fx + fz * fz - r * r;
    const disc = b * b - 4 * a * c;
    if (disc < 0) return;
    const s = Math.sqrt(disc);
    let t = (-b - s) / (2 * a);
    if (t < 0) t = (-b + s) / (2 * a);
    if (t < 0 || t >= R.bestT) return;
    const y = oy + dy * t;
    const g = heightAt(cx, cz);
    if (y < g - 0.4 || y > g + it.h) return;
    R.best = it;
    R.bestT = t;
  }
}

// Сітка для перевірки мінімальної відстані між об'єктами під час розміщення.
class PointGrid {
  constructor(cell) {
    this.cell = cell;
    this.map = new Map();
  }

  key(cx, cz) {
    return cx * 4096 + cz;
  }

  add(x, z) {
    const cx = Math.floor(x / this.cell);
    const cz = Math.floor(z / this.cell);
    const k = this.key(cx, cz);
    if (!this.map.has(k)) this.map.set(k, []);
    this.map.get(k).push(x, z);
  }

  near(x, z, r) {
    const cx = Math.floor(x / this.cell);
    const cz = Math.floor(z / this.cell);
    const span = Math.ceil(r / this.cell);
    for (let dz = -span; dz <= span; dz++) {
      for (let dx = -span; dx <= span; dx++) {
        const list = this.map.get(this.key(cx + dx, cz + dz));
        if (!list) continue;
        for (let i = 0; i < list.length; i += 2) {
          if ((list[i] - x) ** 2 + (list[i + 1] - z) ** 2 < r * r) return true;
        }
      }
    }
    return false;
  }
}

function scatterProps(terrain, noise, rand, colliders) {
  const trees = [];
  const rocks = [];
  const bushes = [];
  const ferns = [];
  const logs = [];
  const reeds = [];
  const treeGrid = new PointGrid(6);
  const wl = terrain.waterLevel;
  const nearSpawn = (x, z, r) => len2(x - SPAWN.x, z - SPAWN.z) < r ||
    len2(x - LODGE.x, z - LODGE.z) < LODGE.r + r * 0.4 ||
    len2(x - VEHICLE.x, z - VEHICLE.z) < 6 + r * 0.3 ||
    len2(x - TOWER.x, z - TOWER.z) < 5 + r * 0.3;
  const inWorld = (x, z, m) => Math.abs(x) < WORLD_HALF - m && Math.abs(z) < WORLD_HALF - m;
  const SIZE = { spruce: 14.5, pine: 18, oak: 11, birch: 14.5, dead: 10 };

  const addTree = (type, x, z, scale) => {
    const y = terrain.heightAt(x, z);
    trees.push({
      type, x, y, z, scale,
      rot: rand() * Math.PI * 2,
      leanX: (rand() - 0.5) * 0.05,
      leanZ: (rand() - 0.5) * 0.05,
      stretch: 0.9 + rand() * 0.2,
    });
    treeGrid.add(x, z);
    if (scale > 0.42) {
      colliders.addCircle(x, z, TREE_INFO[type].trunk * scale + 0.04, 'tree', TREE_INFO[type].name, SIZE[type] * scale);
    }
  };

  // Дерева: сітка з випадковим зсувом, щільність залежить від «лісового» поля.
  const cell = 7.2;
  const cols = Math.ceil(WORLD_SIZE / cell);
  for (let gz = 0; gz < cols; gz++) {
    for (let gx = 0; gx < cols; gx++) {
      const x = -WORLD_HALF + (gx + 0.5 + (rand() - 0.5) * 0.9) * cell;
      const z = -WORLD_HALF + (gz + 0.5 + (rand() - 0.5) * 0.9) * cell;
      const roll = rand();
      if (!inWorld(x, z, 4)) continue;
      const f = terrain.sample(terrain.forest, x, z);
      if (roll > f * f * 0.92 + 0.012) continue;
      if (terrain.pathDistanceAt(x, z) < 3.6 || terrain.lakeAt(x, z) < 1.12 || nearSpawn(x, z, 8)) continue;
      if (terrain.slopeAt(x, z) > 0.9 || treeGrid.near(x, z, 3.0)) continue;
      const h = terrain.heightAt(x, z);
      const conifer = smoothstep(-0.25, 0.35, noise.e(x * 0.008 + 11, z * 0.008 - 3) + (h - 4) * 0.03);
      let type;
      if (rand() < 0.035) type = 'dead';
      else if (rand() < conifer) type = rand() < 0.62 ? 'spruce' : 'pine';
      else {
        const r2 = rand();
        type = r2 < 0.5 ? 'oak' : r2 < 0.86 ? 'birch' : 'spruce';
      }
      addTree(type, x, z, 0.76 + rand() * 0.48);
    }
  }

  // Молоді ялинки на узліссях.
  for (let i = 0; i < 2600 && trees.length < 2200; i++) {
    const x = (rand() - 0.5) * 2 * (WORLD_HALF - 6);
    const z = (rand() - 0.5) * 2 * (WORLD_HALF - 6);
    const f = terrain.sample(terrain.forest, x, z);
    if (f < 0.25 || f > 0.75 || rand() > 0.35) continue;
    if (terrain.pathDistanceAt(x, z) < 2.6 || terrain.lakeAt(x, z) < 1.15 || nearSpawn(x, z, 6) || treeGrid.near(x, z, 2)) continue;
    addTree('spruce', x, z, 0.16 + rand() * 0.2);
  }

  // Каміння: більше на схилах, біля озера та на околицях.
  for (let gz = 0; gz < 40; gz++) {
    for (let gx = 0; gx < 40; gx++) {
      const x = -WORLD_HALF + (gx + 0.5 + (rand() - 0.5) * 0.9) * 12;
      const z = -WORLD_HALF + (gz + 0.5 + (rand() - 0.5) * 0.9) * 12;
      if (!inWorld(x, z, 3)) continue;
      const s = terrain.slopeAt(x, z);
      const ld = terrain.lakeAt(x, z);
      const shore = ld > 0.95 && ld < 1.45 ? 1 : 0;
      const p = 0.07 + s * 0.5 + smoothstep(0.7, 0.95, edgeRatio(x, z)) * 0.35 + shore * 0.35 +
        terrain.sample(terrain.forest, x, z) * 0.08;
      if (rand() > p) continue;
      if (terrain.pathDistanceAt(x, z) < 2.4 || nearSpawn(x, z, 7) || ld < 0.97) continue;
      const big = rand() < 0.13;
      const scale = big ? 1.3 + rand() * 1.6 : 0.25 + rand() * 0.7;
      if (treeGrid.near(x, z, big ? 2.2 : 1.0)) continue;
      const rock = { variant: Math.floor(rand() * 3), x, z, y: terrain.heightAt(x, z), scale, rot: rand() * Math.PI * 2 };
      rocks.push(rock);
      if (scale > 0.55) colliders.addCircle(x, z, scale * 0.82, 'rock', 'Валун, порослий мохом', scale * 1.2);
      if (big) {
        for (let k = 0; k < 3; k++) {
          const a = rand() * Math.PI * 2;
          const d = scale * (1.1 + rand() * 0.9);
          const sx = x + Math.cos(a) * d;
          const sz = z + Math.sin(a) * d;
          if (terrain.pathDistanceAt(sx, sz) < 2.2 || terrain.lakeAt(sx, sz) < 0.97) continue;
          rocks.push({ variant: Math.floor(rand() * 3), x: sx, z: sz, y: terrain.heightAt(sx, sz), scale: 0.2 + rand() * 0.35, rot: rand() * 6.28 });
        }
      }
    }
  }

  // Кущі — переважно на узліссях; папороть — у лісі.
  for (let gz = 0; gz < 74; gz++) {
    for (let gx = 0; gx < 74; gx++) {
      const x = -WORLD_HALF + (gx + 0.5 + (rand() - 0.5) * 0.9) * 6.5;
      const z = -WORLD_HALF + (gz + 0.5 + (rand() - 0.5) * 0.9) * 6.5;
      if (!inWorld(x, z, 3)) continue;
      const f = terrain.sample(terrain.forest, x, z);
      const edge = 4 * f * (1 - f);
      const clear = clearingFactor(noise, x, z);
      let p = 0.05 + edge * 0.42 + f * 0.1;
      if (clear > 0.7) p *= 0.15;
      const r = rand();
      if (terrain.pathDistanceAt(x, z) < 2.3 || terrain.lakeAt(x, z) < 1.08 || nearSpawn(x, z, 5)) continue;
      if (r < p) {
        if (treeGrid.near(x, z, 1.2)) continue;
        bushes.push({ variant: rand() < 0.6 ? 0 : 1, x, z, y: terrain.heightAt(x, z), scale: 0.7 + rand() * 0.7, rot: rand() * 6.28 });
      } else if (f > 0.45 && r < p + f * 0.32) {
        ferns.push({ x, z, y: terrain.heightAt(x, z), scale: 0.75 + rand() * 0.6, rot: rand() * 6.28 });
      }
    }
  }

  // Повалені дерева.
  for (let i = 0; i < 90 && logs.length < 16; i++) {
    const x = (rand() - 0.5) * 2 * (PLAY_HALF - 10);
    const z = (rand() - 0.5) * 2 * (PLAY_HALF - 10);
    if (terrain.sample(terrain.forest, x, z) < 0.55 || terrain.pathDistanceAt(x, z) < 6 || terrain.lakeAt(x, z) < 1.3) continue;
    if (nearSpawn(x, z, 14) || terrain.slopeAt(x, z) > 0.4) continue;
    const scale = 0.8 + rand() * 0.4;
    const rot = rand() * Math.PI;
    const half = 3.4 * scale;
    const ax = x - Math.cos(rot) * half;
    const az = z + Math.sin(rot) * half;
    const bx = x + Math.cos(rot) * half;
    const bz = z - Math.sin(rot) * half;
    let free = true;
    for (let s = 0; s <= 4; s++) {
      const t = s / 4;
      const px = ax + (bx - ax) * t;
      const pz = az + (bz - az) * t;
      if (treeGrid.near(px, pz, 1.4) || terrain.pathDistanceAt(px, pz) < 3) free = false;
    }
    if (!free) continue;
    const ya = terrain.heightAt(ax, az);
    const yb = terrain.heightAt(bx, bz);
    logs.push({ x, z, y: (ya + yb) / 2, scale, rot, tilt: Math.atan2(yb - ya, half * 2) });
    colliders.addSegment(ax, az, bx, bz, 0.34 * scale, 'log', 'Повалене дерево', 0.8 * scale);
  }

  // Очерет уздовж берега.
  for (let i = 0; i < 1400 && reeds.length < 150; i++) {
    const a = rand() * Math.PI * 2;
    const d = LAKE.r * (0.7 + rand() * 0.65);
    const x = LAKE.x + Math.cos(a) * d;
    const z = LAKE.z + Math.sin(a) * d;
    const h = terrain.heightAt(x, z);
    if (h < wl - 0.35 || h > wl + 0.3) continue;
    if (terrain.pathDistanceAt(x, z) < 2) continue;
    reeds.push({ x, z, y: h, scale: 0.75 + rand() * 0.5, rot: rand() * 6.28 });
  }

  return { trees, rocks, bushes, ferns, logs, reeds };
}

// ═══════════════════════════ 8. ДЕРЕВА Й РОСЛИНИ З КАРТОК, ІМПОСТЕРИ ═══════════════════════════
/*
 * Крони складаються з карток (прямокутників із текстурою гілки чи грона листя з прозорістю),
 * як у сучасних іграх. Нормалі карток частково «сферичні» — крона освітлюється цілісно.
 * Три рівні деталізації: близько — детальні картки, середньо — менше й більші картки,
 * далеко — імпостер (дві схрещені площини з «фото» дерева, яке рендериться під час завантаження).
 */

function makePalette() {
  const c = (hex) => new THREE.Color(hex);
  return {
    spruceBark: c(0x8f7a66),
    pineBarkLow: c(0x8c7966),
    pineBarkHigh: c(0xd09a68),
    oakBark: c(0x8a7c6a),
    birchBark: c(0xffffff),
    deadWood: c(0xb2aa9a),
    twig: c(0x6a5a48),
    spruce: c(0xe8f2ea),
    pine: c(0xfaf6e2),
    oak: [c(0xf2f6e6), c(0xe6eed6), c(0xfaf8e8)],
    birch: [c(0xf6f8e6), c(0xeef4dc), c(0xfffbe6)],
    bush: [c(0xeef2e0), c(0xe2ead2), c(0xf6f6e6)],
    fern: c(0xf2f8e8),
    rock: c(0xb4aea4),
    rockDark: c(0x7e7a72),
    moss: c(0x6f7f3d),
    logBark: c(0x8c7a64),
    logWood: c(0xc8a878),
    reed: c(0x74874a),
    reedTip: c(0xa49a5c),
    cattail: c(0x5d3d24),
  };
}

function paintBarkTint(g, color, freq = 1) {
  return paintGeometry(g, (p, n, c) => {
    c.copy(color).multiplyScalar(0.82 + 0.3 * valueNoise3(p.x * 2.5 * freq, p.y * 0.9 * freq, p.z * 2.5 * freq));
  });
}

// Набір карток: чотирикутники з нормалями, кольорами (затінення) і UV.
function makeCards() {
  const P = [];
  const N = [];
  const C = [];
  const UV = [];
  const I = [];
  return {
    add(corners, normals, colors, uvs) {
      const s = P.length / 3;
      for (let i = 0; i < 4; i++) {
        P.push(corners[i].x, corners[i].y, corners[i].z);
        N.push(normals[i].x, normals[i].y, normals[i].z);
        C.push(colors[i].r, colors[i].g, colors[i].b);
        UV.push(uvs[i * 2], uvs[i * 2 + 1]);
      }
      I.push(s, s + 1, s + 2, s, s + 2, s + 3);
    },
    geometry() {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
      g.setAttribute('normal', new THREE.Float32BufferAttribute(N, 3));
      g.setAttribute('color', new THREE.Float32BufferAttribute(C, 3));
      g.setAttribute('uv', new THREE.Float32BufferAttribute(UV, 2));
      g.setIndex(I);
      g.computeBoundingSphere();
      return g;
    },
  };
}

// Картка-грона: квадрат із центром C, нормаль площини nrm, «верх» картки up (низ текстури — v = 0).
function clumpCard(cards, C, size, nrm, up, shadeFn) {
  if (Math.abs(up.dot(nrm)) > 0.92 * up.length()) up = Math.abs(nrm.x) < 0.8 ? V3(1, 0, 0) : V3(0, 0, 1);
  const R = new THREE.Vector3().crossVectors(up, nrm).normalize();
  const U = new THREE.Vector3().crossVectors(nrm, R).normalize();
  const h = size / 2;
  const corners = [
    C.clone().addScaledVector(R, -h).addScaledVector(U, -h),
    C.clone().addScaledVector(R, h).addScaledVector(U, -h),
    C.clone().addScaledVector(R, h).addScaledVector(U, h),
    C.clone().addScaledVector(R, -h).addScaledVector(U, h),
  ];
  const normals = [];
  const colors = [];
  for (const p of corners) {
    const s = shadeFn(p, nrm);
    normals.push(s.n);
    colors.push(s.c);
  }
  cards.add(corners, normals, colors, [0, 0, 1, 0, 1, 1, 0, 1]);
}

function randomDir(rand, upBias = 0) {
  const u = rand() * 2 - 1;
  const a = rand() * Math.PI * 2;
  const s = Math.sqrt(1 - u * u);
  return V3(s * Math.cos(a), u + upBias, s * Math.sin(a)).normalize();
}

// Затінення крони як цілого: нормаль між площиною картки і напрямком від центру крони,
// внутрішні та нижні частини темніші.
function crownShader(center, radii, base, k = 0.65) {
  const tmpN = new THREE.Vector3();
  return (p, nCard) => {
    const qx = (p.x - center.x) / radii.x;
    const qy = (p.y - center.y) / radii.y;
    const qz = (p.z - center.z) / radii.z;
    const r = len3(qx, qy, qz) || 1;
    tmpN.set(qx / radii.x, qy / radii.y + 0.25, qz / radii.z).normalize();
    const n = nCard.clone().lerp(tmpN, k).normalize();
    const ao = (0.42 + 0.58 * smoothstep(0.1, 1.0, r)) * (0.72 + 0.28 * smoothstep(-0.9, 0.8, qy / r));
    return { n, c: base.clone().multiplyScalar(ao) };
  };
}

// Ялина: ярусні «спідниці» хвої навколо стовбура. Кожен ярус — пологий конус, гілки якого
// розходяться від стовбура й звисають кінцями; рваний край текстури дає природний обрис.
function buildSpruce(rand, P) {
  const H = 16;
  const lx = (rand() - 0.5) * 0.3;
  const lz = (rand() - 0.5) * 0.3;
  const axis = (t) => V3(lx * t * t, t * H, lz * t * t);
  const pts = [];
  const secs = [];
  for (let i = 0; i <= 8; i++) {
    const t = i / 8;
    pts.push(axis(t));
    secs.push(i === 0 ? 0.5 : lerp(0.36, 0.04, Math.pow(t, 0.85)));
  }
  const trunk = paintBarkTint(loft(pts, secs, { radial: 7, capEnd: true, vScale: 2.2 }), P.spruceBark);
  const crownBase = 1.5;
  const Rmax = 3.4;
  const radiusAt = (y) => {
    const t = clamp((y - crownBase) / (H - crownBase), 0, 1);
    return lerp(Rmax, 0.3, Math.pow(t, 0.92)) * (t < 0.06 ? lerp(0.75, 1, t / 0.06) : 1);
  };
  const shade = (p, frac, tierT) => {
    const a = axis(clamp(p.y / H, 0, 1));
    const dx = p.x - a.x;
    const dz = p.z - a.z;
    const d = len2(dx, dz) || 1e-4;
    const n = V3(dx / d, 0.5 + 0.35 * (1 - frac), dz / d).normalize();
    const ao = (0.3 + 0.7 * smoothstep(0, 1, frac)) * (0.7 + 0.3 * tierT);
    return { n, c: P.spruce.clone().multiplyScalar(ao) };
  };
  const build = (tiers, segs, withMid) => {
    const cards = makeCards();
    const tier = (y, R, droop, n, tierT) => {
      const base = axis(clamp(y / H, 0, 1));
      const phase = rand() * Math.PI * 2;
      const jit = [];
      for (let k = 0; k < n; k++) jit.push(0.84 + rand() * 0.32);
      const ring = (k, rk, dropK) => {
        const a = phase + (k / n) * Math.PI * 2;
        const j = jit[k % n];
        return base.clone().add(V3(Math.cos(a) * R * rk * j, -droop * dropK * j, Math.sin(a) * R * rk * j));
      };
      for (let k = 0; k < n; k++) {
        const in0 = ring(k, 0.04, -0.02);
        const in1 = ring(k + 1, 0.04, -0.02);
        const out0 = ring(k, 1, 1);
        const out1 = ring(k + 1, 1, 1);
        const quad = (c0, c1, c2, c3, v0, v1, f0, f1) => {
          const corners = [c0, c1, c2, c3];
          const fr = [f0, f0, f1, f1];
          const normals = [];
          const colors = [];
          corners.forEach((c, i) => {
            const sh = shade(c, fr[i], tierT);
            normals.push(sh.n);
            colors.push(sh.c);
          });
          cards.add(corners, normals, colors, [0, v0, 1, v0, 1, v1, 0, v1]);
        };
        if (withMid) {
          const m0 = ring(k, 0.55, 0.2);
          const m1 = ring(k + 1, 0.55, 0.2);
          quad(in0, in1, m1, m0, 1, 0.5, 0, 0.55);
          quad(m0, m1, out1, out0, 0.5, 0, 0.55, 1);
        } else {
          quad(in0, in1, out1, out0, 1, 0, 0, 1);
        }
      }
    };
    for (let i = 0; i < tiers; i++) {
      const t = i / (tiers - 1);
      const y = crownBase + 1.0 + t * (H - crownBase - 1.6) + (rand() - 0.5) * (H / tiers) * 0.6;
      const R = radiusAt(y - 0.4) * (0.86 + rand() * 0.26);
      tier(y, R, (0.4 + R * 0.38) * (0.8 + rand() * 0.45), segs, t);
    }
    // Верхівка: вузький ярус-«свічка».
    tier(H - 0.2, 0.42, 1.1, 5, 1);
    return cards.geometry();
  };
  return {
    trunk,
    foliage: { near: build(19, 9, true), mid: build(9, 6, false) },
    height: H + 0.4,
    crown: Rmax,
    leaf: 'spruceSkirt',
    bark: 'bark',
  };
}

// Щільне «ядро» грона: деформована ікосфера з безшовною текстурою дрібного листя —
// крона не просвічується наскрізь, а картки навколо дають пухнастий край.
function leafBlob(rand, c, r, sy, base, center, radii) {
  const g = blobGeometry(1, r, r * sy, r, 0.28, rand() * 50, 0.85);
  g.translate(c.x, c.y, c.z);
  const pos = g.attributes.position;
  const uv = g.attributes.uv;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i) - c.x;
    const y = pos.getY(i) - c.y;
    const z = pos.getZ(i) - c.z;
    uv.setXY(i, (x + z * 0.71 + c.x) / 2.56, (y + c.z * 0.37) / 2.56);
  }
  const shade = crownShader(center, radii, base, 0.85);
  const nor = g.attributes.normal;
  const col = new Float32Array(pos.count * 3);
  const p = new THREE.Vector3();
  const n = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    p.fromBufferAttribute(pos, i);
    n.fromBufferAttribute(nor, i);
    const sh = shade(p, n);
    nor.setXYZ(i, sh.n.x, sh.n.y, sh.n.z);
    col[i * 3] = sh.c.r * 0.82;
    col[i * 3 + 1] = sh.c.g * 0.82;
    col[i * 3 + 2] = sh.c.b * 0.82;
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return g;
}

function buildPine(rand, P) {
  const H = 18;
  const bx = (rand() - 0.5) * 0.6;
  const bz = (rand() - 0.5) * 0.6;
  const at = (t) => V3(Math.sin(t * Math.PI * 1.1) * bx * 0.5 + bx * t * 0.5, t * H,
    Math.sin(t * Math.PI * 0.8 + 0.6) * bz * 0.4 + bz * t * 0.4);
  const pts = [];
  const secs = [];
  for (let i = 0; i <= 10; i++) {
    const t = i / 10;
    pts.push(at(t));
    secs.push(i === 0 ? 0.55 : lerp(0.38, 0.07, Math.pow(t, 0.9)));
  }
  const trunk = paintGeometry(loft(pts, secs, { radial: 7, capEnd: true, vScale: 2.4 }), (p, n, c) => {
    c.copy(P.pineBarkLow).lerp(P.pineBarkHigh, smoothstep(0.42, 0.62, p.y / H))
      .multiplyScalar(0.85 + 0.28 * valueNoise3(p.x * 2.5, p.y * 0.9, p.z * 2.5));
  });
  const woody = [trunk];
  const clusters = [];
  const B = 9;
  for (let b = 0; b < B; b++) {
    const t = 0.55 + 0.37 * (b / (B - 1));
    const base = at(t);
    const ang = b * 2.39996 + rand() * 0.6;
    const dir = V3(Math.cos(ang), 0, Math.sin(ang));
    const len = (3.4 - b * 0.24) * (0.8 + rand() * 0.4);
    const p1 = base.clone().addScaledVector(dir, len * 0.5).add(V3(0, 0.3 + rand() * 0.3, 0));
    const p2 = base.clone().addScaledVector(dir, len).add(V3(0, 0.75 + rand() * 0.6, 0));
    woody.push(paintBarkTint(loft([base, p1, p2], [0.13 - b * 0.007, 0.075, 0.035], { radial: 5, capEnd: true }), P.pineBarkHigh));
    clusters.push({ c: p2.clone().add(V3(0, 0.3, 0)), r: 1.75 + rand() * 0.6 });
    clusters.push({ c: p1.clone().add(V3(0, 0.35, 0)), r: 1.3 + rand() * 0.35 });
  }
  const top = at(1);
  clusters.push({ c: top.clone().add(V3(0, 0.1, 0)), r: 1.8 });
  clusters.push({ c: at(0.87), r: 2.2 });
  clusters.push({ c: at(0.76), r: 2.0 });
  const center = at(0.82);
  const radii = V3(4.2, 3.0, 4.2);
  const shade = crownShader(center, radii, P.pine);
  const build = (per, sizeK) => {
    const cards = makeCards();
    for (const cl of clusters) {
      for (let i = 0; i < per; i++) {
        const nrm = randomDir(rand, 0.7);
        const off = randomDir(rand).multiplyScalar(cl.r * 0.5 * rand());
        clumpCard(cards, cl.c.clone().add(off), cl.r * sizeK * (0.85 + rand() * 0.3), nrm, V3(0, 1, 0).lerp(nrm, -0.3).normalize(), shade);
      }
    }
    return cards.geometry();
  };
  const core = (k) => mergeGeometries(clusters.map((cl) => leafBlob(rand, cl.c, cl.r * k, 0.7, P.pine, center, radii)));
  return {
    trunk: mergeGeometries(woody),
    foliage: { near: build(13, 1.3), mid: build(5, 1.6) },
    core: { near: core(0.5), mid: core(0.6) },
    height: H + 1.8,
    crown: 3.4,
    leaf: 'pine',
    bark: 'bark',
  };
}

function broadleafFoliage(rand, clusters, crown, base, per, perMid, sizeK, hanging) {
  const center = V3(crown.cx, crown.cy, crown.cz);
  const radii = V3(crown.rx, crown.ry, crown.rz);
  const shade = crownShader(center, radii, base, 0.7);
  const build = (count, sk) => {
    const cards = makeCards();
    for (const cl of clusters) {
      for (let i = 0; i < count; i++) {
        const nrm = hanging ? V3(rand() - 0.5, (rand() - 0.5) * 0.4, rand() - 0.5).normalize() : randomDir(rand, 0.35);
        const off = randomDir(rand).multiplyScalar(cl.r * 0.55 * rand());
        off.y *= cl.sy;
        const up = hanging ? V3(0, 1, 0) : randomDir(rand, 1.2);
        clumpCard(cards, V3(cl.x, cl.y, cl.z).add(off), cl.r * sk * (0.8 + rand() * 0.4), nrm, up, shade);
      }
    }
    return cards.geometry();
  };
  const core = (k) => mergeGeometries(clusters.map((cl) => leafBlob(rand, V3(cl.x, cl.y, cl.z), cl.r * k, cl.sy * (hanging ? 1.15 : 0.85), base, center, radii)));
  return { near: build(per, sizeK), mid: build(perMid, sizeK * 1.4), coreNear: core(0.5), coreMid: core(0.62) };
}

function buildOak(rand, P) {
  const top = V3(0.18, 3.5, 0.08);
  const trunk = paintBarkTint(loft([V3(0, 0, 0), V3(0.05, 1.2, 0.02), V3(0.12, 2.4, 0.05), top],
    [0.72, 0.5, 0.44, 0.38], { radial: 9, vScale: 2.2 }), P.oakBark, 1.4);
  const woody = [trunk];
  const clusters = [];
  const Y = V3(0, 1, 0);
  for (let b = 0; b < 4; b++) {
    const ang = (b / 4) * Math.PI * 2 + rand() * 0.7;
    const dir = V3(Math.cos(ang), 0, Math.sin(ang));
    const dir2 = dir.clone().applyAxisAngle(Y, (rand() - 0.5) * 0.6);
    const p0 = top.clone().add(V3(0, -0.25, 0));
    const p1 = p0.clone().addScaledVector(dir, 1.3 + rand() * 0.4).add(V3(0, 1.2 + rand() * 0.4, 0));
    const p2 = p1.clone().addScaledVector(dir2, 1.5 + rand() * 0.4).add(V3(0, 1.3 + rand() * 0.5, 0));
    const p3 = p2.clone().addScaledVector(dir2, 1.0 + rand() * 0.5).add(V3(0, 0.9 + rand() * 0.5, 0));
    woody.push(paintBarkTint(loft([p0, p1, p2, p3], [0.28, 0.2, 0.13, 0.06], { radial: 6, capEnd: true, vScale: 2.2 }), P.oakBark, 1.4));
    clusters.push({ x: p3.x, y: p3.y + 0.4, z: p3.z, r: 2.1 + rand() * 0.5, sy: 0.8 });
    clusters.push({ x: p2.x, y: p2.y + 0.2, z: p2.z, r: 1.7 + rand() * 0.4, sy: 0.8 });
  }
  const lead = [top.clone().add(V3(0, -0.25, 0)), V3(0.3, 5.0, 0.1), V3(0.2, 6.6, 0.25), V3(0.1, 8.0, 0.1)];
  woody.push(paintBarkTint(loft(lead, [0.26, 0.19, 0.12, 0.06], { radial: 6, capEnd: true, vScale: 2.2 }), P.oakBark, 1.4));
  clusters.push({ x: 0.1, y: 8.4, z: 0.1, r: 2.3, sy: 0.75 });
  for (let i = 0; i < 3; i++) {
    const a = rand() * Math.PI * 2;
    const d = rand() * 1.8;
    clusters.push({ x: Math.cos(a) * d, y: 6.4 + rand() * 1.6, z: Math.sin(a) * d, r: 2.0, sy: 0.8 });
  }
  const crown = { cx: 0.15, cy: 7.2, cz: 0.1, rx: 4.6, ry: 3.2, rz: 4.6 };
  const fol = broadleafFoliage(rand, clusters, crown, pick(P.oak, rand), 18, 6, 1.2, false);
  return {
    trunk: mergeGeometries(woody),
    foliage: fol,
    core: { near: fol.coreNear, mid: fol.coreMid },
    height: 11,
    crown: 4.4,
    leaf: 'oak',
    bark: 'bark',
  };
}

function buildBirch(rand, P) {
  const H = 14.5;
  const lx = (rand() - 0.5) * 0.9;
  const lz = (rand() - 0.5) * 0.9;
  const at = (t) => V3(lx * t + Math.sin(t * 5) * 0.08, t * H, lz * t + Math.cos(t * 4) * 0.06 - 0.06);
  const pts = [];
  const secs = [];
  for (let i = 0; i <= 14; i++) {
    const t = i / 14;
    pts.push(at(t));
    secs.push(i === 0 ? 0.3 : lerp(0.22, 0.045, Math.pow(t, 0.8)));
  }
  const trunk = paintGeometry(loft(pts, secs, { radial: 8, capEnd: true, vScale: 1.4 }), (p, n, c) => {
    c.setRGB(1, 1, 1).multiplyScalar(p.y < 1.2 ? lerp(0.45, 1, smoothstep(0.2, 1.2, p.y)) : 1);
  });
  const woody = [];
  const clusters = [];
  for (let b = 0; b < 6; b++) {
    const t = 0.36 + 0.5 * (b / 5);
    const base = at(t);
    const ang = b * 2.2 + rand() * 0.8;
    const dir = V3(Math.cos(ang), 0, Math.sin(ang));
    const len = 1.4 + rand() * 1.1;
    const p1 = base.clone().addScaledVector(dir, len * 0.55).add(V3(0, 0.7, 0));
    const p2 = base.clone().addScaledVector(dir, len).add(V3(0, 0.5 + rand() * 0.4, 0));
    woody.push(paintBarkTint(loft([base, p1, p2], [0.07, 0.045, 0.02], { radial: 5, capEnd: true }), P.twig));
    clusters.push({ x: p2.x, y: p2.y - 0.2, z: p2.z, r: 1.1 + rand() * 0.45, sy: 1.3 });
  }
  for (let i = 0; i < 3; i++) {
    const c = at(0.66 + i * 0.13);
    clusters.push({ x: c.x, y: c.y + 0.3, z: c.z, r: 1.3 + rand() * 0.4, sy: 1.35 });
  }
  const mid = at(0.72);
  const crown = { cx: mid.x, cy: mid.y, cz: mid.z, rx: 2.8, ry: 4.8, rz: 2.8 };
  const fol = broadleafFoliage(rand, clusters, crown, pick(P.birch, rand), 16, 6, 1.25, true);
  return {
    trunk,
    twigs: mergeGeometries(woody),
    foliage: fol,
    core: { near: fol.coreNear, mid: fol.coreMid },
    height: H + 1.5,
    crown: 2.6,
    leaf: 'birch',
    bark: 'birch',
  };
}

function buildDeadTree(rand, P) {
  const H = 10;
  const lx = (rand() - 0.5) * 0.5;
  const lz = (rand() - 0.5) * 0.5;
  const at = (t) => V3(lx * t, t * H, lz * t);
  const pts = [];
  const secs = [];
  for (let i = 0; i <= 7; i++) {
    const t = i / 7;
    pts.push(at(t));
    secs.push(i === 0 ? 0.42 : lerp(0.32, 0.09, t));
  }
  const parts = [loft(pts, secs, { radial: 7, capEnd: true, vScale: 2.2 })];
  for (let b = 0; b < 5; b++) {
    const t = 0.35 + 0.55 * (b / 4);
    const base = at(t);
    const ang = b * 2.5 + rand();
    const dir = V3(Math.cos(ang), 0, Math.sin(ang));
    const len = 1.4 + rand() * 1.6;
    const p1 = base.clone().addScaledVector(dir, len * 0.5).add(V3(0, len * 0.45, 0));
    const p2 = base.clone().addScaledVector(dir, len).add(V3(0, len * 0.75, 0));
    parts.push(loft([base, p1, p2], [0.1, 0.06, 0.02], { radial: 5, capEnd: true }));
  }
  const trunk = paintGeometry(mergeGeometries(parts), (p, n, c) => {
    c.copy(P.deadWood).multiplyScalar((0.66 + 0.34 * smoothstep(0, 4, p.y)) * (0.84 + 0.26 * valueNoise3(p.x * 2, p.y * 1.4, p.z * 2)));
  });
  return { trunk, foliage: null, height: H + 1.5, crown: 1.4, leaf: null, bark: 'bark' };
}

function buildBush(rand, P, variant) {
  const clusters = variant === 0
    ? [{ x: 0, y: 0.62, z: 0, r: 0.8, sy: 0.85 }]
    : [{ x: -0.38, y: 0.42, z: 0.05, r: 0.62, sy: 0.62 }, { x: 0.36, y: 0.38, z: -0.1, r: 0.58, sy: 0.6 }];
  const crown = variant === 0 ? { cx: 0, cy: 0.5, cz: 0, rx: 1.0, ry: 0.8, rz: 1.0 } : { cx: 0, cy: 0.3, cz: 0, rx: 1.2, ry: 0.6, rz: 0.9 };
  return broadleafFoliage(rand, clusters, crown, pick(P.bush, rand), variant === 0 ? 11 : 8, 4, 1.45, false);
}

// Папороть: вайї з двох вигнутих сегментів (основа піднімається, кінчик звисає).
function buildFern(rand, P) {
  const cards = makeCards();
  const F = 7;
  for (let f = 0; f < F; f++) {
    const ang = (f / F) * Math.PI * 2 + rand() * 0.5;
    const dir = V3(Math.cos(ang), 0, Math.sin(ang));
    const side = V3(-dir.z, 0, dir.x);
    const L = 0.75 + rand() * 0.45;
    const W = L * 0.42;
    const rise = 0.6 + rand() * 0.25;
    const p0 = V3(0, 0.02, 0);
    const p1 = dir.clone().multiplyScalar(L * 0.5).add(V3(0, L * rise * 0.65, 0));
    const p2 = dir.clone().multiplyScalar(L * 0.95).add(V3(0, L * rise * 0.45, 0));
    const shade = (p, n) => ({ n: V3(n.x * 0.4, 1, n.z * 0.4).normalize(), c: P.fern.clone().multiplyScalar(0.62 + 0.38 * smoothstep(0, 0.5, p.y)) });
    const n1 = new THREE.Vector3().crossVectors(side, p1.clone().sub(p0)).normalize();
    const n2 = new THREE.Vector3().crossVectors(side, p2.clone().sub(p1)).normalize();
    const quad = (a, b, va, vb, nrm, wa, wb) => {
      const corners = [a.clone().addScaledVector(side, -wa), a.clone().addScaledVector(side, wa), b.clone().addScaledVector(side, wb), b.clone().addScaledVector(side, -wb)];
      const normals = [];
      const colors = [];
      for (const p of corners) {
        const s = shade(p, nrm.y < 0 ? nrm.clone().negate() : nrm);
        normals.push(s.n);
        colors.push(s.c);
      }
      cards.add(corners, normals, colors, [0, va, 1, va, 1, vb, 0, vb]);
    };
    quad(p0, p1, 0, 0.55, n1, W * 0.35, W * 0.5);
    quad(p1, p2, 0.55, 1, n2, W * 0.5, W * 0.18);
  }
  return cards.geometry();
}

function buildRock(rand, P, detail) {
  const base = icosphere(detail);
  const src = base.positions;
  const count = src.length / 3;
  const pos = new Float32Array(src.length);
  const disp = new Float32Array(count);
  const seed = rand() * 100;
  const planes = [];
  for (let i = 0; i < 5; i++) {
    const a = rand() * Math.PI * 2;
    const n = V3(Math.cos(a), rand() * 1.1 - 0.25, Math.sin(a)).normalize();
    planes.push([n.x, n.y, n.z, 0.7 + rand() * 0.2]);
  }
  for (let i = 0; i < count; i++) {
    let x = src[i * 3];
    let y = src[i * 3 + 1];
    let z = src[i * 3 + 2];
    const n = valueNoise3(x * 1.6 + seed, y * 1.6, z * 1.6 - seed) * 0.65 + valueNoise3(x * 4 - seed, y * 4 + seed, z * 4) * 0.35;
    const r = 0.86 + n * 0.32;
    x *= r;
    y *= r;
    z *= r;
    for (const [px, py, pz, d] of planes) {
      const dot = x * px + y * py + z * pz;
      if (dot > d) {
        x -= px * (dot - d);
        y -= py * (dot - d);
        z -= pz * (dot - d);
      }
    }
    if (y < -0.35) y = -0.35 + (y + 0.35) * 0.3;
    pos[i * 3] = x;
    pos[i * 3 + 1] = y * 0.68;
    pos[i * 3 + 2] = z * 0.86;
    disp[i] = r;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setIndex(new THREE.BufferAttribute(base.index.slice(), 1));
  g.computeVertexNormals();
  const uv = new Float32Array(count * 2);
  for (let i = 0; i < count; i++) {
    uv[i * 2] = pos[i * 3] * 0.55 + pos[i * 3 + 2] * 0.4;
    uv[i * 2 + 1] = pos[i * 3 + 1] * 0.6 + pos[i * 3 + 2] * 0.25;
  }
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  return paintGeometry(g, (p, n, c, i) => {
    const crevice = smoothstep(0.86, 1.06, disp[i]);
    const moss = smoothstep(0.5, 0.88, n.y) * (0.45 + 0.55 * valueNoise3(p.x * 2.2 + seed, p.y * 2.2, p.z * 2.2));
    c.copy(P.rockDark).lerp(P.rock, crevice).multiplyScalar(0.9 + 0.2 * valueNoise3(p.x * 3, p.y * 3, p.z * 3));
    c.lerp(P.moss, moss * 0.8);
  });
}

function buildLog(rand, P) {
  const pts = [];
  const secs = [];
  for (let i = 0; i <= 7; i++) {
    const t = i / 7;
    pts.push(V3(-3.4 + t * 6.8, Math.sin(t * 3.1) * 0.06, Math.sin(t * 2.3 + 1) * 0.12));
    secs.push(lerp(0.34, 0.25, t));
  }
  const body = loft(pts, secs, { radial: 9, capStart: true, capEnd: true, vScale: 2.2, up: V3(0, 1, 0) });
  const knotA = loft([V3(-0.8, 0.2, 0.1), V3(-0.6, 0.55, 0.35), V3(-0.5, 0.75, 0.42)], [0.09, 0.06, 0.04], { radial: 5, capEnd: true });
  const knotB = loft([V3(1.6, 0.15, -0.15), V3(1.9, 0.3, -0.55)], [0.08, 0.05], { radial: 5, capEnd: true });
  const g = mergeGeometries([body, knotA, knotB]);
  return paintGeometry(g, (p, n, c) => {
    c.copy(P.logBark).multiplyScalar(0.84 + 0.3 * valueNoise3(p.x * 2, p.y * 3, p.z * 3));
    c.lerp(P.moss, smoothstep(0.35, 0.85, n.y) * (0.4 + 0.6 * valueNoise3(p.x * 1.4, p.y, p.z * 1.4)));
    if (Math.abs(n.x) > 0.85 && Math.abs(p.x) > 3.2) c.copy(P.logWood);
  });
}

function buildReeds(rand, P) {
  const positions = [];
  const normals = [];
  const colors = [];
  const col = new THREE.Color();
  const pushVertex = (x, y, z, nx, nz, t) => {
    positions.push(x, y, z);
    const l = len3(nx, 0.6, nz) || 1;
    normals.push(nx / l, 0.6 / l, nz / l);
    col.copy(P.reed).lerp(P.reedTip, t);
    colors.push(col.r, col.g, col.b);
  };
  for (let b = 0; b < 10; b++) {
    const a = rand() * Math.PI * 2;
    const r = rand() * 0.28;
    const cx = Math.cos(a) * r;
    const cz = Math.sin(a) * r;
    const H = 1.0 + rand() * 0.7;
    const la = rand() * Math.PI * 2;
    const lean = 0.1 + rand() * 0.25;
    const w = 0.022 + rand() * 0.012;
    const px = -Math.sin(la);
    const pz = Math.cos(la);
    const at = (t) => [cx + Math.cos(la) * lean * t * t, H * t, cz + Math.sin(la) * lean * t * t];
    const levels = [0, 0.35, 0.7, 1];
    for (let s = 0; s < 3; s++) {
      const t0 = levels[s];
      const t1 = levels[s + 1];
      const p0 = at(t0);
      const p1 = at(t1);
      const w0 = w * (1 - t0);
      const w1 = w * (1 - t1) + 0.001;
      const A = [p0[0] - px * w0, p0[1], p0[2] - pz * w0];
      const Bv = [p0[0] + px * w0, p0[1], p0[2] + pz * w0];
      const C = [p1[0] + px * w1, p1[1], p1[2] + pz * w1];
      const D = [p1[0] - px * w1, p1[1], p1[2] - pz * w1];
      const nx = Math.cos(la);
      const nz = Math.sin(la);
      for (const [v, t] of [[A, t0], [Bv, t0], [C, t1], [A, t0], [C, t1], [D, t1]]) pushVertex(v[0], v[1], v[2], nx, nz, t);
    }
  }
  const blades = makeTriangleGeometry(positions, normals, colors);
  const heads = [];
  for (let k = 0; k < 1; k++) {
    const a = rand() * Math.PI * 2;
    const x = Math.cos(a) * 0.15;
    const z = Math.sin(a) * 0.15;
    const H = 1.25 + rand() * 0.35;
    const stem = loft([V3(x, 0, z), V3(x, H, z)], [0.007, 0.006], { radial: 4 });
    paintGeometry(stem, (p, n, c) => c.copy(P.reed));
    const head = loft([V3(x, H - 0.28, z), V3(x, H - 0.24, z), V3(x, H - 0.06, z), V3(x, H - 0.02, z)],
      [0.012, 0.03, 0.03, 0.012], { radial: 6, capEnd: true });
    paintGeometry(head, (p, n, c) => c.copy(P.cattail));
    heads.push(stem, head);
  }
  return mergeGeometries([blades, ...heads]);
}

// Вітер і просвічування листя: зсув вершин у вершинному шейдері, світло крізь листя проти сонця.
function windChunk(amount, minY) {
  return `#include <begin_vertex>
#ifdef USE_INSTANCING
  vec3 wBase = vec3(instanceMatrix[3][0], instanceMatrix[3][1], instanceMatrix[3][2]);
#else
  vec3 wBase = vec3(0.0);
#endif
  float wH = max(position.y - ${minY.toFixed(2)}, 0.0);
  float wP = uTime * 1.3 + wBase.x * 0.11 + wBase.z * 0.13;
  float wS = (sin(wP) * 0.65 + sin(wP * 2.7 + 1.3) * 0.25) * uWind;
  float wF = sin(uTime * 4.1 + position.x * 2.3 + position.z * 1.9 + wBase.x) * 0.012 * uWind * min(wH, 3.0);
  transformed.x += wS * wH * wH * ${amount.toFixed(5)} + wF;
  transformed.z += wS * wH * wH * ${amount.toFixed(5)} * 0.55 * cos(wP * 0.6) + wF * 0.7;
  transformed.y += wF * 0.5;`;
}

function addWind(material, key, amount, minY) {
  const prev = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    if (prev) prev(shader, renderer);
    shader.uniforms.uTime = WIND.uTime;
    shader.uniforms.uWind = WIND.uStrength;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;\nuniform float uWind;')
      .replace('#include <begin_vertex>', windChunk(amount, minY));
  };
  material.customProgramCacheKey = () => `wh-wind-${key}`;
  return material;
}

function foliageMaterial(map, key, amount, minY, atmos, translucency = 0.35, edgeFade = false) {
  const mat = new THREE.MeshLambertMaterial({ map, alphaTest: 0.42, side: THREE.DoubleSide, vertexColors: true });
  // Ядра крон: біля силуету (нормаль майже перпендикулярна до погляду) листя рідшає — обрис рваний.
  const edgeChunk = edgeFade
    ? 'diffuseColor.a *= smoothstep(0.08, 0.55, abs(dot(normalize(vNormal), normalize(vViewPosition))));\n#include <alphatest_fragment>'
    : '#include <alphatest_fragment>';
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = WIND.uTime;
    shader.uniforms.uWind = WIND.uStrength;
    shader.uniforms.uSunDirL = atmos.u.uSunDir;
    shader.uniforms.uSunColL = atmos.u.uSunColor;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;\nuniform float uWind;\nvarying vec3 vLeafW;')
      .replace('#include <begin_vertex>', windChunk(amount, minY))
      .replace('#include <project_vertex>', `#include <project_vertex>
#ifdef USE_INSTANCING
  vLeafW = (modelMatrix * instanceMatrix * vec4(transformed, 1.0)).xyz;
#else
  vLeafW = (modelMatrix * vec4(transformed, 1.0)).xyz;
#endif`);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform vec3 uSunDirL;\nuniform vec3 uSunColL;\nvarying vec3 vLeafW;')
      .replace('#include <alphatest_fragment>', edgeChunk)
      .replace('#include <normal_fragment_begin>',
        'float faceDirection = gl_FrontFacing ? 1.0 : -1.0;\nvec3 normal = normalize(vNormal);\nvec3 nonPerturbedNormal = normal;')
      .replace('#include <opaque_fragment>', `
  vec3 lV = normalize(cameraPosition - vLeafW);
  float lBack = pow(max(dot(-lV, uSunDirL), 0.0), 3.0);
  outgoingLight += diffuseColor.rgb * uSunColL * lBack * ${translucency.toFixed(3)};
  #include <opaque_fragment>`);
  };
  mat.customProgramCacheKey = () => `wh-leaf-${key}`;
  return mat;
}

function foliageDepthMaterial(map, key, amount, minY) {
  const mat = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking, map, alphaTest: 0.42 });
  return addWind(mat, `${key}-depth`, amount, minY);
}

function createMaterials(textures, quality, atmos) {
  const F = textures.foliage;
  const nm = quality.normalMaps;
  const bark = new THREE.MeshStandardMaterial({
    vertexColors: true, map: textures.bark.albedo, normalMap: nm ? textures.bark.normal : null, roughness: 0.93, metalness: 0, envMapIntensity: 0.45,
  });
  const birchBark = new THREE.MeshStandardMaterial({
    vertexColors: true, map: textures.birch.albedo, normalMap: nm ? textures.birch.normal : null, roughness: 0.8, metalness: 0, envMapIntensity: 0.5,
  });
  const rock = new THREE.MeshStandardMaterial({
    vertexColors: true, map: textures.rock.albedo, normalMap: nm ? textures.rock.normal : null, roughness: 0.86, metalness: 0, envMapIntensity: 0.5,
  });
  if (nm) {
    bark.normalScale.set(1.2, 1.2);
    rock.normalScale.set(1.4, 1.4);
  }
  const deer = new THREE.MeshStandardMaterial({ vertexColors: true, map: textures.fur, roughness: 0.85, metalness: 0, envMapIntensity: 0.4 });
  const reeds = addWind(new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide }), 'reeds', 0.045, 0.15);
  return {
    bark, birchBark, rock, deer, reeds,
    leaves: {
      spruce: foliageMaterial(F.spruce, 'spruce', 0.0011, 2.0, atmos, 0.3),
      spruceSkirt: foliageMaterial(F.spruceSkirt, 'spruceSkirt', 0.0009, 2.0, atmos, 0.22),
      pine: foliageMaterial(F.pine, 'pine', 0.0011, 2.0, atmos, 0.35),
      oak: foliageMaterial(F.oak, 'oak', 0.0018, 2.5, atmos, 0.45),
      birch: foliageMaterial(F.birch, 'birch', 0.0022, 2.5, atmos, 0.5),
      bush: foliageMaterial(F.bush, 'bush', 0.03, 0.2, atmos, 0.45),
      fern: foliageMaterial(F.fern, 'fern', 0.05, 0.1, atmos, 0.5),
    },
    cores: {
      oak: foliageMaterial(F.canopyOak, 'core-oak', 0.0018, 2.5, atmos, 0.3, true),
      birch: foliageMaterial(F.canopyBirch, 'core-birch', 0.0022, 2.5, atmos, 0.35, true),
      pine: foliageMaterial(F.canopyPine, 'core-pine', 0.0011, 2.0, atmos, 0.25, true),
      bush: foliageMaterial(F.canopyOak, 'core-bush', 0.03, 0.2, atmos, 0.3, true),
    },
    coresDepth: {
      oak: foliageDepthMaterial(F.canopyOak, 'core-oak', 0.0018, 2.5),
      birch: foliageDepthMaterial(F.canopyBirch, 'core-birch', 0.0022, 2.5),
      pine: foliageDepthMaterial(F.canopyPine, 'core-pine', 0.0011, 2.0),
      bush: foliageDepthMaterial(F.canopyOak, 'core-bush', 0.03, 0.2),
    },
    leavesDepth: {
      spruce: foliageDepthMaterial(F.spruce, 'spruce', 0.0011, 2.0),
      spruceSkirt: foliageDepthMaterial(F.spruceSkirt, 'spruceSkirt', 0.0009, 2.0),
      pine: foliageDepthMaterial(F.pine, 'pine', 0.0011, 2.0),
      oak: foliageDepthMaterial(F.oak, 'oak', 0.0018, 2.5),
      birch: foliageDepthMaterial(F.birch, 'birch', 0.0022, 2.5),
      bush: foliageDepthMaterial(F.bush, 'bush', 0.03, 0.2),
    },
  };
}

/*
 * Імпостер: дерево рендериться збоку в текстуру (лише колір і затінення без освітлення),
 * потім у грі освітлюється як звичайний об'єкт — тож працює з будь-яким часом доби.
 */
function bakeImpostor(renderer, parts, w = 256, h = 512) {
  const scene = new THREE.Scene();
  const group = new THREE.Group();
  const temp = [];
  for (const part of parts) {
    const m = new THREE.MeshBasicMaterial({
      map: part.material.map || null,
      color: part.material.color ? part.material.color.clone() : 0xffffff,
      vertexColors: !!part.geometry.attributes.color,
      alphaTest: part.material.alphaTest || 0,
      side: THREE.DoubleSide,
      fog: false,
    });
    temp.push(m);
    group.add(new THREE.Mesh(part.geometry, m));
  }
  scene.add(group);
  const box = new THREE.Box3().setFromObject(group);
  const halfW = Math.max(-box.min.x, box.max.x, -box.min.z, box.max.z, 0.5) * 1.03;
  const top = box.max.y * 1.02;
  const cam = new THREE.OrthographicCamera(-halfW, halfW, top, 0, -100, 100);
  cam.position.set(0, 0, 50);
  const rt = new THREE.WebGLRenderTarget(w, h, { generateMipmaps: true, minFilter: THREE.LinearMipmapLinearFilter, magFilter: THREE.LinearFilter });
  rt.texture.colorSpace = THREE.SRGBColorSpace;
  const prevTarget = renderer.getRenderTarget();
  const prevColor = renderer.getClearColor(new THREE.Color());
  const prevAlpha = renderer.getClearAlpha();
  renderer.setRenderTarget(rt);
  renderer.setClearColor(0x000000, 0);
  renderer.clear(true, true, false);
  renderer.render(scene, cam);
  renderer.setRenderTarget(prevTarget);
  renderer.setClearColor(prevColor, prevAlpha);
  for (const m of temp) m.dispose();
  return { texture: rt.texture, target: rt, halfW, height: top };
}

function impostorGeometry(halfW, height) {
  const cards = makeCards();
  const white = new THREE.Color(1, 1, 1);
  for (let q = 0; q < 2; q++) {
    const a = q * Math.PI / 2;
    const ax = Math.cos(a);
    const az = Math.sin(a);
    const corners = [V3(-ax * halfW, 0, -az * halfW), V3(ax * halfW, 0, az * halfW), V3(ax * halfW, height, az * halfW), V3(-ax * halfW, height, -az * halfW)];
    const normals = corners.map((p) => V3(p.x, height * 0.35 + p.y * 0.25, p.z).normalize());
    cards.add(corners, normals, [white, white, white, white], [0, 0, 1, 0, 1, 1, 0, 1]);
  }
  return cards.geometry();
}

function impostorMaterial(texture) {
  const mat = new THREE.MeshLambertMaterial({ map: texture, alphaTest: 0.32, side: THREE.DoubleSide });
  mat.onBeforeCompile = (shader) => {
    shader.fragmentShader = shader.fragmentShader.replace('#include <normal_fragment_begin>',
      'float faceDirection = gl_FrontFacing ? 1.0 : -1.0;\nvec3 normal = normalize(vNormal);\nvec3 nonPerturbedNormal = normal;');
  };
  mat.customProgramCacheKey = () => 'wh-impostor';
  return mat;
}

/*
 * Плавна зміна рівнів деталізації (LOD): біля межі двох рівнів дерево малюється обома моделями,
 * і кожен піксель бере лише одна з них (взаємодоповнювальний «розчинний» візерунок). Біля межі
 * дальності об'єкт так само поступово розчиняється, а не зникає раптово.
 * Значення aFade на екземпляр: 1 — повністю видимий; 0…1 — видимий там, де шум < aFade;
 * 1…2 — видимий там, де шум ≥ aFade − 1 (доповнення до сусіднього рівня).
 */
function addLodFade(material) {
  if (!material || material.userData.whLodFade) return material;
  material.userData.whLodFade = true;
  const prev = material.onBeforeCompile;
  material.onBeforeCompile = function onCompileLodFade(shader, renderer) {
    if (prev) prev.call(this, shader, renderer);
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\n#ifdef USE_INSTANCING\nattribute float aFade;\nvarying float vLodFade;\n#endif')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\n#ifdef USE_INSTANCING\n\tvLodFade = aFade;\n#endif');
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\n#ifdef USE_INSTANCING\nvarying float vLodFade;\n#endif')
      .replace('#include <clipping_planes_fragment>', `#ifdef USE_INSTANCING
\tif (abs(vLodFade - 1.0) > 0.002) {
\t\tfloat lodN = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
\t\tif (vLodFade < 1.0 ? lodN >= vLodFade : lodN < vLodFade - 1.0) discard;
\t}
#endif
#include <clipping_planes_fragment>`);
  };
  const key = material.customProgramCacheKey.bind(material);
  material.customProgramCacheKey = () => `${key()}|wh-lod`;
  return material;
}

/**
 * Набір однакових об'єктів (InstancedMesh) з кількома рівнями деталізації. Коли камера рухається,
 * у буфер GPU копіюються лише видимі екземпляри (відсікання за відстанню та пірамідою видимості),
 * кожен — у шар за відстанню: ближній, середній або імпостер.
 */
class InstancedField {
  constructor(name, kind, layerParts, capacity, maxDist) {
    this.name = name;
    this.kind = kind;
    this.layerParts = layerParts.filter(Boolean);
    this.capacity = Math.max(1, capacity);
    this.maxDist = maxDist;
    this.lod = [40, 120];
    this.count = 0;
    this.visibleCount = 0;
    this.static = false;              // true — відсікання лише за переміщенням (далекий ліс)
    this.matrices = new Float32Array(this.capacity * 16);
    this.tints = new Float32Array(this.capacity * 3);
    this.spheres = new Float32Array(this.capacity * 4);
    this.layers = [];
  }

  add(matrix, tint, cx, cy, cz, radius) {
    if (this.count >= this.capacity) return;
    const i = this.count++;
    matrix.toArray(this.matrices, i * 16);
    this.tints[i * 3] = tint.r;
    this.tints[i * 3 + 1] = tint.g;
    this.tints[i * 3 + 2] = tint.b;
    this.spheres[i * 4] = cx;
    this.spheres[i * 4 + 1] = cy;
    this.spheres[i * 4 + 2] = cz;
    this.spheres[i * 4 + 3] = radius;
  }

  makeLayer(scene, parts) {
    const cap = this.capacity;
    const layer = {
      matrix: new THREE.InstancedBufferAttribute(new Float32Array(cap * 16), 16),
      full: new THREE.InstancedBufferAttribute(new Float32Array(cap * 3), 3),
      gray: new THREE.InstancedBufferAttribute(new Float32Array(cap * 3), 3),
      fade: new THREE.InstancedBufferAttribute(new Float32Array(cap).fill(1), 1),
      meshes: [],
      count: 0,
    };
    layer.attrs = [layer.matrix, layer.full, layer.gray, layer.fade];
    layer.ranges = layer.attrs.map(() => ({ start: 0, count: 0 }));
    for (const attr of layer.attrs) attr.setUsage(THREE.DynamicDrawUsage);
    for (const part of parts) {
      const src = part.geometry;
      const geo = new THREE.BufferGeometry();
      for (const [name, attr] of Object.entries(src.attributes)) geo.setAttribute(name, attr);
      if (src.index) geo.setIndex(src.index);
      for (const gr of src.groups) geo.addGroup(gr.start, gr.count, gr.materialIndex);
      geo.setDrawRange(src.drawRange.start, src.drawRange.count);
      geo.setAttribute('aFade', layer.fade);
      addLodFade(part.material);
      if (part.depthMaterial) addLodFade(part.depthMaterial);
      const mesh = new THREE.InstancedMesh(geo, part.material, cap);
      mesh.instanceMatrix = layer.matrix;
      mesh.instanceColor = part.tint === 'gray' ? layer.gray : layer.full;
      mesh.count = 0;
      mesh.visible = false;
      mesh.frustumCulled = false;
      mesh.castShadow = !!part.castShadow;
      mesh.receiveShadow = !!part.receiveShadow;
      if (part.depthMaterial) mesh.customDepthMaterial = part.depthMaterial;
      mesh.name = this.name;
      mesh.matrixAutoUpdate = false;
      mesh.updateMatrix();
      scene.add(mesh);
      layer.meshes.push(mesh);
    }
    return layer;
  }

  build(scene) {
    this.layers = this.layerParts.map((parts) => this.makeLayer(scene, parts));
  }

  setShadows(on) {
    for (let l = 0; l < this.layers.length; l++) {
      const parts = this.layerParts[l];
      this.layers[l].meshes.forEach((mesh, i) => {
        mesh.castShadow = on && !!parts[i].castShadow;
      });
    }
  }

  cull(camX, camZ, frustum, nearDist) {
    const S = this.spheres;
    const M = this.matrices;
    const T = this.tints;
    const L = this.layers;
    const n = L.length;
    const b0 = this.lod[0];
    const b1 = this.lod[1];
    // Півширина перехідної смуги: 7 % відстані межі + 1 м.
    const e0 = b0 * 0.07 + 1;
    const e1 = b1 * 0.07 + 1;
    const near2 = nearDist * nearDist;
    let visible = 0;
    for (const layer of L) layer.count = 0;
    for (let i = 0; i < this.count; i++) {
      const i4 = i * 4;
      const sx = S[i4];
      const sz = S[i4 + 2];
      const r = S[i4 + 3];
      const dx = sx - camX;
      const dz = sz - camZ;
      const d2 = dx * dx + dz * dz;
      const lim = this.maxDist + r;
      if (d2 > lim * lim) continue;
      if (frustum && d2 > near2) {
        SPHERE.center.set(sx, S[i4 + 1], sz);
        SPHERE.radius = r + 1.5 + Math.sqrt(d2) * 0.03;
        if (!frustum.intersectsSphere(SPHERE)) continue;
      }
      const d = Math.sqrt(d2);
      visible++;
      // Останні 6 % дальності — поступове розчинення.
      const fadeStart = lim * 0.94;
      const edgeFade = d > fadeStart ? Math.max(0, 1 - (d - fadeStart) / (lim - fadeStart)) : 1;
      if (n === 1) {
        this.put(L[0], i, edgeFade, M, T);
        continue;
      }
      if (d < b0 - e0) this.put(L[0], i, 1, M, T);
      else if (d < b0 + e0) {
        const t = (d - (b0 - e0)) / (2 * e0);
        this.put(L[0], i, 1 - t, M, T);
        this.put(L[1], i, 2 - t, M, T);
      } else if (n === 2 || d < b1 - e1) this.put(L[1], i, n === 2 ? edgeFade : 1, M, T);
      else if (d < b1 + e1) {
        const t = (d - (b1 - e1)) / (2 * e1);
        this.put(L[1], i, 1 - t, M, T);
        this.put(L[2], i, 2 - t, M, T);
      } else this.put(L[2], i, edgeFade, M, T);
    }
    for (const layer of L) {
      // Оновлюється лише використана частина буферів; об'єкти діапазонів — постійні.
      for (let a = 0; a < 4; a++) {
        const attr = layer.attrs[a];
        const range = layer.ranges[a];
        range.count = Math.max(1, layer.count) * attr.itemSize;
        attr.updateRanges.length = 0;
        attr.updateRanges.push(range);
        attr.needsUpdate = true;
      }
      for (const mesh of layer.meshes) {
        mesh.count = layer.count;
        mesh.visible = layer.count > 0;
      }
    }
    this.visibleCount = visible;
  }

  // Екземпляр i — у шар layer зі значенням розчинення fade.
  put(layer, i, fade, M, T) {
    const k = layer.count++;
    const dm = layer.matrix.array;
    const s16 = i * 16;
    const d16 = k * 16;
    for (let m = 0; m < 16; m++) dm[d16 + m] = M[s16 + m];
    const s3 = i * 3;
    const d3 = k * 3;
    const df = layer.full.array;
    const dg = layer.gray.array;
    df[d3] = T[s3];
    df[d3 + 1] = T[s3 + 1];
    df[d3 + 2] = T[s3 + 2];
    const gray = (T[s3] + T[s3 + 1] + T[s3 + 2]) / 3;
    dg[d3] = gray;
    dg[d3 + 1] = gray;
    dg[d3 + 2] = gray;
    layer.fade.array[k] = fade;
  }
}

function buildVegetation(scene, props, materials, rand, quality, renderer, terrain) {
  const P = makePalette();
  const fields = [];
  const impostors = {};
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const e = new THREE.Euler();
  const s = new THREE.Vector3();
  const p = new THREE.Vector3();
  const tint = new THREE.Color();
  const builders = { spruce: buildSpruce, pine: buildPine, oak: buildOak, birch: buildBirch, dead: buildDeadTree };
  const defs = {};

  for (const type of TREE_TYPES) {
    const def = GLB_VEGETATION[type] ? GLB_VEGETATION[type] : builders[type](rand, P);
    defs[type] = def;
    let near;
    let mid;
    if (def.parts) {
      near = def.parts;
      mid = def.parts;
    } else {
      const barkMat = def.bark === 'birch' ? materials.birchBark : materials.bark;
      const trunkPart = { geometry: def.trunk, material: barkMat, castShadow: true, receiveShadow: true, tint: 'gray' };
      near = [trunkPart];
      mid = [trunkPart];
      if (def.twigs) near.push({ geometry: def.twigs, material: materials.bark, castShadow: true, receiveShadow: true, tint: 'gray' });
      if (def.core) {
        const coreMat = materials.cores[def.leaf];
        const coreDepth = materials.coresDepth[def.leaf];
        near.push({ geometry: def.core.near, material: coreMat, depthMaterial: coreDepth, castShadow: true, receiveShadow: true, tint: 'full' });
        mid.push({ geometry: def.core.mid, material: coreMat, depthMaterial: coreDepth, castShadow: true, receiveShadow: true, tint: 'full' });
      }
      if (def.foliage) {
        const leafMat = materials.leaves[def.leaf];
        const depth = materials.leavesDepth[def.leaf];
        near.push({ geometry: def.foliage.near, material: leafMat, depthMaterial: depth, castShadow: true, receiveShadow: true, tint: 'full' });
        mid.push({ geometry: def.foliage.mid, material: leafMat, depthMaterial: depth, castShadow: true, receiveShadow: true, tint: 'full' });
      }
    }
    const imp = bakeImpostor(renderer, near);
    const impPart = { geometry: impostorGeometry(imp.halfW, imp.height), material: impostorMaterial(imp.texture), castShadow: false, receiveShadow: false, tint: 'full' };
    impostors[type] = { ...imp, part: impPart };
    const list = props.trees.filter((t) => t.type === type);
    const field = new InstancedField(`tree-${type}`, 'tree', [near, mid, [impPart]], list.length, quality.impostor);
    field.lod = [quality.lodNear, quality.lodMid];
    for (const t of list) {
      e.set(t.leanX, t.rot, t.leanZ);
      q.setFromEuler(e);
      s.set(t.scale, t.scale * t.stretch, t.scale);
      p.set(t.x, t.y - 0.12 * t.scale, t.z);
      m.compose(p, q, s);
      const v = 0.86 + rand() * 0.26;
      const warm = (rand() - 0.4) * 0.12;
      tint.setRGB(v * (1 + warm), v, v * (1 - warm * 1.3));
      const h = def.height * t.scale * t.stretch;
      field.add(m, tint, t.x, t.y + h * 0.5, t.z, Math.max(h * 0.55, def.crown * t.scale));
    }
    field.build(scene);
    fields.push(field);
  }

  // Далекий ліс на схилах гір — лише імпостери (ялина й сосна, трохи листяних).
  const far = farForestPoints(terrain, quality.farForest, rand);
  if (far.length) {
    for (const [kind, filter] of [['spruce', (f) => f.conifer && f.scale > 1.05], ['pine', (f) => f.conifer && f.scale <= 1.05], ['oak', (f) => !f.conifer]]) {
      const list = far.filter(filter);
      if (!list.length) continue;
      const field = new InstancedField(`far-${kind}`, 'impostor', [[impostors[kind].part]], list.length, FAR_RADIUS);
      field.static = true;
      field.lod = [0, 0];
      for (const f of list) {
        e.set(0, f.rot, 0);
        q.setFromEuler(e);
        s.set(f.scale * 1.15, f.scale * 1.25, f.scale * 1.15);
        p.set(f.x, f.y, f.z);
        m.compose(p, q, s);
        const v = 0.7 + rand() * 0.25;
        tint.setRGB(v * 0.95, v, v * 0.9);
        field.add(m, tint, f.x, f.y + 8, f.z, 10);
      }
      field.build(scene);
      fields.push(field);
    }
  }

  const simpleField = (name, kind, layers, list, opts) => {
    const field = new InstancedField(name, kind, layers, list.length, Math.min(quality.view, FIELD_CAPS[kind]));
    field.lod = [quality.lodNear * (opts.lodK || 0.8), quality.lodMid * 0.6];
    for (const it of list) {
      e.set(0, it.rot, 0);
      q.setFromEuler(e);
      s.set(it.scale, it.scale, it.scale);
      p.set(it.x, it.y - (opts.sink || 0) * it.scale, it.z);
      m.compose(p, q, s);
      const v = 0.85 + rand() * 0.3;
      tint.setRGB(v, v, v * (0.95 + rand() * 0.1));
      field.add(m, tint, it.x, it.y + opts.height * 0.5 * it.scale, it.z, opts.radius * it.scale);
    }
    field.build(scene);
    fields.push(field);
    return field;
  };

  for (let v = 0; v < 3; v++) {
    const geo = GLB_VEGETATION.rock ? null : buildRock(rand, P, v === 2 ? 3 : 2);
    const layers = GLB_VEGETATION.rock
      ? [GLB_VEGETATION.rock.parts]
      : [[{ geometry: geo, material: materials.rock, castShadow: true, receiveShadow: true, tint: 'full' }]];
    simpleField(`rock-${v}`, 'rock', layers, props.rocks.filter((r) => r.variant === v), { height: 1.2, radius: 1.3, sink: 0.12 });
  }
  for (let v = 0; v < 2; v++) {
    let layers;
    if (GLB_VEGETATION.bush) layers = [GLB_VEGETATION.bush.parts];
    else {
      const g = buildBush(rand, P, v);
      const base = { material: materials.leaves.bush, depthMaterial: materials.leavesDepth.bush, castShadow: true, receiveShadow: true, tint: 'full' };
      const core = { material: materials.cores.bush, depthMaterial: materials.coresDepth.bush, castShadow: true, receiveShadow: true, tint: 'full' };
      layers = [[{ ...core, geometry: g.coreNear }, { ...base, geometry: g.near }], [{ ...core, geometry: g.coreMid }, { ...base, geometry: g.mid }]];
    }
    simpleField(`bush-${v}`, 'bush', layers, props.bushes.filter((b) => b.variant === v), { height: 1.4, radius: 1.3 });
  }
  simpleField('ferns', 'fern', GLB_VEGETATION.fern ? [GLB_VEGETATION.fern.parts]
    : [[{ geometry: buildFern(rand, P), material: materials.leaves.fern, castShadow: false, receiveShadow: true, tint: 'full' }]],
  props.ferns, { height: 0.8, radius: 1.1, lodK: 10 });
  simpleField('reeds', 'reeds', [[{ geometry: buildReeds(rand, P), material: materials.reeds, castShadow: false, receiveShadow: true, tint: 'full' }]],
    props.reeds, { height: 1.6, radius: 0.9, lodK: 10 });

  const logField = new InstancedField('logs', 'log', [[{ geometry: buildLog(rand, P), material: materials.bark, castShadow: true, receiveShadow: true, tint: 'gray' }]],
    props.logs.length, Math.min(quality.view, FIELD_CAPS.log));
  logField.lod = [1e4, 1e4];
  for (const l of props.logs) {
    e.set(0, l.rot, l.tilt, 'YZX');
    q.setFromEuler(e);
    s.set(l.scale, l.scale, l.scale);
    p.set(l.x, l.y + 0.12 * l.scale, l.z);
    m.compose(p, q, s);
    tint.setRGB(1, 1, 1);
    logField.add(m, tint, l.x, l.y + 0.3, l.z, 3.8 * l.scale);
  }
  logField.build(scene);
  fields.push(logField);
  return { fields, impostors, defs };
}

// ═══════════════════════════ 9. ЗЕМЛЯ, ТРАВА, КВІТИ, ВОДА ═══════════════════════════

/*
 * Макрокарта всієї долини (DataTexture): RGB — легкі зміни відтінку (128 = нейтрально),
 * A — затінення під кронами й біля каміння. Деталі дають безшовні PBR-шари.
 */
function paintTerrainMacro(terrain, props, textures, size) {
  const data = new Uint8Array(size * size * 4);
  const coarse = textures.coarseNoise;
  const fine = textures.fineNoise;
  const mPerPx = WORLD_SIZE / size;
  const ao = new Float32Array(size * size).fill(1);
  for (let py = 0; py < size; py++) {
    const z = -WORLD_HALF + (py + 0.5) * mPerPx;
    for (let px = 0; px < size; px++) {
      const x = -WORLD_HALF + (px + 0.5) * mPerPx;
      const dry = terrain.sample(terrain.dryness, x, z);
      const ld = terrain.sample(terrain.lake, x, z);
      const n1 = sampleTile(coarse, 256, x * 1.6, z * 1.6);
      const n2 = sampleTile(fine, 256, x * 4, z * 4);
      const v = 0.92 + 0.16 * n1 + 0.06 * (n2 - 0.5);
      let r = v * (1 + dry * 0.06);
      let g = v * (1 + dry * 0.03);
      let b = v * (1 - dry * 0.08);
      const wet = 1 - smoothstep(1.0, 1.25, ld);
      r *= 1 - wet * 0.12;
      g *= 1 - wet * 0.08;
      b *= 1 - wet * 0.05;
      const o = (py * size + px) * 4;
      data[o] = clamp(r * 128, 0, 255);
      data[o + 1] = clamp(g * 128, 0, 255);
      data[o + 2] = clamp(b * 128, 0, 255);
    }
  }
  const crown = { spruce: 2.8, pine: 2.3, oak: 4.0, birch: 2.4, dead: 0.8 };
  const darken = (cx, cz, radiusM, strength) => {
    const rpx = radiusM / mPerPx;
    const pcx = (cx + WORLD_HALF) / mPerPx;
    const pcz = (cz + WORLD_HALF) / mPerPx;
    const x0 = Math.max(0, Math.floor(pcx - rpx));
    const x1 = Math.min(size - 1, Math.ceil(pcx + rpx));
    const z0 = Math.max(0, Math.floor(pcz - rpx));
    const z1 = Math.min(size - 1, Math.ceil(pcz + rpx));
    for (let pz = z0; pz <= z1; pz++) {
      for (let px = x0; px <= x1; px++) {
        const d = len2(px + 0.5 - pcx, pz + 0.5 - pcz) / rpx;
        if (d >= 1) continue;
        ao[pz * size + px] *= 1 - strength * (1 - d * d) * (1 - d * d);
      }
    }
  };
  for (const t of props.trees) darken(t.x, t.z, crown[t.type] * t.scale * 1.15, t.scale < 0.4 ? 0.12 : 0.34);
  for (const r of props.rocks) darken(r.x, r.z, r.scale * 1.3, 0.32);
  for (let i = 0; i < size * size; i++) data[i * 4 + 3] = clamp(ao[i] * 255, 0, 255);
  const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat, THREE.UnsignedByteType);
  tex.colorSpace = THREE.NoColorSpace;
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  tex.needsUpdate = true;
  return tex;
}

function buildTerrainMesh(terrain, macroTex, textures, quality, atmos) {
  const N = TERRAIN_N;
  const pos = new Float32Array(N * N * 3);
  const uv = new Float32Array(N * N * 2);
  const splat = new Float32Array(N * N * 4);
  const misc = new Float32Array(N * N * 2);
  for (let j = 0; j < N; j++) {
    for (let i = 0; i < N; i++) {
      const k = j * N + i;
      pos[k * 3] = -WORLD_HALF + i * TERRAIN_STEP;
      pos[k * 3 + 1] = terrain.height[k];
      pos[k * 3 + 2] = -WORLD_HALF + j * TERRAIN_STEP;
      uv[k * 2] = i / TERRAIN_SEG;
      uv[k * 2 + 1] = j / TERRAIN_SEG;
      const pathT = 1 - smoothstep(1.0, 2.6, terrain.pathDist[k]);
      const forestT = smoothstep(0.42, 0.92, terrain.forest[k]);
      const rockT = smoothstep(0.58, 1.0, terrain.slope[k]);
      const ld = terrain.lake[k];
      const shore = 1 - smoothstep(0.94, 1.14, ld);
      const yard = 1 - smoothstep(LODGE.r * 0.35, LODGE.r * 0.8, len2(pos[k * 3] - LODGE.x, pos[k * 3 + 2] - LODGE.z));
      let w0 = (1 - forestT) * (1 - pathT) * (1 - rockT);
      let w1 = forestT * (1 - pathT) * (1 - rockT);
      let w2 = Math.max(pathT, shore * 0.85, yard * 0.75);
      let w3 = rockT * (1 - pathT);
      w0 *= 1 - w2;
      w1 *= 1 - w2;
      const sum = w0 + w1 + w2 + w3 || 1;
      splat[k * 4] = w0 / sum;
      splat[k * 4 + 1] = w1 / sum;
      splat[k * 4 + 2] = w2 / sum;
      splat[k * 4 + 3] = w3 / sum;
      misc[k * 2] = 1 - smoothstep(0.96, 1.1, ld);
      misc[k * 2 + 1] = terrain.dryness[k];
    }
  }
  const index = new Uint16Array(TERRAIN_SEG * TERRAIN_SEG * 6);
  let o = 0;
  for (let j = 0; j < TERRAIN_SEG; j++) {
    for (let i = 0; i < TERRAIN_SEG; i++) {
      const a = j * N + i;
      const b = a + 1;
      const c = a + N;
      const d = c + 1;
      index[o++] = a;
      index[o++] = c;
      index[o++] = b;
      index[o++] = b;
      index[o++] = c;
      index[o++] = d;
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  geo.setAttribute('aSplat', new THREE.BufferAttribute(splat, 4));
  geo.setAttribute('aMisc', new THREE.BufferAttribute(misc, 2));
  geo.setIndex(new THREE.BufferAttribute(index, 1));
  geo.computeVertexNormals();
  geo.computeBoundingSphere();
  const mat = new THREE.MeshStandardMaterial({ roughness: 0.92, metalness: 0, envMapIntensity: 0.55 });
  const G = textures.ground;
  // Карти нормалей землі й другий масштаб текстур (проти помітного повторення) — за профілем: на телефонах
  // це найдорожчий шейдер за кількістю вибірок текстур (до 11 на піксель).
  const normals = quality.terrainNormals;
  const variation = quality.terrainVariation;
  const uniforms = {
    uAlb0: { value: G.albedo[0] }, uAlb1: { value: G.albedo[1] }, uAlb2: { value: G.albedo[2] }, uAlb3: { value: G.albedo[3] },
    uNrm0: { value: G.normal[0] }, uNrm1: { value: G.normal[1] }, uNrm2: { value: G.normal[2] }, uNrm3: { value: G.normal[3] },
    uMacro: { value: macroTex },
    uWet: atmos.u.uWet,
    uScale: { value: new THREE.Vector4(0.33, 0.27, 0.36, 0.14) },
  };
  mat.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>
attribute vec4 aSplat;
attribute vec2 aMisc;
varying vec4 vSplat;
varying vec2 vMisc;
varying vec2 vXZ;
varying vec2 vMacroUv;
varying vec3 vWN;`)
      .replace('#include <begin_vertex>', `#include <begin_vertex>
vSplat = aSplat;
vMisc = aMisc;
vXZ = (modelMatrix * vec4(position, 1.0)).xz;
vMacroUv = uv;
vWN = normalize(mat3(modelMatrix) * normal);`);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>
${normals ? '#define WH_NORMALS' : ''}
${variation ? '#define WH_VARIATION' : ''}
uniform sampler2D uAlb0;
uniform sampler2D uAlb1;
uniform sampler2D uAlb2;
uniform sampler2D uAlb3;
uniform sampler2D uNrm0;
uniform sampler2D uNrm1;
uniform sampler2D uNrm2;
uniform sampler2D uNrm3;
uniform sampler2D uMacro;
uniform float uWet;
uniform vec4 uScale;
varying vec4 vSplat;
varying vec2 vMisc;
varying vec2 vXZ;
varying vec2 vMacroUv;
varying vec3 vWN;`)
      .replace('#include <map_fragment>', `
vec2 uv0 = vXZ * uScale.x;
vec2 uv1 = vXZ * uScale.y + 0.13;
vec2 uv2 = vXZ * uScale.z + 0.41;
vec2 uv3 = vXZ * uScale.w + 0.7;
vec4 a0 = texture2D(uAlb0, uv0);
vec4 a1 = texture2D(uAlb1, uv1);
vec4 a2 = texture2D(uAlb2, uv2);
vec4 a3 = texture2D(uAlb3, uv3);
#ifdef WH_VARIATION
a0.rgb = mix(a0.rgb, texture2D(uAlb0, vXZ * 0.061 + 0.5).rgb, 0.35);
a1.rgb = mix(a1.rgb, texture2D(uAlb1, vXZ * 0.057 + 0.2).rgb, 0.3);
#endif
vec4 hw = vec4(a0.a, a1.a, a2.a, a3.a) * 0.45 + vSplat;
float hmax = max(max(hw.x, hw.y), max(hw.z, hw.w)) - 0.18;
vec4 bw = max(hw - hmax, 0.0) * step(0.002, vSplat);
bw /= (bw.x + bw.y + bw.z + bw.w + 1e-5);
vec3 albedo = a0.rgb * bw.x + a1.rgb * bw.y + a2.rgb * bw.z + a3.rgb * bw.w;
vec4 macro = texture2D(uMacro, vMacroUv);
albedo *= macro.rgb * 2.0 * macro.a;
// Далеко ліс видно як суцільні крони: підстилка між деревами непомітна (і дерева там уже не малюються).
float canopy = bw.y * smoothstep(120.0, 260.0, length(vXZ - cameraPosition.xz));
albedo = mix(albedo, vec3(0.03, 0.055, 0.028) * (0.8 + 0.4 * a1.a), canopy * 0.9);
float wet = max(vMisc.x, uWet * 0.55);
albedo *= 1.0 - wet * 0.32;
diffuseColor.rgb *= albedo;
float whRough = 0.92;`)
      .replace('#include <roughnessmap_fragment>', 'float roughnessFactor = whRough;')
      .replace('#include <normal_fragment_maps>', `
#ifdef WH_NORMALS
vec4 n0 = texture2D(uNrm0, uv0);
vec4 n1 = texture2D(uNrm1, uv1);
vec4 n2 = texture2D(uNrm2, uv2);
vec4 n3 = texture2D(uNrm3, uv3);
vec4 nb = n0 * bw.x + n1 * bw.y + n2 * bw.z + n3 * bw.w;
vec3 tn = nb.xyz * 2.0 - 1.0;
tn.xy *= 1.15;
vec3 Nw = normalize(vWN);
vec3 Tw = normalize(vec3(1.0, 0.0, 0.0) - Nw * Nw.x);
vec3 Bw = normalize(cross(Tw, Nw));
vec3 nw = normalize(Tw * tn.x + Bw * tn.y + Nw * tn.z);
normal = normalize((viewMatrix * vec4(nw, 0.0)).xyz);
roughnessFactor = nb.a;
#endif
roughnessFactor = mix(roughnessFactor, 0.3, wet * 0.75);`);
  };
  mat.customProgramCacheKey = () => `wh-terrain-${normals ? 'n' : 'f'}${variation ? 'v' : ''}`;
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  mesh.name = 'terrain';
  mesh.matrixAutoUpdate = false;
  return mesh;
}

/*
 * Дані рельєфу для шейдерів трави, квітів і води.
 * uTerrain (N×N, HalfFloat, лінійна фільтрація): R — висота, G — густота трави, B — сухість, A — ліс;
 * маски читаються однією вибіркою з апаратною інтерполяцією.
 * uTerrainH ((N−1)², Float32): висоти чотирьох кутів кожної клітинки — точна висота трикутників сітки
 * однією вибіркою (раніше — чотири texelFetch на кожну вершину кожної травинки).
 */
function createTerrainDataTexture(terrain) {
  const N = TERRAIN_N;
  const toHalf = THREE.DataUtils.toHalfFloat;
  const data = new Uint16Array(N * N * 4);
  for (let k = 0; k < N * N; k++) {
    data[k * 4] = toHalf(terrain.height[k]);
    data[k * 4 + 1] = toHalf(terrain.grass[k]);
    data[k * 4 + 2] = toHalf(terrain.dryness[k]);
    data[k * 4 + 3] = toHalf(terrain.forest[k]);
  }
  const tex = new THREE.DataTexture(data, N, N, THREE.RGBAFormat, THREE.HalfFloatType);
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearFilter;
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  tex.generateMipmaps = false;
  tex.needsUpdate = true;
  const M = N - 1;
  const H = terrain.height;
  const cells = new Float32Array(M * M * 4);
  for (let j = 0; j < M; j++) {
    for (let i = 0; i < M; i++) {
      const k = j * N + i;
      const o = (j * M + i) * 4;
      cells[o] = H[k];
      cells[o + 1] = H[k + 1];
      cells[o + 2] = H[k + N];
      cells[o + 3] = H[k + N + 1];
    }
  }
  const cellTex = new THREE.DataTexture(cells, M, M, THREE.RGBAFormat, THREE.FloatType);
  cellTex.magFilter = THREE.NearestFilter;
  cellTex.minFilter = THREE.NearestFilter;
  cellTex.generateMipmaps = false;
  cellTex.needsUpdate = true;
  tex.userData.cells = cellTex;
  return tex;
}

const TERRAIN_GLSL = /* glsl */`
uniform sampler2D uTerrain;
uniform sampler2D uTerrainH;
uniform vec3 uTerr;
vec4 whTerrain(vec2 p) {
  vec2 f = (p + uTerr.z) / uTerr.y;
  vec2 cell = clamp(floor(f), vec2(0.0), vec2(uTerr.x - 2.0));
  vec2 t = clamp(f - cell, 0.0, 1.0);
  vec4 h = texelFetch(uTerrainH, ivec2(cell), 0);
  float y = t.x + t.y <= 1.0 ? h.x + (h.y - h.x) * t.x + (h.z - h.x) * t.y : h.w + (h.z - h.w) * (1.0 - t.x) + (h.y - h.w) * (1.0 - t.y);
  vec4 m = texture2D(uTerrain, (clamp(f, vec2(0.0), vec2(uTerr.x - 1.0)) + 0.5) / uTerr.x);
  return vec4(y, m.gba);
}
`;

/**
 * Густа трава: один InstancedMesh із кущиків травинок. Позиції екземплярів «загортаються»
 * навколо гравця у вершинному шейдері, висота береться з текстури рельєфу — трава
 * нескінченна навколо гравця і не потребує роботи процесора.
 */
function createGrass(terrainTex, quality, rand, atmos) {
  const blades = 8;
  const positions = [];
  const normals = [];
  const colors = [];
  const heights = [];
  const index = [];
  const base = new THREE.Color(0x1f2c12);
  const mid = new THREE.Color(0x46602a);
  const tip = new THREE.Color(0x77913f);
  const dry = new THREE.Color(0xa69a5c);
  const c = new THREE.Color();
  for (let b = 0; b < blades; b++) {
    const a = rand() * Math.PI * 2;
    const r = Math.sqrt(rand()) * 0.26;
    const ox = Math.cos(a) * r;
    const oz = Math.sin(a) * r;
    const facing = rand() * Math.PI * 2;
    const px = Math.cos(facing);
    const pz = Math.sin(facing);
    const h = 0.28 + rand() * 0.36;
    const w = 0.018 + rand() * 0.016;
    const leanA = rand() * Math.PI * 2;
    const lean = (0.15 + rand() * 0.35) * h;
    const verts = [
      [ox - px * w, 0, oz - pz * w, 0],
      [ox + px * w, 0, oz + pz * w, 0],
      [ox + Math.cos(leanA) * lean, h, oz + Math.sin(leanA) * lean, 1],
    ];
    const start = positions.length / 3;
    const nx = -pz * 0.5 + Math.cos(leanA) * 0.25;
    const nz = px * 0.5 + Math.sin(leanA) * 0.25;
    const nl = len3(nx, 0.85, nz);
    const yellow = rand() < 0.14 ? 0.3 + rand() * 0.4 : 0;
    const shade = 0.85 + rand() * 0.3;
    for (const [x, y, z, t] of verts) {
      positions.push(x, y, z);
      normals.push(nx / nl, 0.85 / nl, nz / nl);
      c.copy(base).lerp(mid, Math.min(1, t * 1.6)).lerp(tip, Math.max(0, t - 0.4) * 1.4).lerp(dry, yellow * t).multiplyScalar(shade);
      colors.push(c.r, c.g, c.b);
      heights.push(t);
    }
    index.push(start, start + 1, start + 2);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geo.setAttribute('aH', new THREE.Float32BufferAttribute(heights, 1));
  geo.setIndex(index);
  const inst = new Float32Array(GRASS_CAPACITY * 4);
  const g = 1.324717957244746;      // «пластичне число»: рівномірний розподіл травинок
  const a1 = 1 / g;
  const a2 = 1 / (g * g);
  for (let n = 0; n < GRASS_CAPACITY; n++) {
    inst[n * 4] = fract(0.5 + a1 * (n + 1));
    inst[n * 4 + 1] = fract(0.5 + a2 * (n + 1));
    inst[n * 4 + 2] = rand();
    inst[n * 4 + 3] = rand() * Math.PI * 2;
  }
  geo.setAttribute('aInst', new THREE.InstancedBufferAttribute(inst, 4));
  const uniforms = {
    uTime: WIND.uTime,
    uWindS: WIND.uStrength,
    uCenter: { value: new THREE.Vector2() },
    uSize: { value: quality.grassSize },
    uTerrain: { value: terrainTex },
    uTerrainH: { value: terrainTex.userData.cells },
    uTerr: { value: new THREE.Vector3(TERRAIN_N, TERRAIN_STEP, WORLD_HALF) },
    uWindDir: atmos.u.uWind,
    uSunDir: atmos.u.uSunDir,
    uSunColor: atmos.u.uSunColor,
  };
  const mat = new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide });
  mat.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>
attribute vec4 aInst;
attribute float aH;
uniform float uTime;
uniform float uWindS;
uniform vec2 uCenter;
uniform float uSize;
uniform vec2 uWindDir;
varying float vTip;
varying vec3 vGrassW;
${TERRAIN_GLSL}`)
      .replace('void main() {', `void main() {
  vec2 gRel = mod(aInst.xy * uSize - uCenter + 0.5 * uSize, uSize) - 0.5 * uSize;
  vec2 gXZ = uCenter + gRel;
  vec4 gT = whTerrain(gXZ);
  float gDist = length(gRel) / (0.5 * uSize);
  float gFade = 1.0 - smoothstep(0.72, 0.98, gDist);
  float gKeep = step(aInst.z, gT.g);
  float gScale = (0.62 + 0.7 * fract(aInst.z * 7.31 + aInst.w)) * (0.5 + 0.72 * gT.g) * gFade * gKeep;
  float gc = cos(aInst.w);
  float gs = sin(aInst.w);
  vec3 gLocal = vec3(gc * position.x - gs * position.z, position.y, gs * position.x + gc * position.z) * gScale;
  vec3 gNormal = normalize(vec3(gc * normal.x - gs * normal.z, normal.y, gs * normal.x + gc * normal.z));
  float gW = sin(uTime * 1.9 + gXZ.x * 0.32 + gXZ.y * 0.21) * 0.6 + sin(uTime * 3.3 + gXZ.x * 0.83 - gXZ.y * 0.57) * 0.3;
  float gGust = 0.55 + 0.45 * sin(uTime * 0.37 + gXZ.x * 0.015 + gXZ.y * 0.011);
  vec2 gBend = uWindDir * (gW * gGust * 0.16 * uWindS * aH * aH * gScale);
  vec3 gPos = vec3(gXZ.x + gLocal.x + gBend.x, gT.r - 0.04 + gLocal.y - dot(gBend, gBend) * 0.6, gXZ.y + gLocal.z + gBend.y);
  float gVar = fract(aInst.z * 13.17 + aInst.w * 0.31);
  vec3 gTint = mix(vec3(1.0), vec3(1.2, 1.07, 0.72), clamp(gT.b, 0.0, 1.0) * 0.55) * (0.8 + 0.4 * gVar);
  gTint *= mix(1.0, 0.62, clamp(gT.a, 0.0, 1.0));
  vTip = aH;
  vGrassW = gPos;`)
      .replace('#include <beginnormal_vertex>', 'vec3 objectNormal = gNormal;')
      .replace('#include <begin_vertex>', 'vec3 transformed = gPos;')
      .replace('#include <color_vertex>', '#include <color_vertex>\n  vColor.rgb *= gTint;');
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>
uniform vec3 uSunDir;
uniform vec3 uSunColor;
varying float vTip;
varying vec3 vGrassW;`)
      .replace('#include <normal_fragment_begin>',
        'float faceDirection = gl_FrontFacing ? 1.0 : -1.0;\nvec3 normal = normalize(vNormal);\nvec3 nonPerturbedNormal = normal;')
      .replace('#include <opaque_fragment>', `
  vec3 gV = normalize(cameraPosition - vGrassW);
  float gBack = pow(max(dot(-gV, uSunDir), 0.0), 4.0) * vTip;
  outgoingLight += diffuseColor.rgb * uSunColor * gBack * 0.22;
  #include <opaque_fragment>`);
  };
  mat.customProgramCacheKey = () => 'wh-grass-v2';
  const mesh = new THREE.InstancedMesh(geo, mat, GRASS_CAPACITY);
  mesh.count = quality.grass;
  mesh.frustumCulled = false;
  mesh.castShadow = false;
  mesh.receiveShadow = quality.shadows && quality.grassShadows;   // тіні на траві — лише «Високий» і «Ультра»
  mesh.name = 'grass';
  return { mesh, uniforms, material: mat };
}

/*
 * Квіти на галявинах: схрещені картки з атласу (ромашка, жовтець, дзвоники, конюшина),
 * розташовуються як трава — навколо гравця, лише на відкритих місцях і плямами.
 */
function createFlowers(terrainTex, texture, quality, rand) {
  const geo = new THREE.BufferGeometry();
  const P = [];
  const UV = [];
  const NRM = [];
  const IDX = [];
  for (let q = 0; q < 2; q++) {
    const a = q * Math.PI / 2;
    const cx = Math.cos(a) * 0.14;
    const cz = Math.sin(a) * 0.14;
    const s = P.length / 3;
    P.push(-cx, 0, -cz, cx, 0, cz, cx, 0.36, cz, -cx, 0.36, -cz);
    UV.push(0, 0, 1, 0, 1, 1, 0, 1);
    for (let i = 0; i < 4; i++) NRM.push(0, 1, 0);
    IDX.push(s, s + 1, s + 2, s, s + 2, s + 3);
  }
  geo.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(UV, 2));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(NRM, 3));
  geo.setIndex(IDX);
  const inst = new Float32Array(FLOWER_CAPACITY * 4);
  for (let n = 0; n < FLOWER_CAPACITY; n++) {
    inst[n * 4] = rand();
    inst[n * 4 + 1] = rand();
    inst[n * 4 + 2] = rand();
    inst[n * 4 + 3] = rand();
  }
  geo.setAttribute('aInst', new THREE.InstancedBufferAttribute(inst, 4));
  const uniforms = {
    uTime: WIND.uTime,
    uCenter: { value: new THREE.Vector2() },
    uSize: { value: 44 },
    uTerrain: { value: terrainTex },
    uTerrainH: { value: terrainTex.userData.cells },
    uTerr: { value: new THREE.Vector3(TERRAIN_N, TERRAIN_STEP, WORLD_HALF) },
  };
  const mat = new THREE.MeshLambertMaterial({ map: texture, alphaTest: 0.45, side: THREE.DoubleSide });
  mat.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>
attribute vec4 aInst;
uniform float uTime;
uniform vec2 uCenter;
uniform float uSize;
${TERRAIN_GLSL}`)
      .replace('#include <uv_vertex>', `#include <uv_vertex>
  float fKind = floor(aInst.w * 4.0);
  vMapUv = vec2((fKind + uv.x) * 0.25, uv.y);`)
      .replace('#include <begin_vertex>', `
  vec2 fRel = mod(aInst.xy * uSize - uCenter + 0.5 * uSize, uSize) - 0.5 * uSize;
  vec2 fXZ = uCenter + fRel;
  vec4 fT = whTerrain(fXZ);
  float patchN = sin(fXZ.x * 0.11 + fKind * 1.7) * sin(fXZ.y * 0.093 - fKind) + sin(fXZ.x * 0.031 - fXZ.y * 0.027);
  float fKeep = step(0.35, patchN) * step(0.55, fT.g) * step(fT.a, 0.35);
  float fFade = 1.0 - smoothstep(0.7, 0.98, length(fRel) / (0.5 * uSize));
  float fScale = (0.75 + 0.5 * aInst.z) * fKeep * fFade;
  float fa = aInst.z * 6.2831;
  vec3 fLoc = vec3(cos(fa) * position.x - sin(fa) * position.z, position.y, sin(fa) * position.x + cos(fa) * position.z) * fScale;
  float fw = sin(uTime * 2.1 + fXZ.x * 0.4) * 0.05 * position.y;
  vec3 transformed = vec3(fXZ.x + fLoc.x + fw, fT.r - 0.02 + fLoc.y, fXZ.y + fLoc.z + fw * 0.6);`);
  };
  mat.customProgramCacheKey = () => 'wh-flowers-v1';
  const mesh = new THREE.InstancedMesh(geo, mat, FLOWER_CAPACITY);
  mesh.count = quality.flowers;
  mesh.visible = quality.flowers > 0;
  mesh.frustumCulled = false;
  mesh.name = 'flowers';
  return { mesh, uniforms };
}

/*
 * Озеро: хвилі з карти нормалей у двох масштабах, відбиття кубічної карти (небо, гори, ліс),
 * ефект Френеля, відблиск сонця, колір і прозорість за глибиною, піна біля берега, брижі від дощу.
 */
function createWater(terrain, terrainTex, normalTex, atmos, envCube) {
  const uniforms = THREE.UniformsUtils.merge([THREE.UniformsLib.fog, {
    uDeep: { value: new THREE.Color(0x15281f) },
    uShallow: { value: new THREE.Color(0x56624a) },
    uTerr: { value: new THREE.Vector3(TERRAIN_N, TERRAIN_STEP, WORLD_HALF) },
    uWater: { value: terrain.waterLevel },
  }]);
  Object.assign(uniforms, {
    uTime: WIND.uTime,
    uNormal: { value: normalTex },
    uTerrain: { value: terrainTex },
    uTerrainH: { value: terrainTex.userData.cells },
    uEnv: { value: envCube },
    uSunDir: atmos.u.uSunDir,
    uSunColor: atmos.u.uSunColor,
    uZenith: atmos.u.uZenith,
    uHorizon: atmos.u.uHorizon,
    uRain: atmos.u.uRain,
    uWind: atmos.u.uWind,
  });
  const mat = new THREE.ShaderMaterial({
    uniforms,
    defines: envCube ? { WH_ENV: 1 } : {},
    vertexShader: /* glsl */`
      #include <common>
      #include <fog_pars_vertex>
      varying vec3 vWorld;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
        vec4 mvPosition = viewMatrix * wp;
        gl_Position = projectionMatrix * mvPosition;
        #include <fog_vertex>
      }`,
    fragmentShader: /* glsl */`
      #include <common>
      #include <fog_pars_fragment>
      uniform float uTime;
      uniform vec3 uSunDir;
      uniform vec3 uSunColor;
      uniform vec3 uDeep;
      uniform vec3 uShallow;
      uniform vec3 uZenith;
      uniform vec3 uHorizon;
      uniform float uRain;
      uniform vec2 uWind;
      uniform sampler2D uNormal;
      uniform float uWater;
      #ifdef WH_ENV
      uniform samplerCube uEnv;
      #endif
      varying vec3 vWorld;
      ${TERRAIN_GLSL}
      void main() {
        vec2 p = vWorld.xz;
        vec2 drift = uWind * uTime * 0.012;
        vec3 nA = texture2D(uNormal, p * 0.055 + drift).xyz * 2.0 - 1.0;
        vec3 nB = texture2D(uNormal, p * 0.13 - drift * 1.7 + 0.37).xyz * 2.0 - 1.0;
        vec3 nC = texture2D(uNormal, p * 0.41 + vec2(uTime * 0.05, -uTime * 0.03)).xyz * 2.0 - 1.0;
        vec2 slopeXY = (nA.xy * 0.3 + nB.xy * 0.2 + nC.xy * (0.07 + uRain * 0.45)) * (0.7 + 0.3 * length(uWind));
        vec3 n = normalize(vec3(slopeXY.x, 1.0, slopeXY.y) );
        vec3 v = normalize(cameraPosition - vWorld);
        float cosT = clamp(dot(n, v), 0.0, 1.0);
        float fres = 0.02 + 0.98 * pow(1.0 - cosT, 5.0);
        vec3 r = reflect(-v, n);
        r.y = abs(r.y);
        #ifdef WH_ENV
        vec3 refl = textureCube(uEnv, vec3(r.x, r.y, r.z)).rgb;
        #else
        vec3 refl = mix(uHorizon, uZenith, pow(clamp(r.y, 0.0, 1.0), 0.6));
        #endif
        float depth = uWater - whTerrain(p).r;
        float shallow = 1.0 - smoothstep(0.0, 2.4, depth);
        vec3 body = mix(uDeep, uShallow, shallow * 0.7) * (0.35 + 0.65 * max(uSunDir.y, 0.15));
        vec3 col = mix(body, refl, clamp(fres, 0.0, 1.0));
        float spec = pow(clamp(dot(r, uSunDir), 0.0, 1.0), 380.0) * 2.4 + pow(clamp(dot(r, uSunDir), 0.0, 1.0), 40.0) * 0.08;
        col += uSunColor * spec * 0.35;
        float foam = (1.0 - smoothstep(0.0, 0.16, depth)) * (0.55 + 0.45 * texture2D(uNormal, p * 0.9 + drift * 3.0).z);
        col = mix(col, vec3(0.8, 0.82, 0.8) * (0.5 + 0.5 * max(uSunDir.y, 0.2)), foam * 0.35);
        float alpha = 0.94 * smoothstep(0.0, 0.32, depth);
        alpha = max(alpha, fres * smoothstep(0.0, 0.1, depth));
        alpha = max(alpha, foam * 0.5 * smoothstep(0.0, 0.04, depth));
        gl_FragColor = vec4(col, alpha);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
        #include <fog_fragment>
      }`,
    transparent: true,
    fog: true,
  });
  const geo = new THREE.CircleGeometry(LAKE.r * 1.32, 96);
  geo.rotateX(-Math.PI / 2);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(LAKE.x, terrain.waterLevel, LAKE.z);
  mesh.name = 'lake';
  mesh.renderOrder = 2;
  return mesh;
}

// ═══════════════════════════ 10. НЕБО, АТМОСФЕРА, ЧАС ДОБИ, ПОГОДА, ГОРИ ═══════════════════════════

/*
 * Повітряна перспектива для всіх матеріалів: туман експоненційний і рідшає з висотою
 * (гори видно крізь серпанок, низини затягує), у бік сонця серпанок тепліший.
 * Вбудовані фрагменти шейдерів Three.js замінюються один раз до компіляції матеріалів;
 * туман застосовується до тональної компресії — однаково з постобробкою і без неї.
 */
const HAZE_HEIGHT = 130;
function patchAtmosphereChunks() {
  const C = THREE.ShaderChunk;
  if (C.tonemapping_fragment.includes('WH_FOG')) return;
  C.fog_pars_vertex = '#ifdef USE_FOG\n\tvarying float vFogDepth;\n\tvarying vec3 vFogWorld;\n#endif';
  C.fog_vertex = '#ifdef USE_FOG\n\tvFogDepth = - mvPosition.z;\n\tvFogWorld = transpose(mat3(viewMatrix)) * (mvPosition.xyz - viewMatrix[3].xyz);\n#endif';
  C.fog_pars_fragment = `#ifdef USE_FOG
\tuniform vec3 fogColor;
\tvarying float vFogDepth;
\tvarying vec3 vFogWorld;
\tuniform vec3 whSunDir;
\tuniform vec3 whFogSunDelta;
\t#ifdef FOG_EXP2
\t\tuniform float fogDensity;
\t#else
\t\tuniform float fogNear;
\t\tuniform float fogFar;
\t#endif
#endif`;
  const fog = `// WH_FOG: серпанок до тональної компресії
#ifdef USE_FOG
\t#ifdef FOG_EXP2
\t\tvec3 whFogV = vFogWorld - cameraPosition;
\t\tfloat whFogD = length(whFogV);
\t\tfloat whFogA = max(cameraPosition.y, 0.0) / ${HAZE_HEIGHT.toFixed(1)};
\t\tfloat whFogB = max(vFogWorld.y, 0.0) / ${HAZE_HEIGHT.toFixed(1)};
\t\tfloat whFogH = abs(whFogB - whFogA) > 1e-3 ? (exp(-whFogA) - exp(-whFogB)) / (whFogB - whFogA) : exp(-whFogA);
\t\tfloat fogFactor = 1.0 - exp(-fogDensity * whFogD * whFogH);
\t\tvec3 whFogC = fogColor + whFogSunDelta * pow(max(dot(whFogV / max(whFogD, 1e-3), whSunDir), 0.0), 5.0);
\t#else
\t\tfloat fogFactor = smoothstep(fogNear, fogFar, vFogDepth);
\t\tvec3 whFogC = fogColor;
\t#endif
\tgl_FragColor.rgb = mix(gl_FragColor.rgb, whFogC, fogFactor);
#endif
`;
  C.tonemapping_fragment = fog + C.tonemapping_fragment;
  C.fog_fragment = '';
}

// Матеріалам із туманом передаються напрямок сонця і теплий відтінок серпанку.
function bindAtmosphere(material, atmos) {
  if (!material || material.userData.whAtmos) return;
  material.userData.whAtmos = true;
  const prev = material.onBeforeCompile;
  material.onBeforeCompile = function onCompileAtmos(shader, renderer) {
    if (prev) prev.call(this, shader, renderer);
    shader.uniforms.whSunDir = atmos.u.uSunDir;
    shader.uniforms.whFogSunDelta = atmos.fogSunDelta;
  };
}

function bindAtmosphereTree(root, atmos) {
  root.traverse((o) => {
    if (o.material) for (const m of [].concat(o.material)) bindAtmosphere(m, atmos);
    if (o.customDepthMaterial) bindAtmosphere(o.customDepthMaterial, atmos);
  });
}

// Сонце за годинами: схід на сході (+x), полудень на півдні (+z), захід на заході (−x).
function sunFromHour(hour, out) {
  const t = clamp((hour - 5.6) / 14.8, 0, 1);
  const elev = Math.sin(t * Math.PI) * 52 * DEG - 3 * DEG;
  const az = lerp(112, -112, t) * DEG;
  out.set(Math.cos(elev) * Math.sin(az), Math.sin(elev), Math.cos(elev) * Math.cos(az)).normalize();
  return elev;
}

// Ключові кольори неба за висотою сонця (градуси). Значення — sRGB, переводяться в лінійні.
const SKY_KEYS = [
  { e: -4, zenith: 0x1f2c4c, horizon: 0x5a6276, horizonSun: 0xb8673e, sun: 0xff7a3a, sunI: 0.0, hemiSky: 0x44527a, hemiGround: 0x2b2820, hemiI: 1.5, fog: 1.25, exposure: 2.1 },
  { e: 3, zenith: 0x31508a, horizon: 0x9aa4b4, horizonSun: 0xf29a5a, sun: 0xff9a52, sunI: 1.8, hemiSky: 0x7084a6, hemiGround: 0x3e3a2c, hemiI: 1.65, fog: 1.3, exposure: 1.5 },
  { e: 12, zenith: 0x305fae, horizon: 0xaec0d4, horizonSun: 0xf4c08a, sun: 0xffc48a, sunI: 2.8, hemiSky: 0x8ea8cc, hemiGround: 0x4a4632, hemiI: 1.65, fog: 1.12, exposure: 1.15 },
  { e: 30, zenith: 0x2d64c4, horizon: 0xb6cbe2, horizonSun: 0xe6e2d6, sun: 0xffe6c8, sunI: 3.3, hemiSky: 0x9cb8dc, hemiGround: 0x4f4a36, hemiI: 1.5, fog: 1.0, exposure: 0.92 },
  { e: 60, zenith: 0x2a62c8, horizon: 0xbcd0e6, horizonSun: 0xe2e6e6, sun: 0xfff2e2, sunI: 3.6, hemiSky: 0xa2bcde, hemiGround: 0x524c38, hemiI: 1.5, fog: 0.95, exposure: 0.88 },
];
// Змішування ключових кольорів і чисел неба та «сіріння» кольору (без створення замикань щокадру).
function skyMixC(A, B, t, key, out) {
  return out.copy(A[key]).lerp(B[key], t);
}

function skyMixN(A, B, t, key) {
  return lerp(A[key], B[key], t);
}

function greyColor(c, amount, dark) {
  const l = c.r * 0.3 + c.g * 0.59 + c.b * 0.11;
  c.r = lerp(c.r, l, amount) * dark;
  c.g = lerp(c.g, l, amount) * dark;
  c.b = lerp(c.b, l, amount) * dark;
  return c;
}

const SKY_KEYS_LIN = SKY_KEYS.map((k) => {
  const out = { ...k };
  for (const key of ['zenith', 'horizon', 'horizonSun', 'sun', 'hemiSky', 'hemiGround']) out[key] = null;
  return out;
});

const COMPASS_NAMES = ['Пн', 'ПнСх', 'Сх', 'ПдСх', 'Пд', 'ПдЗх', 'Зх', 'ПнЗх'];
// Параметри погоди, що плавно змінюються (постійний масив — без створення нового щокадру).
const WEATHER_BLEND_KEYS = ['clouds', 'dark', 'sun', 'fog', 'sat', 'rain', 'wind', 'shafts'];
function headingName(deg) {
  return COMPASS_NAMES[Math.round(((deg % 360) + 360) % 360 / 45) % 8];
}

/**
 * Атмосфера: годинник доби, плавна зміна погоди, кольори неба й туману, світло сонця,
 * вітер. Спільні uniform-змінні (this.u) використовують небо, гори, вода, листя й дощ.
 */
class Atmosphere {
  constructor(settings, quality) {
    if (!SKY_KEYS_LIN[0].zenith) {
      SKY_KEYS.forEach((k, i) => {
        for (const key of ['zenith', 'horizon', 'horizonSun', 'sun', 'hemiSky', 'hemiGround']) SKY_KEYS_LIN[i][key] = new THREE.Color(k[key]);
      });
    }
    this.quality = quality;
    this.timeMode = settings.time;
    this.weatherMode = settings.weather;
    this.hour = TIMES[this.timeMode] ? TIMES[this.timeMode].hour : 9;
    this.day = 1;
    const startWeather = WEATHER[this.weatherMode] ? this.weatherMode : 'clear';
    this.weatherKey = startWeather;
    this.w = { ...WEATHER[startWeather] };
    this.weatherTimer = 240 + Math.random() * 180;
    this.windAngle = -0.6 + Math.random() * 0.4;     // звідки віє (радіани від півночі за годинниковою)
    this.windSpeed = 3;
    this.windTimer = 0;
    this.sunDir = new THREE.Vector3(0.3, 0.6, 0.3).normalize();
    this.lightDir = this.sunDir.clone();
    this.elev = 0.5;
    this.changed = true;
    this.envStamp = { hour: -99, weather: '', clouds: -1 };
    this.dayRollover = false;
    this.u = {
      uSunDir: { value: this.sunDir },
      uSunColor: { value: new THREE.Color() },
      uZenith: { value: new THREE.Color() },
      uHorizon: { value: new THREE.Color() },
      uHorizonSun: { value: new THREE.Color() },
      uFogColor: { value: new THREE.Color() },
      uFogSun: { value: new THREE.Color() },
      uHemiSky: { value: new THREE.Color() },
      uHemiGround: { value: new THREE.Color() },
      uCloudCover: { value: 0.34 },
      uCloudDark: { value: 0 },
      uCloudLight: { value: new THREE.Color() },
      uCloudShade: { value: new THREE.Color() },
      uHazeK: { value: 0.0023 },
      uHazeH: { value: 180 },
      uBaseY: { value: 0 },
      uWet: { value: 0 },
      uRain: { value: 0 },
      uSunVis: { value: 1 },
      uWind: { value: new THREE.Vector2(1, 0) },
      uTime: WIND.uTime,
    };
    this.fogDensity = 0.0017;
    this.fogSunDelta = { value: new THREE.Color() };
    this.exposure = 1;
    this.sunIntensity = 3;
    this.hemiIntensity = 1;
    this.tmpA = new THREE.Color();
    this.tmpB = new THREE.Color();
    this.hemiSky = new THREE.Color();
    this.hemiGround = new THREE.Color();
    this.sunColor = new THREE.Color();
    this.recompute();
  }

  setTimeMode(mode) {
    if (!TIMES[mode]) return;
    this.timeMode = mode;
    if (mode !== 'auto') this.hour = TIMES[mode].hour;
    this.changed = true;
  }

  setWeatherMode(mode) {
    if (mode !== 'auto' && !WEATHER[mode]) return;
    this.weatherMode = mode;
    if (mode !== 'auto') this.weatherKey = mode;
    this.weatherTimer = 240 + Math.random() * 240;
    this.changed = true;
  }

  // Миттєво встановити годину та/або погоду (вибір у меню, технічний режим) — без плавного переходу.
  snapTo(hour, weatherKey) {
    if (typeof hour === 'number' && Number.isFinite(hour)) this.hour = clamp(hour, 5, 21);
    if (weatherKey && WEATHER[weatherKey]) {
      this.weatherKey = weatherKey;
      Object.assign(this.w, WEATHER[weatherKey]);
    }
    this.recompute();
  }

  // Плавний перехід погоди та хід годинника.
  update(dt, running) {
    if (this.timeMode === 'auto' && running) {
      this.hour += dt / 60;              // 1 ігрова хвилина за секунду
      if (this.hour > 20.4) {
        this.hour = 6.2;
        this.day++;
        this.dayRollover = true;
      }
      this.changed = true;
    }
    if (this.weatherMode === 'auto' && running) {
      this.weatherTimer -= dt;
      if (this.weatherTimer <= 0) {
        const options = WEATHER_ORDER.filter((k) => k !== this.weatherKey);
        const weights = { clear: 3, cloudy: 2.2, fog: 1, rain: 1.2 };
        let total = 0;
        for (const k of options) total += weights[k];
        let r = Math.random() * total;
        for (const k of options) {
          r -= weights[k];
          if (r <= 0) {
            this.weatherKey = k;
            break;
          }
        }
        this.weatherTimer = 200 + Math.random() * 260;
      }
    }
    const target = WEATHER[this.weatherKey];
    const k = 1 - Math.exp(-dt / 6);
    let moving = false;
    for (let i = 0; i < WEATHER_BLEND_KEYS.length; i++) {
      const key = WEATHER_BLEND_KEYS[i];
      const d = target[key] - this.w[key];
      if (Math.abs(d) > 1e-4) {
        this.w[key] += d * k;
        moving = true;
      }
    }
    if (moving) this.changed = true;
    this.windTimer -= dt;
    if (this.windTimer <= 0) {
      this.windTimer = 8 + Math.random() * 10;
      this.windTarget = this.windAngle + (Math.random() - 0.5) * 0.5;
    }
    if (this.windTarget !== undefined) this.windAngle += (this.windTarget - this.windAngle) * (1 - Math.exp(-dt / 12));
    this.windSpeed = (2.2 + 1.6 * Math.sin(this.u.uTime.value * 0.05)) * this.w.wind;
    // Вектор, куди віє вітер (від напрямку «звідки» на протилежний бік).
    this.u.uWind.value.set(-Math.sin(this.windAngle), Math.cos(this.windAngle));
    WIND.uStrength.value = 0.55 + this.windSpeed * 0.22;
    if (this.changed) this.recompute();
  }

  recompute() {
    this.changed = false;
    const e = sunFromHour(this.hour, this.sunDir);
    this.elev = e;
    // Світло не опускається нижче 4°, щоб тіні не ставали безкінечними.
    const le = Math.max(e, 4 * DEG);
    this.lightDir.set(this.sunDir.x, 0, this.sunDir.z).normalize().multiplyScalar(Math.cos(le));
    this.lightDir.y = Math.sin(le);
    const ed = e / DEG;
    let i = 0;
    while (i < SKY_KEYS.length - 2 && ed > SKY_KEYS[i + 1].e) i++;
    const A = SKY_KEYS_LIN[i];
    const B = SKY_KEYS_LIN[i + 1];
    const t = clamp((ed - A.e) / (B.e - A.e), 0, 1);
    const w = this.w;
    const u = this.u;
    const desat = 1 - w.sat;
    const dark = 1 - w.dark * 0.45;
    greyColor(skyMixC(A, B, t, 'zenith', u.uZenith.value), desat * 1.4, 1 - w.dark * 0.55);
    greyColor(skyMixC(A, B, t, 'horizon', u.uHorizon.value), desat, dark);
    greyColor(skyMixC(A, B, t, 'horizonSun', u.uHorizonSun.value), desat * 1.1, dark);
    u.uHorizonSun.value.lerp(u.uHorizon.value, w.dark * 0.8);
    skyMixC(A, B, t, 'sun', u.uSunColor.value);
    this.sunIntensity = skyMixN(A, B, t, 'sunI') * w.sun;
    u.uSunColor.value.multiplyScalar(this.sunIntensity);
    greyColor(skyMixC(A, B, t, 'hemiSky', this.hemiSky), desat, 1);
    skyMixC(A, B, t, 'hemiGround', this.hemiGround);
    this.hemiIntensity = skyMixN(A, B, t, 'hemiI') * (1 + (1 - w.sun) * 0.25);
    u.uHemiSky.value.copy(this.hemiSky).multiplyScalar(this.hemiIntensity * Math.PI);
    u.uHemiGround.value.copy(this.hemiGround).multiplyScalar(this.hemiIntensity * Math.PI);
    this.sunColor.copy(A.sun).lerp(B.sun, t);
    u.uFogColor.value.copy(u.uHorizon.value).lerp(u.uHorizonSun.value, 0.22);
    u.uFogSun.value.copy(u.uHorizonSun.value).lerp(u.uFogColor.value, w.dark);
    this.fogSunDelta.value.copy(u.uFogSun.value).sub(u.uFogColor.value);
    u.uCloudCover.value = w.clouds;
    u.uCloudDark.value = w.dark;
    u.uCloudLight.value.copy(A.sun).lerp(B.sun, t).lerp(this.tmpA.setRGB(1, 1, 1), 0.55).multiplyScalar(lerp(1.15, 0.7, w.dark));
    u.uCloudShade.value.copy(u.uHorizon.value).multiplyScalar(lerp(0.78, 0.55, w.dark));
    u.uWet.value = w.rain;
    u.uRain.value = w.rain;
    u.uSunVis.value = clamp(1 - w.clouds * 0.6 - w.dark * 0.5, 0, 1) * smoothstep(-0.02, 0.06, this.sunDir.y);
    const fogQ = this.quality ? this.quality.fog : 1;
    this.fogDensity = 0.00055 * fogQ * w.fog * skyMixN(A, B, t, 'fog');
    u.uHazeK.value = this.fogDensity;
    u.uHazeH.value = HAZE_HEIGHT;
    this.exposure = skyMixN(A, B, t, 'exposure') * (1 + (1 - w.sun) * 0.18);
  }

  // Чи потрібно оновити відбиття й освітлення від неба (після помітної зміни часу чи погоди).
  envNeedsUpdate() {
    const st = this.envStamp;
    return Math.abs(this.hour - st.hour) > 0.4 || this.weatherKey !== st.weather || Math.abs(this.w.clouds - st.clouds) > 0.01;
  }

  markEnvUpdated() {
    this.envStamp.hour = this.hour;
    this.envStamp.weather = this.weatherKey;
    this.envStamp.clouds = this.w.clouds;
  }

  clockText() {
    const h = Math.floor(this.hour);
    const m = Math.floor((this.hour - h) * 60);
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  }

  describe() {
    const wind = headingName(this.windAngle / DEG);
    const timeLabel = this.timeMode === 'auto' ? this.clockText() : TIMES[this.timeMode].label;
    return `${timeLabel} · ${WEATHER[this.weatherKey].label} · вітер ${wind} ${this.windSpeed.toFixed(0)} м/с`;
  }
}

function createSky(atmos, cloudTex) {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      ...atmos.u,
      uClouds: { value: cloudTex },
    },
    vertexShader: /* glsl */`
      varying vec3 vDir;
      void main() {
        vDir = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        gl_Position.z = gl_Position.w;   // на далекій площині: тест глибини пропускає лише порожні пікселі
      }`,
    fragmentShader: /* glsl */`
      #include <common>
      uniform vec3 uZenith;
      uniform vec3 uHorizon;
      uniform vec3 uHorizonSun;
      uniform vec3 uSunColor;
      uniform vec3 uSunDir;
      uniform vec3 uFogColor;
      uniform vec3 uFogSun;
      uniform vec3 uCloudLight;
      uniform vec3 uCloudShade;
      uniform float uCloudCover;
      uniform float uCloudDark;
      uniform float uSunVis;
      uniform vec2 uWind;
      uniform float uTime;
      uniform sampler2D uClouds;
      varying vec3 vDir;
      float cloudDensity(vec2 uv) {
        float c = texture2D(uClouds, uv).r * 0.6 + texture2D(uClouds, uv * 2.7 + 0.31).r * 0.27 + texture2D(uClouds, uv * 7.1 + 0.77).r * 0.13;
        c = (c - 0.5) * 2.3 + 0.5;
        return smoothstep(1.0 - uCloudCover - 0.06, 1.0 - uCloudCover + 0.22, c);
      }
      void main() {
        vec3 d = normalize(vDir);
        float y = d.y;
        float sd = dot(d, uSunDir);
        vec2 dh = normalize(d.xz + vec2(1e-5));
        vec2 sh = normalize(uSunDir.xz + vec2(1e-5));
        float toward = pow(dot(dh, sh) * 0.5 + 0.5, 3.0) * (1.0 - smoothstep(0.05, 0.55, uSunDir.y));
        vec3 horizon = mix(uHorizon, uHorizonSun, toward);
        vec3 col = mix(horizon, uZenith, pow(clamp(y, 0.0, 1.0), 0.5));
        float s = max(sd, 0.0);
        col += uSunColor * (pow(s, 8.0) * 0.045 + pow(s, 90.0) * 0.12) * (0.4 + 0.6 * uSunVis);
        vec3 disc = uSunColor * smoothstep(0.99955, 0.99975, sd) * 6.0 * uSunVis;
        col += disc;
        if (y > 0.0) {
          vec2 uv = d.xz / (y + 0.07) * 0.075 + uWind * uTime * 0.0012;
          float den = cloudDensity(uv);
          float toSun = cloudDensity(uv + normalize(uSunDir.xz + vec2(1e-4)) * 0.025);
          float light = clamp(0.58 + (den - toSun) * 2.8, 0.0, 1.0);
          vec3 ccol = mix(uCloudShade, uCloudLight, light);
          ccol *= 0.82 + 0.18 * smoothstep(0.0, 0.6, den);
          ccol += uSunColor * pow(s, 10.0) * 0.08 * (1.0 - den) ;
          float fade = smoothstep(0.0, 0.16, y);
          col = mix(col, ccol, den * fade * (0.82 + 0.15 * uCloudDark));
        }
        float sunAmt = pow(max(sd, 0.0), 5.0);
        vec3 haze = mix(uFogColor, uFogSun, sunAmt);
        col = mix(col, haze, smoothstep(0.08, -0.02, y));
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`,
    side: THREE.BackSide,
    depthWrite: false,
    depthTest: true,
    fog: false,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(5200, 48, 24), mat);
  // Небо — після всіх непрозорих об'єктів: пікселі, закриті горами, лісом і землею, не обчислюються
  // (раніше небо малювалося першим на весь екран, а потім перемальовувалося).
  sky.renderOrder = 20;
  sky.frustumCulled = false;
  sky.name = 'sky';
  return sky;
}

/*
 * Гірське кільце: сітка від краю долини (квадрат 480 м) до радіуса FAR_RADIUS. Перше кільце точно
 * збігається з краєм рельєфу долини, далі форма плавно стає колом. Маски лісу, лук і снігу
 * рахуються на процесорі для кожної вершини (ті самі, що й для далеких дерев), а шейдер додає
 * дрібні деталі: скелі з шарами, кулуари зі снігом, крони лісу, тіні хмар і серпанок.
 */
function farLandMask(noise, x, z, h, slope) {
  const treeline = 720 + 130 * noise.e(x * 0.0007 + 2.1, z * 0.0007 - 1.7);
  const patchy = smoothstep(-0.75, -0.25, noise.d(x * 0.0026 + 4.4, z * 0.0026 - 9.1));
  const forest = (1 - smoothstep(treeline - 90, treeline + 30, h)) * (1 - smoothstep(0.6, 0.82, slope)) * patchy;
  const snowline = 880 + 140 * noise.e(x * 0.00045 + 5.3, z * 0.00045 - 2.6);
  let snow = smoothstep(snowline - 70, snowline + 90, h) * (1 - smoothstep(0.55, 0.8, slope));
  snow = Math.max(snow, smoothstep(snowline + 260, snowline + 460, h) * (1 - smoothstep(0.78, 0.95, slope)));
  const meadow = (1 - smoothstep(0.26, 0.44, slope)) * (1 - snow) * (1 - smoothstep(treeline + 250, treeline + 420, h));
  return { forest, snow, meadow };
}

function createFarTerrain(terrain, quality, atmos, noiseTex, cloudTex) {
  const M = TERRAIN_SEG;
  const P = 4 * M;
  const rings = quality.mountainRings;
  const N = TERRAIN_N;
  const count = (rings + 1) * P;
  const pos = new Float32Array(count * 3);
  for (let k = 0; k <= rings; k++) {
    const t = k / rings;
    const s = WORLD_HALF * Math.pow(FAR_RADIUS / WORLD_HALF, Math.pow(t, 0.9));
    const morph = smoothstep(0, 0.45, t);
    for (let i = 0; i < P; i++) {
      const side = Math.floor(i / M);
      const f = (i % M) / M;
      let qx;
      let qz;
      if (side === 0) {
        qx = -1 + 2 * f;
        qz = -1;
      } else if (side === 1) {
        qx = 1;
        qz = -1 + 2 * f;
      } else if (side === 2) {
        qx = 1 - 2 * f;
        qz = 1;
      } else {
        qx = -1;
        qz = 1 - 2 * f;
      }
      const ql = len2(qx, qz);
      const x = lerp(qx, (qx / ql) * 1.12, morph) * s;
      const z = lerp(qz, (qz / ql) * 1.12, morph) * s;
      let y;
      if (k === 0) {
        const gi = Math.round(((qx + 1) / 2) * M);
        const gj = Math.round(((qz + 1) / 2) * M);
        y = terrain.height[gj * N + gi];
      } else {
        y = terrain.farHeightAt(x, z);
      }
      const o = (k * P + i) * 3;
      pos[o] = x;
      pos[o + 1] = y;
      pos[o + 2] = z;
    }
  }
  const index = new Uint32Array(rings * P * 6);
  let o = 0;
  for (let k = 0; k < rings; k++) {
    for (let i = 0; i < P; i++) {
      const a = k * P + i;
      const b = k * P + ((i + 1) % P);
      const c = (k + 1) * P + i;
      const d = (k + 1) * P + ((i + 1) % P);
      index[o++] = a;
      index[o++] = b;
      index[o++] = c;
      index[o++] = b;
      index[o++] = d;
      index[o++] = c;
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setIndex(new THREE.BufferAttribute(index, 1));
  geo.computeVertexNormals();
  // Маски для кожної вершини: ліс, сніг, луки (той самий розрахунок, що й для далеких дерев).
  const nor = geo.attributes.normal.array;
  const mask = new Float32Array(count * 3);
  const noise = terrain.noise;
  for (let v = 0; v < count; v++) {
    const m = farLandMask(noise, pos[v * 3], pos[v * 3 + 2], pos[v * 3 + 1], 1 - nor[v * 3 + 1]);
    // Біля самої долини (перші кільця) — суцільний ліс, як на краю рельєфу долини.
    const edge = 1 - smoothstep(WORLD_HALF + 10, WORLD_HALF + 160, Math.max(Math.abs(pos[v * 3]), Math.abs(pos[v * 3 + 2])));
    mask[v * 3] = Math.max(m.forest, edge);
    mask[v * 3 + 1] = m.snow;
    mask[v * 3 + 2] = m.meadow;
  }
  geo.setAttribute('aMask', new THREE.BufferAttribute(mask, 3));
  geo.computeBoundingSphere();
  const mat = new THREE.ShaderMaterial({
    uniforms: { ...atmos.u, uNoise: { value: noiseTex }, uClouds: { value: cloudTex } },
    defines: quality.terrainNormals ? { WH_DETAIL: 1 } : {},
    vertexShader: /* glsl */`
      attribute vec3 aMask;
      varying vec3 vW;
      varying vec3 vN;
      varying vec3 vMask;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vW = wp.xyz;
        vN = normalize(mat3(modelMatrix) * normal);
        vMask = aMask;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: /* glsl */`
      #include <common>
      uniform vec3 uSunDir;
      uniform vec3 uSunColor;
      uniform vec3 uHemiSky;
      uniform vec3 uHemiGround;
      uniform vec3 uFogColor;
      uniform vec3 uFogSun;
      uniform float uHazeK;
      uniform float uHazeH;
      uniform float uBaseY;
      uniform float uWet;
      uniform float uCloudCover;
      uniform float uTime;
      uniform vec2 uWind;
      uniform sampler2D uNoise;
      uniform sampler2D uClouds;
      varying vec3 vW;
      varying vec3 vN;
      varying vec3 vMask;
      float nz(vec2 p) { return texture2D(uNoise, p).r; }
      void main() {
        vec3 N = normalize(vN);
        vec2 p = vW.xz;
        vec3 V = vW - cameraPosition;
        float dist = length(V);
        vec3 vd = V / dist;
        float slope = 1.0 - N.y;
        float h = vW.y - uBaseY;
        // Дрібна будова схилів: кілька масштабів шуму, затухають з відстанню.
        float detailFade = 1.0 - smoothstep(2500.0, 6000.0, dist);
        float n1 = nz(p * 0.00071);
        float n2 = nz(p * 0.0029 + 0.37);
        float n3 = nz(p * 0.011 + 0.71);
        float n4 = nz(p * 0.043 + 0.13);
        #ifdef WH_DETAIL
        float e = 6.0;
        float hC = n3 * 0.6 + n4 * 0.4;
        float hX = nz((p + vec2(e, 0.0)) * 0.011 + 0.71) * 0.6 + nz((p + vec2(e, 0.0)) * 0.043 + 0.13) * 0.4;
        float hZ = nz((p + vec2(0.0, e)) * 0.011 + 0.71) * 0.6 + nz((p + vec2(0.0, e)) * 0.043 + 0.13) * 0.4;
        float bump = (0.45 + 1.4 * smoothstep(0.25, 0.7, slope)) * detailFade;
        N = normalize(N + vec3(hC - hX, 0.0, hC - hZ) * 9.0 * bump);
        #endif
        // Маски з вершин + дрібне «розмиття» країв шумом.
        float forest = smoothstep(0.35, 0.65, vMask.x + (n3 - 0.5) * 0.45 + (n4 - 0.5) * 0.25);
        float snowN = vMask.y + (n2 - 0.5) * 0.35 + (n4 - 0.5) * 0.3 - smoothstep(0.45, 0.8, slope) * 0.25;
        float snow = smoothstep(0.42, 0.58, snowN);
        float meadow = smoothstep(0.3, 0.7, vMask.z + (n3 - 0.5) * 0.6) * (1.0 - snow);
        // Скеля: сіро-коричневий вапняк із горизонтальними шарами й темними тріщинами.
        float strata = sin(h * 0.11 + n2 * 7.0 + n3 * 2.0) * 0.5 + 0.5;
        vec3 rock = mix(vec3(0.14, 0.13, 0.12), vec3(0.33, 0.31, 0.28), n3 * 0.7 + strata * 0.3);
        rock *= 0.72 + 0.45 * n4;
        rock = mix(rock, vec3(0.2, 0.19, 0.18), smoothstep(0.62, 0.3, n4) * 0.5);
        vec3 meadowCol = mix(vec3(0.075, 0.105, 0.035), vec3(0.16, 0.15, 0.07), n2 * 0.6 + n4 * 0.4);
        meadowCol = mix(meadowCol, rock * 0.9, smoothstep(0.55, 0.8, n4) * 0.6);
        // Ліс: темні крони з просвітами — «зернистість» дрібного шуму.
        float crowns = nz(p * 0.21 + 0.5) * 0.6 + nz(p * 0.53) * 0.4;
        vec3 forestCol = mix(vec3(0.018, 0.034, 0.018), vec3(0.07, 0.1, 0.045), smoothstep(0.35, 0.8, crowns));
        forestCol *= 0.85 + 0.3 * n3;
        vec3 snowCol = mix(vec3(0.78, 0.81, 0.88), vec3(0.95, 0.96, 0.98), n4);
        vec3 col = mix(rock, meadowCol, meadow);
        col = mix(col, forestCol, forest);
        col = mix(col, snowCol, snow);
        col *= 1.0 - uWet * 0.18 * (1.0 - snow);
        // Освітлення: сонце (з «обгортанням» для лісу), небо, відбите від землі, тіні хмар.
        float ndl = dot(N, uSunDir);
        float wrap = mix(0.0, 0.25, forest);
        float diff = max((ndl + wrap) / (1.0 + wrap), 0.0);
        vec2 cuv = p * 0.000085 + uWind * uTime * 0.0012 * 0.3;
        float cl = texture2D(uClouds, cuv).r * 0.7 + texture2D(uClouds, cuv * 2.7 + 0.31).r * 0.3;
        float shadow = 1.0 - smoothstep(1.0 - uCloudCover - 0.12, 1.0 - uCloudCover + 0.28, cl) * 0.7;
        float ao = mix(1.0, 0.75 + 0.25 * crowns, forest);
        vec3 irr = uSunColor * diff * shadow + mix(uHemiGround, uHemiSky, N.y * 0.5 + 0.5) * ao;
        vec3 lit = col * irr * RECIPROCAL_PI;
        vec3 R = reflect(vd, N);
        lit += uSunColor * snow * pow(max(dot(R, uSunDir), 0.0), 18.0) * 0.035 * shadow;
        // Повітряна перспектива (та сама модель, що й для решти матеріалів).
        float a = max(cameraPosition.y - uBaseY, 0.0) / uHazeH;
        float b = max(vW.y - uBaseY, 0.0) / uHazeH;
        float hf = abs(b - a) > 1e-3 ? (exp(-a) - exp(-b)) / (b - a) : exp(-a);
        float fog = 1.0 - exp(-dist * uHazeK * hf);
        vec3 fogCol = mix(uFogColor, uFogSun, pow(max(dot(vd, uSunDir), 0.0), 5.0));
        gl_FragColor = vec4(mix(lit, fogCol, fog), 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`,
    fog: false,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.name = 'mountains';
  mesh.renderOrder = 10;     // після рельєфу долини й рослинності — закриті ними пікселі гір не обчислюються
  mesh.frustumCulled = false;
  mesh.matrixAutoUpdate = false;
  mesh.receiveShadow = false;
  return mesh;
}

// Точки для далекого лісу на схилах гір (імпостери): там, де маска лісу в шейдері гір.
function farForestPoints(terrain, count, rand) {
  const out = [];
  if (!count) return out;
  const noise = terrain.noise;
  let tries = 0;
  while (out.length < count && tries < count * 10) {
    tries++;
    const a = rand() * Math.PI * 2;
    const d = WORLD_HALF + 8 + Math.pow(rand(), 1.45) * 2300;
    const x = Math.cos(a) * d;
    const z = Math.sin(a) * d;
    if (Math.max(Math.abs(x), Math.abs(z)) < WORLD_HALF + 6) continue;
    const h = terrain.farHeightAt(x, z);
    const hx = terrain.farHeightAt(x + 8, z) - h;
    const hz = terrain.farHeightAt(x, z + 8) - h;
    const slope = 1 - 1 / len3(hx / 8, hz / 8, 1);
    const m = farLandMask(noise, x, z, h, slope);
    if (rand() > m.forest * 0.95) continue;
    out.push({ x, y: h - 1.0, z, scale: 0.85 + rand() * 0.6, rot: rand() * Math.PI * 2, conifer: rand() < 0.78 + h * 0.0006 });
  }
  return out;
}

// Дощ: тонкі смуги, що «загортаються» навколо камери у вершинному шейдері (без роботи процесора).
function createRain(capacity, atmos) {
  const geo = new THREE.PlaneGeometry(0.012, 0.75);
  geo.translate(0, 0.375, 0);
  const offs = new Float32Array(capacity * 3);
  for (let i = 0; i < capacity; i++) {
    offs[i * 3] = Math.random();
    offs[i * 3 + 1] = Math.random();
    offs[i * 3 + 2] = Math.random();
  }
  geo.setAttribute('aOff', new THREE.InstancedBufferAttribute(offs, 3));
  const uniforms = { ...atmos.u, uCenter: { value: new THREE.Vector3() }, uBox: { value: new THREE.Vector3(28, 18, 28) } };
  const mat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: /* glsl */`
      attribute vec3 aOff;
      uniform vec3 uCenter;
      uniform vec3 uBox;
      uniform float uTime;
      uniform vec2 uWind;
      varying float vA;
      void main() {
        vec3 o = aOff * uBox;
        o.y -= uTime * (9.0 + aOff.x * 3.0);
        vec3 rel = mod(o - uCenter + 0.5 * uBox, uBox) - 0.5 * uBox;
        vec3 base = uCenter + rel;
        vec3 toCam = normalize(vec3(cameraPosition.x - base.x, 0.0, cameraPosition.z - base.z) + vec3(1e-4));
        vec3 side = vec3(toCam.z, 0.0, -toCam.x);
        vec3 p = base + side * position.x + vec3(uWind.x * 0.18, 1.0, uWind.y * 0.18) * position.y;
        vA = 1.0 - smoothstep(0.35, 0.5, length(rel.xz) / uBox.x);
        gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
      }`,
    fragmentShader: /* glsl */`
      uniform float uRain;
      varying float vA;
      void main() {
        gl_FragColor = vec4(vec3(0.72, 0.76, 0.8), 0.16 * uRain * vA);
      }`,
    transparent: true,
    depthWrite: false,
    fog: false,
  });
  const mesh = new THREE.InstancedMesh(geo, mat, capacity);
  mesh.frustumCulled = false;
  mesh.count = capacity;
  mesh.visible = false;
  mesh.name = 'rain';
  mesh.renderOrder = 5;
  return { mesh, uniforms, capacity };
}

/**
 * Освітлення від оточення й відбиття у воді: кубічна карта знімається з центру озера
 * (небо, гори, ліс), з неї будується PMREM для PBR-матеріалів. Оновлюється рідко —
 * після помітної зміни часу доби чи погоди.
 */
// Шари Three.js: 0 — усе; 1 — лише для знімка оточення (спрощений ліс-імпостери);
// 2 — лише для основної камери (рослинність із відсіканням, трава, вода, тварини, зброя).
const LAYER_PROBE = 1;
const LAYER_MAIN = 2;

/*
 * Знімок оточення з центру озера: відбиття у воді й освітлення PBR-матеріалів.
 * Камера знімка бачить небо, гори, рельєф, далекий ліс, будівлі й спрощений ліс (шар 1).
 * Під час гри знімок оновлюється частинами — одна грань куба за кадр, далі фільтрація для PBR,
 * — щоб не було просідання FPS на кілька кадрів одразу.
 */
class EnvironmentProbe {
  constructor(renderer, scene, quality, position) {
    this.renderer = renderer;
    this.scene = scene;
    this.size = quality.waterCube;
    this.rt = new THREE.WebGLCubeRenderTarget(this.size, { type: THREE.HalfFloatType, generateMipmaps: true, minFilter: THREE.LinearMipmapLinearFilter });
    this.cam = new THREE.CubeCamera(0.5, CAMERA_FAR, this.rt);
    this.cam.position.copy(position);
    for (const c of this.cam.children) {
      c.layers.set(0);
      c.layers.enable(LAYER_PROBE);
    }
    this.pmrem = new THREE.PMREMGenerator(renderer);
    this.envRT = null;
    this.face = -1;
    this.lastTime = -1e9;
  }

  get texture() {
    return this.rt.texture;
  }

  get busy() {
    return this.face >= 0;
  }

  // Повний знімок одразу (під час завантаження світу).
  captureNow(prepare, restore) {
    if (prepare) prepare(this.cam.position);
    this.cam.update(this.renderer, this.scene);
    if (restore) restore();
    this.filter();
  }

  begin() {
    this.cam.updateMatrixWorld();
    this.face = 0;
  }

  // Наступна частина знімка: грань куба (0–5) або фільтрація. Повертає true, коли знімок готовий.
  step(prepare, restore) {
    if (this.face < 0) return false;
    if (this.face < 6) {
      const r = this.renderer;
      const tex = this.rt.texture;
      const prev = r.getRenderTarget();
      if (prepare) prepare(this.cam.position);
      tex.generateMipmaps = this.face === 5;      // mip-рівні — після останньої грані
      r.setRenderTarget(this.rt, this.face);
      r.render(this.scene, this.cam.children[this.face]);
      r.setRenderTarget(prev);
      tex.generateMipmaps = true;
      if (restore) restore();
      this.face++;
      return false;
    }
    this.filter();
    this.face = -1;
    return true;
  }

  // Префільтрована карта для PBR; ціль рендерингу використовується повторно.
  filter() {
    this.envRT = this.pmrem.fromCubemap(this.rt.texture, this.envRT);
    this.scene.environment = this.envRT.texture;
    this.lastTime = performance.now();
  }
}

// ═══════════════════════════ 11. ТВАРИНИ ═══════════════════════════
/*
 * Види тварин, процедурні моделі та поведінка.
 * Модель кожного виду — один SkinnedMesh (один виклик малювання на тварину): частини тіла
 * («лофт» уздовж кісток) жорстко прив'язані до кісток скелета, анімація повертає кістки.
 * Це ТИМЧАСОВІ процедурні моделі, а не фотореалістичні: їх можна замінити готовими GLB
 * через assets/manifest.json (див. розділ 14). Інтерфейс моделі: object + update(dt, pose).
 */

