function animalPalette(kind, female) {
  const c = (hex) => new THREE.Color(hex);
  if (kind === 'boar') {
    return {
      back: c(0x2c2722), side: c(0x3d3530), belly: c(0x4a423b), rump: c(0x3a332d),
      neck: c(0x332c27), mane: c(0x1d1a17), throat: c(0x463e37),
      head: c(0x3a332d), faceTop: c(0x2b2622), muzzle: c(0x5a4d46), nose: c(0x3a2f2c), eye: c(0x0b0909),
      earOut: c(0x2a2420), earIn: c(0x4a3e38), leg: c(0x241f1c), legLow: c(0x1c1816), hoof: c(0x141110),
      tusk: c(0xe6dccb), tailTop: c(0x221d1a), tailUnder: c(0x2e2724),
    };
  }
  if (kind === 'bear') {
    return {
      back: c(0x382719), side: c(0x4a3423), belly: c(0x3a2a1d), rump: c(0x3e2c1d),
      neck: c(0x45301f), mane: c(0x2e2015), throat: c(0x3c2b1d),
      head: c(0x4a3524), faceTop: c(0x3e2c1e), muzzle: c(0x6e5440), nose: c(0x151110), eye: c(0x090706),
      earOut: c(0x3a2a1c), earIn: c(0x2a1e15), leg: c(0x2d2017), legLow: c(0x241a12), hoof: c(0x1a1410),
      tailTop: c(0x3a2a1c), tailUnder: c(0x3a2a1c),
    };
  }
  if (kind === 'roe') {
    const roe = {
      back: c(0x7a4e2c), side: c(0x9a6538), belly: c(0xc2a582), rump: c(0xeee6d8),
      neck: c(0x8a5c34), mane: c(0x6a4426), throat: c(0xcdbfa6),
      head: c(0x8e6240), faceTop: c(0x6e4b32), muzzle: c(0x2a221d), nose: c(0x121010), eye: c(0x0e0c0a),
      earOut: c(0x7e5636), earIn: c(0xc9b394), leg: c(0x85603f), legLow: c(0x9c7b5c), hoof: c(0x24201c),
      antlerBase: c(0x5a4735), antlerTip: c(0xd9cbb0), tailTop: c(0xe9e2d6), tailUnder: c(0xf2ede4),
    };
    return mutePalette(roe, 0.75, 0.92);
  }
  const p = {
    back: c(0x654832), side: c(0x8a6646), belly: c(0xbfa98c), rump: c(0xd8ccb6),
    neck: c(0x6e5038), mane: c(0x4b3522), throat: c(0xcfc3ad),
    head: c(0x84634a), faceTop: c(0x634935), muzzle: c(0xa8927a), nose: c(0x1d1a17), eye: c(0x0e0c0a),
    earOut: c(0x6f5139), earIn: c(0xc2b098),
    leg: c(0x77593f), legLow: c(0x93795e), hoof: c(0x272320),
    antlerBase: c(0x5a4735), antlerTip: c(0xe4d7b9),
    tailTop: c(0x4e3826), tailUnder: c(0xece6da),
  };
  if (female) {
    p.back = c(0x76563c);
    p.side = c(0x977252);
    p.neck = c(0x86644a);
    p.mane = c(0x6c4f37);
  }
  return mutePalette(p, 0.72, 0.9);
}

// Приглушення кольорів хутра (насиченість і яскравість), щоб у тонуванні ACES не було «помаранчевого пластику».
function mutePalette(p, sat, light) {
  const hsl = { h: 0, s: 0, l: 0 };
  for (const key of Object.keys(p)) {
    if (key === 'eye' || key === 'nose' || key === 'hoof' || key === 'tusk' || key === 'antlerTip') continue;
    p[key].getHSL(hsl);
    p[key].setHSL(hsl.h, hsl.s * sat, hsl.l * light);
  }
  return p;
}

// Кут ноги протягом кроку: опора (нога йде назад) і перенесення (нога йде вперед).
function legSwing(phase, duty, amp) {
  if (phase < duty) return amp * (1 - 2 * (phase / duty));
  const t = (phase - duty) / (1 - duty);
  return amp * (-1 + 2 * t * t * (3 - 2 * t));
}

function legLift(phase, duty) {
  if (phase < duty) return 0;
  return Math.sin(Math.PI * (phase - duty) / (1 - duty));
}

// Тулуб за профілем: [z, центр y, півширина, верх, низ].
function torsoFromProfile(S, P, opts = {}) {
  const g = loft(S.map((s) => V3(0, s[1], s[0])), S.map((s) => [s[2], s[3], s[4]]),
    { radial: opts.radial || 20, up: V3(0, 1, 0), capStart: true, capEnd: true });
  const zMin = S[0][0];
  return paintGeometry(g, (p, n, c) => {
    c.copy(P.belly).lerp(P.side, smoothstep(-0.8, -0.15, n.y)).lerp(P.back, smoothstep(0.3, 0.95, n.y) * 0.85);
    if (opts.rump) {
      const rump = smoothstep(zMin + 0.22, zMin + 0.06, p.z) * (1 - smoothstep(0.08, 0.16, Math.abs(p.x))) * smoothstep(-0.2, 0.05, p.y);
      c.lerp(P.rump, rump * 0.9);
    }
    c.multiplyScalar(0.9 + (opts.fur || 0.14) * valueNoise3(p.x * 7, p.y * 7, p.z * 7));
  });
}

function headFromProfile(S, P, noseZ, opts = {}) {
  const g = loft(S.map((s) => V3(0, s[1], s[0])), S.map((s) => [s[2], s[3], s[4]]),
    { radial: opts.radial || 12, capStart: true, capEnd: true, up: V3(0, 1, 0) });
  return paintGeometry(g, (p, n, c) => {
    c.copy(P.head).lerp(P.faceTop, smoothstep(0.45, 0.95, n.y) * 0.5);
    c.lerp(P.muzzle, smoothstep(noseZ - 0.16, noseZ - 0.06, p.z) * 0.75);
    c.lerp(P.throat, smoothstep(-0.4, -0.85, n.y) * 0.5);
    if (p.z > noseZ && (opts.noseAll || p.y > S[S.length - 1][1] - 0.02)) c.copy(P.nose);
  });
}

function eyesFor(P, x, y, z, r) {
  const out = [];
  for (const side of [-1, 1]) {
    const eye = blobGeometry(1, r, r * 0.9, r, 0.05, 3);
    eye.translate(side * x, y, z);
    out.push(paintGeometry(eye, (p, n, c) => c.copy(P.eye)));
  }
  return out;
}

function deerAntlers(P, s, small) {
  const k = small ? 0.42 : 1;
  const sc = (v) => V3(v.x * (small ? 0.8 : 1), 0.085 + (v.y - 0.085) * k, v.z * (small ? 0.7 : 1));
  const beam = [V3(s * 0.045, 0.085, -0.05), V3(s * 0.09, 0.2, -0.11), V3(s * 0.19, 0.38, -0.16),
    V3(s * 0.27, 0.55, -0.13), V3(s * 0.31, 0.69, -0.05), V3(s * 0.3, 0.78, 0.03)].map(sc);
  const tines = small
    ? [[[V3(s * 0.07, 0.17, -0.09), V3(s * 0.09, 0.22, -0.02), V3(s * 0.1, 0.27, 0.03)], [0.012, 0.008, 0.003]]]
    : [
      [[V3(s * 0.06, 0.13, -0.075), V3(s * 0.09, 0.17, 0.04), V3(s * 0.1, 0.24, 0.13)], [0.016, 0.011, 0.004]],
      [[V3(s * 0.15, 0.31, -0.15), V3(s * 0.19, 0.38, -0.04), V3(s * 0.21, 0.46, 0.05)], [0.014, 0.01, 0.004]],
      [[V3(s * 0.25, 0.51, -0.14), V3(s * 0.3, 0.6, -0.06), V3(s * 0.33, 0.68, 0)], [0.012, 0.009, 0.003]],
      [[V3(s * 0.29, 0.64, -0.09), V3(s * 0.34, 0.74, -0.14), V3(s * 0.36, 0.82, -0.16)], [0.011, 0.008, 0.003]],
    ];
  const w = small ? 0.75 : 1;
  const list = [loft(beam, [0.027, 0.023, 0.019, 0.016, 0.012, 0.005].map((r) => r * w), { radial: 6, capEnd: true })];
  for (const [pts, radii] of tines) list.push(loft(pts, radii.map((r) => r * w), { radial: 5, capEnd: true }));
  for (const g of list) paintGeometry(g, (p, n, c) => c.copy(P.antlerBase).lerp(P.antlerTip, smoothstep(0.12, 0.7 * k, p.y) * 0.7 + 0.15));
  return list;
}

function legParts(P, upperPts, upperSec, lowerPts, lowerSec, side, hoofY) {
  const upper = paintGeometry(loft(upperPts, upperSec, { radial: 8 }), (p, n, c) => {
    c.copy(P.side).lerp(P.leg, smoothstep(0, -0.25, p.y)).lerp(P.belly, smoothstep(0.2, 0.9, -n.x * side) * 0.3);
  });
  const lower = paintGeometry(loft(lowerPts, lowerSec, { radial: 7, capEnd: true }), (p, n, c) => {
    c.copy(P.leg).lerp(P.legLow, smoothstep(-0.05, -0.2, p.y));
    if (p.y < hoofY) c.copy(P.hoof);
  });
  return { upper, lower };
}

// «Набір» моделі виду: кістки (ім'я, батько, положення) і частини тіла, прив'язані до кісток.
function buildAnimalKit(kind, female) {
  const P = animalPalette(kind, female);
  const bones = [];
  const parts = [];
  const bone = (name, parent, x, y, z) => bones.push({ name, parent, pos: [x, y, z] });
  const part = (b, g) => parts.push({ bone: b, geometry: g });
  let legs;
  let bodyY;
  if (kind === 'deer' || kind === 'roe') {
    bodyY = 0.95;
    bone('body', null, 0, bodyY, 0);
    bone('neck', 'body', 0, 0.13, 0.5);
    bone('head', 'neck', 0, 0.6, 0);
    bone('earL', 'head', -0.065, 0.085, -0.075);
    bone('earR', 'head', 0.065, 0.085, -0.075);
    bone('tail', 'body', 0, 0.12, -0.76);
    part('body', torsoFromProfile([
      [-0.8, 0.06, 0.03, 0.03, 0.03], [-0.76, 0.05, 0.12, 0.14, 0.14], [-0.68, 0.04, 0.18, 0.21, 0.22],
      [-0.55, 0.03, 0.205, 0.24, 0.25], [-0.38, 0.01, 0.21, 0.24, 0.24], [-0.18, 0, 0.215, 0.235, 0.215],
      [0.02, 0.01, 0.22, 0.245, 0.25], [0.22, 0.03, 0.215, 0.26, 0.29], [0.4, 0.05, 0.195, 0.27, 0.3],
      [0.54, 0.04, 0.17, 0.24, 0.27], [0.64, 0.02, 0.12, 0.17, 0.2], [0.7, 0.01, 0.05, 0.08, 0.09],
      [0.72, 0.01, 0.01, 0.012, 0.012],
    ], P, { rump: true }));
    const neckPts = [V3(0, -0.1, -0.05), V3(0, 0.12, -0.01), V3(0, 0.36, 0.015), V3(0, 0.54, 0), V3(0, 0.64, -0.02)];
    const neckSecs = [[0.14, 0.18, 0.14], [0.105, 0.145, 0.105], [0.085, 0.115, 0.085], [0.075, 0.095, 0.075], [0.065, 0.075, 0.065]];
    part('neck', paintGeometry(loft(neckPts, neckSecs, { radial: 14 }), (p, n, c) => {
      c.copy(P.neck).lerp(P.mane, smoothstep(0.1, -0.8, n.z) * 0.55);
      c.lerp(P.throat, smoothstep(0.4, 0.58, p.y) * smoothstep(0.3, 0.85, n.z));
      c.multiplyScalar(0.92 + 0.14 * valueNoise3(p.x * 8, p.y * 8, p.z * 8));
    }));
    const head = [headFromProfile([
      [-0.1, 0.02, 0.05, 0.06, 0.06], [-0.06, 0.03, 0.082, 0.09, 0.08], [0.02, 0.03, 0.092, 0.095, 0.085],
      [0.1, 0.01, 0.074, 0.075, 0.075], [0.2, -0.01, 0.058, 0.06, 0.066], [0.28, -0.02, 0.05, 0.05, 0.056],
      [0.33, -0.03, 0.042, 0.04, 0.046], [0.355, -0.035, 0.02, 0.02, 0.022],
    ], P, 0.325), ...eyesFor(P, 0.083, 0.048, 0.035, 0.019)];
    if (!female) for (const s of [-1, 1]) head.push(...deerAntlers(P, s, kind === 'roe'));
    part('head', mergeGeometries(head));
    const earGeo = blobGeometry(1, 0.042, 0.1, 0.017, 0.08, 7, 0.3);
    earGeo.translate(0, 0.09, 0);
    paintGeometry(earGeo, (p, n, c) => c.copy(P.earOut).lerp(P.earIn, smoothstep(0.1, 0.7, n.z) * 0.8));
    part('earL', earGeo);
    part('earR', earGeo.clone());
    const tailG = loft([V3(0, 0.02, 0), V3(0, -0.07, -0.035), V3(0, -0.15, -0.045), V3(0, -0.21, -0.035)],
      [[0.045, 0.03, 0.035], [0.05, 0.03, 0.035], [0.04, 0.025, 0.03], [0.012, 0.01, 0.01]], { radial: 8, capEnd: true });
    part('tail', paintGeometry(tailG, (p, n, c) => c.copy(P.tailTop).lerp(P.tailUnder, smoothstep(-0.2, 0.5, n.z))));
    legs = [
      { name: 'FL', front: true, side: -1, hip: [-0.115, -0.1, 0.42], knee: [0, -0.45, 0] },
      { name: 'FR', front: true, side: 1, hip: [0.115, -0.1, 0.42], knee: [0, -0.45, 0] },
      { name: 'BL', front: false, side: -1, hip: [-0.125, -0.02, -0.52], knee: [0, -0.55, -0.11] },
      { name: 'BR', front: false, side: 1, hip: [0.125, -0.02, -0.52], knee: [0, -0.55, -0.11] },
    ];
    for (const L of legs) {
      bone(`hip${L.name}`, 'body', ...L.hip);
      bone(`knee${L.name}`, `hip${L.name}`, ...L.knee);
      const lp = L.front
        ? legParts(P, [V3(0, 0.06, 0), V3(0, -0.18, -0.035), V3(0, -0.45, 0)], [[0.085, 0.11, 0.1], [0.06, 0.075, 0.07], [0.035, 0.04, 0.04]],
          [V3(0, 0, 0), V3(0, -0.2, 0), V3(0, -0.34, 0.01), V3(0, -0.38, 0.03), V3(0, -0.405, 0.045)], [0.034, 0.026, 0.028, 0.032, 0.03], L.side, -0.355)
        : legParts(P, [V3(0, 0.08, 0.02), V3(0, -0.22, 0.09), V3(0, -0.4, -0.04), V3(0, -0.55, -0.11)], [[0.11, 0.14, 0.17], [0.085, 0.1, 0.12], [0.05, 0.055, 0.065], [0.035, 0.04, 0.045]],
          [V3(0, 0, 0), V3(0, -0.2, 0.03), V3(0, -0.32, 0.05), V3(0, -0.36, 0.07), V3(0, -0.385, 0.085)], [0.032, 0.025, 0.027, 0.031, 0.029], L.side, -0.355);
      part(`hip${L.name}`, lp.upper);
      part(`knee${L.name}`, lp.lower);
    }
  } else if (kind === 'boar') {
    bodyY = 0.58;
    bone('body', null, 0, bodyY, 0);
    bone('neck', 'body', 0, 0.1, 0.42);
    bone('head', 'neck', 0, 0.24, 0);
    bone('earL', 'head', -0.08, 0.11, -0.07);
    bone('earR', 'head', 0.08, 0.11, -0.07);
    bone('tail', 'body', 0, 0.1, -0.6);
    part('body', torsoFromProfile([
      [-0.64, 0.04, 0.04, 0.04, 0.04], [-0.6, 0.04, 0.15, 0.17, 0.16], [-0.5, 0.03, 0.22, 0.24, 0.23],
      [-0.32, 0.02, 0.25, 0.27, 0.26], [-0.1, 0.02, 0.26, 0.29, 0.27], [0.12, 0.04, 0.26, 0.33, 0.27],
      [0.3, 0.05, 0.25, 0.35, 0.26], [0.44, 0.04, 0.22, 0.31, 0.24], [0.52, 0.03, 0.17, 0.24, 0.2],
      [0.57, 0.02, 0.09, 0.12, 0.11], [0.59, 0.02, 0.02, 0.02, 0.02],
    ], P, { fur: 0.26 }));
    // Щетина вздовж хребта.
    const mane = loft([V3(0, 0.27, -0.36), V3(0, 0.33, -0.05), V3(0, 0.39, 0.22), V3(0, 0.36, 0.42)],
      [[0.04, 0.05, 0.01], [0.05, 0.07, 0.01], [0.05, 0.08, 0.01], [0.03, 0.04, 0.01]], { radial: 6 });
    part('body', paintGeometry(mane, (p, n, c) => c.copy(P.mane).multiplyScalar(0.8 + 0.4 * valueNoise3(p.z * 30, p.y * 20, 0))));
    part('neck', paintGeometry(loft([V3(0, -0.1, -0.06), V3(0, 0.06, -0.02), V3(0, 0.2, 0.0), V3(0, 0.27, -0.01)],
      [[0.2, 0.24, 0.2], [0.19, 0.22, 0.19], [0.16, 0.18, 0.16], [0.14, 0.15, 0.14]], { radial: 12 }), (p, n, c) => {
      c.copy(P.neck).lerp(P.mane, smoothstep(0.1, -0.8, n.z) * 0.6).multiplyScalar(0.88 + 0.24 * valueNoise3(p.x * 9, p.y * 9, p.z * 9));
    }));
    const head = [headFromProfile([
      [-0.14, 0.02, 0.11, 0.13, 0.12], [-0.06, 0.03, 0.14, 0.15, 0.14], [0.04, 0.02, 0.13, 0.13, 0.13],
      [0.14, 0.0, 0.1, 0.1, 0.11], [0.24, -0.02, 0.075, 0.075, 0.08], [0.33, -0.03, 0.06, 0.06, 0.065],
      [0.38, -0.035, 0.058, 0.058, 0.06], [0.395, -0.035, 0.05, 0.05, 0.05], [0.4, -0.035, 0.01, 0.01, 0.01],
    ], P, 0.385, { noseAll: true }), ...eyesFor(P, 0.1, 0.06, 0.06, 0.014)];
    if (!female) {
      for (const s of [-1, 1]) {
        head.push(paintGeometry(loft([V3(s * 0.055, -0.05, 0.27), V3(s * 0.085, -0.005, 0.3), V3(s * 0.09, 0.045, 0.27)],
          [0.014, 0.01, 0.002], { radial: 5, capEnd: true }), (p, n, c) => c.copy(P.tusk)));
      }
    }
    part('head', mergeGeometries(head));
    const earGeo = blobGeometry(1, 0.035, 0.075, 0.016, 0.1, 9, 0.3);
    earGeo.translate(0, 0.06, 0);
    paintGeometry(earGeo, (p, n, c) => c.copy(P.earOut).lerp(P.earIn, smoothstep(0.1, 0.7, n.z) * 0.6));
    part('earL', earGeo);
    part('earR', earGeo.clone());
    part('tail', paintGeometry(loft([V3(0, 0, 0), V3(0, -0.1, -0.03), V3(0, -0.2, -0.02), V3(0, -0.24, -0.02)],
      [0.022, 0.015, 0.012, 0.03], { radial: 6, capEnd: true }), (p, n, c) => c.copy(P.tailTop)));
    legs = [
      { name: 'FL', front: true, side: -1, hip: [-0.12, -0.12, 0.34], knee: [0, -0.24, 0] },
      { name: 'FR', front: true, side: 1, hip: [0.12, -0.12, 0.34], knee: [0, -0.24, 0] },
      { name: 'BL', front: false, side: -1, hip: [-0.13, -0.08, -0.42], knee: [0, -0.26, -0.04] },
      { name: 'BR', front: false, side: 1, hip: [0.13, -0.08, -0.42], knee: [0, -0.26, -0.04] },
    ];
    for (const L of legs) {
      bone(`hip${L.name}`, 'body', ...L.hip);
      bone(`knee${L.name}`, `hip${L.name}`, ...L.knee);
      const lp = L.front
        ? legParts(P, [V3(0, 0.06, 0), V3(0, -0.12, -0.01), V3(0, -0.24, 0)], [[0.08, 0.1, 0.1], [0.06, 0.065, 0.065], [0.036, 0.036, 0.036]],
          [V3(0, 0, 0), V3(0, -0.14, 0), V3(0, -0.2, 0.01), V3(0, -0.225, 0.03), V3(0, -0.24, 0.04)], [0.034, 0.027, 0.029, 0.031, 0.028], L.side, -0.205)
        : legParts(P, [V3(0, 0.07, 0.02), V3(0, -0.12, 0.06), V3(0, -0.26, -0.04)], [[0.1, 0.12, 0.13], [0.07, 0.075, 0.08], [0.037, 0.04, 0.04]],
          [V3(0, 0, 0), V3(0, -0.13, 0.02), V3(0, -0.19, 0.03), V3(0, -0.215, 0.05), V3(0, -0.23, 0.06)], [0.034, 0.027, 0.029, 0.031, 0.028], L.side, -0.195);
      part(`hip${L.name}`, lp.upper);
      part(`knee${L.name}`, lp.lower);
    }
  } else {
    bodyY = 0.84;
    bone('body', null, 0, bodyY, 0);
    bone('neck', 'body', 0, 0.16, 0.6);
    bone('head', 'neck', 0, 0.33, 0);
    bone('earL', 'head', -0.12, 0.15, -0.03);
    bone('earR', 'head', 0.12, 0.15, -0.03);
    bone('tail', 'body', 0, 0.14, -0.86);
    part('body', torsoFromProfile([
      [-0.9, 0.05, 0.05, 0.05, 0.05], [-0.86, 0.05, 0.22, 0.24, 0.22], [-0.72, 0.04, 0.33, 0.36, 0.33],
      [-0.5, 0.03, 0.38, 0.41, 0.37], [-0.2, 0.02, 0.4, 0.42, 0.38], [0.1, 0.04, 0.4, 0.45, 0.38],
      [0.36, 0.06, 0.39, 0.49, 0.37], [0.56, 0.06, 0.34, 0.44, 0.33], [0.7, 0.05, 0.26, 0.32, 0.26],
      [0.78, 0.04, 0.14, 0.16, 0.14], [0.81, 0.04, 0.03, 0.03, 0.03],
    ], P, { radial: 22, fur: 0.3 }));
    part('neck', paintGeometry(loft([V3(0, -0.1, -0.08), V3(0, 0.08, -0.03), V3(0, 0.26, 0), V3(0, 0.35, -0.02)],
      [[0.3, 0.32, 0.3], [0.27, 0.29, 0.27], [0.22, 0.23, 0.22], [0.19, 0.2, 0.19]], { radial: 14 }), (p, n, c) => {
      c.copy(P.neck).lerp(P.mane, smoothstep(0.1, -0.8, n.z) * 0.4).multiplyScalar(0.86 + 0.28 * valueNoise3(p.x * 8, p.y * 8, p.z * 8));
    }));
    const head = [headFromProfile([
      [-0.16, 0.03, 0.12, 0.13, 0.12], [-0.08, 0.04, 0.19, 0.2, 0.18], [0.02, 0.03, 0.2, 0.21, 0.18],
      [0.12, 0.0, 0.16, 0.15, 0.15], [0.2, -0.03, 0.1, 0.09, 0.1], [0.28, -0.05, 0.075, 0.07, 0.075],
      [0.33, -0.055, 0.06, 0.055, 0.06], [0.355, -0.055, 0.03, 0.03, 0.03],
    ], P, 0.33, { radial: 14 }), ...eyesFor(P, 0.1, 0.075, 0.1, 0.017)];
    part('head', mergeGeometries(head));
    const earGeo = blobGeometry(1, 0.055, 0.05, 0.028, 0.08, 4, 0.4);
    earGeo.translate(0, 0.03, 0);
    paintGeometry(earGeo, (p, n, c) => c.copy(P.earOut).lerp(P.earIn, smoothstep(0.2, 0.8, n.z) * 0.6));
    part('earL', earGeo);
    part('earR', earGeo.clone());
    const tailG = blobGeometry(1, 0.06, 0.05, 0.06, 0.1, 2, 0.4);
    part('tail', paintGeometry(tailG, (p, n, c) => c.copy(P.tailTop)));
    legs = [
      { name: 'FL', front: true, side: -1, hip: [-0.2, -0.16, 0.48], knee: [0, -0.38, 0.02] },
      { name: 'FR', front: true, side: 1, hip: [0.2, -0.16, 0.48], knee: [0, -0.38, 0.02] },
      { name: 'BL', front: false, side: -1, hip: [-0.21, -0.1, -0.55], knee: [0, -0.4, -0.06] },
      { name: 'BR', front: false, side: 1, hip: [0.21, -0.1, -0.55], knee: [0, -0.4, -0.06] },
    ];
    for (const L of legs) {
      bone(`hip${L.name}`, 'body', ...L.hip);
      bone(`knee${L.name}`, `hip${L.name}`, ...L.knee);
      const lp = L.front
        ? legParts(P, [V3(0, 0.06, 0), V3(0, -0.18, -0.02), V3(0, -0.38, 0.02)], [[0.14, 0.16, 0.16], [0.12, 0.13, 0.13], [0.1, 0.1, 0.1]],
          [V3(0, 0, 0), V3(0, -0.2, 0.01), V3(0, -0.3, 0.03), V3(0, -0.33, 0.07), V3(0, -0.335, 0.11)], [0.1, 0.09, 0.1, 0.09, 0.05], L.side, -0.32)
        : legParts(P, [V3(0, 0.08, 0.02), V3(0, -0.2, 0.08), V3(0, -0.4, -0.06)], [[0.17, 0.19, 0.2], [0.14, 0.15, 0.15], [0.1, 0.1, 0.1]],
          [V3(0, 0, 0), V3(0, -0.2, 0.02), V3(0, -0.28, 0.05), V3(0, -0.31, 0.1), V3(0, -0.315, 0.14)], [0.1, 0.09, 0.1, 0.09, 0.05], L.side, -0.3);
      part(`hip${L.name}`, lp.upper);
      part(`knee${L.name}`, lp.lower);
    }
  }
  return { bones, parts, bodyY, legs, kind, female };
}

// Об'єднання частин в одну геометрію зі скінінгом (кожна вершина повністю належить одній кістці).
function skinnedKitGeometry(kit) {
  const index = new Map(kit.bones.map((b, i) => [b.name, i]));
  const world = kit.bones.map(() => [0, 0, 0]);
  kit.bones.forEach((b, i) => {
    const pw = b.parent ? world[index.get(b.parent)] : [0, 0, 0];
    world[i] = [pw[0] + b.pos[0], pw[1] + b.pos[1], pw[2] + b.pos[2]];
  });
  const geos = [];
  const boneIds = [];
  for (const p of kit.parts) {
    const g = p.geometry.clone();
    const w = world[index.get(p.bone)];
    g.translate(w[0], w[1], w[2]);
    geos.push(g);
    boneIds.push(index.get(p.bone));
  }
  const merged = mergeGeometries(geos);
  const count = merged.attributes.position.count;
  const skinIndex = new Uint16Array(count * 4);
  const skinWeight = new Float32Array(count * 4);
  let v = 0;
  geos.forEach((g, gi) => {
    const n = g.attributes.position.count;
    for (let i = 0; i < n; i++, v++) {
      skinIndex[v * 4] = boneIds[gi];
      skinWeight[v * 4] = 1;
    }
  });
  merged.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(skinIndex, 4));
  merged.setAttribute('skinWeight', new THREE.Float32BufferAttribute(skinWeight, 4));
  merged.computeBoundingSphere();
  return merged;
}

const ANIMAL_KITS = new Map();
function animalKit(kind, female) {
  const key = `${kind}:${female ? 'f' : 'm'}`;
  if (!ANIMAL_KITS.has(key)) {
    const kit = buildAnimalKit(kind, female);
    kit.geometry = skinnedKitGeometry(kit);
    ANIMAL_KITS.set(key, kit);
  }
  return ANIMAL_KITS.get(key);
}

/**
 * Процедурна модель тварини (тимчасова, замінна на GLB). Інтерфейс для поведінки:
 * object (THREE.Object3D), bones (за іменами), update(dt, pose).
 */
class ProceduralAnimalModel {
  constructor(spec, kit, material) {
    this.spec = spec;
    this.kit = kit;
    this.object = new THREE.Group();
    this.object.name = `animal-${kit.kind}`;
    this.bones = {};
    const list = [];
    for (const b of kit.bones) {
      const bone = new THREE.Bone();
      bone.name = b.name;
      bone.position.set(b.pos[0], b.pos[1], b.pos[2]);
      this.bones[b.name] = bone;
      list.push(bone);
    }
    for (const b of kit.bones) if (b.parent) this.bones[b.parent].add(this.bones[b.name]);
    this.mesh = new THREE.SkinnedMesh(kit.geometry, material);
    this.mesh.add(this.bones.body);
    this.mesh.updateMatrixWorld(true);
    this.mesh.bind(new THREE.Skeleton(list));
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = true;
    this.mesh.frustumCulled = false;
    this.object.add(this.mesh);
    for (const b of Object.values(this.bones)) b.rotation.order = 'YXZ';
    this.body = this.bones.body;
    this.neck = this.bones.neck;
    this.head = this.bones.head;
    this.tail = this.bones.tail;
    this.ears = [{ pivot: this.bones.earL, side: -1 }, { pivot: this.bones.earR, side: 1 }];
    this.legs = kit.legs.map((L) => ({ hip: this.bones[`hip${L.name}`], knee: this.bones[`knee${L.name}`], front: L.front, side: L.side }));
    this.offsets = [[0.25, 0.0, 0.55], [0.75, 0.5, 0.45], [0.0, 0.5, 0.0], [0.5, 0.0, 0.1]];
    this.bodyY = kit.bodyY;
    const n = spec.neck;
    const h = spec.head;
    this.s = { neck: n.feed, headPitch: h.feed, yaw: 0, tail: 0, alert: 0, pitch: 0, dead: 0 };
    this.earTimer = 2;
    this.twitch = 0;
    this.twitchSide = 0;
    this.tailTimer = 3;
    this.flick = 0;
    this.feedPhase = Math.random() * 10;
  }

  setShadow(on) {
    this.mesh.castShadow = on;
  }

  update(dt, pose) {
    const s = this.s;
    s.neck = damp(s.neck, pose.neck, 3.2, dt);
    s.headPitch = damp(s.headPitch, pose.headPitch, 3.6, dt);
    s.yaw = damp(s.yaw, pose.lookYaw, 4, dt);
    s.tail = damp(s.tail, pose.tail, 6, dt);
    s.alert = damp(s.alert, pose.alert, 4, dt);
    s.pitch = damp(s.pitch, pose.bodyPitch, 6, dt);
    s.dead = pose.dead > s.dead ? Math.min(pose.dead, s.dead + dt * 1.6) : pose.dead;
    const v = pose.speed;
    const walkW = 1 - smoothstep(1.8, 3.0, v);
    const gallopW = smoothstep(4.8, 7.0, v);
    const trotW = Math.max(0, 1 - walkW - gallopW);
    const moving = smoothstep(0.04, 0.35, v) * (1 - s.dead);
    const ph = pose.phase;
    const TAU = Math.PI * 2;
    const dead = s.dead;
    for (let i = 0; i < 4; i++) {
      const leg = this.legs[i];
      const off = this.offsets[i];
      let angle = 0;
      let lift = 0;
      if (walkW > 0) {
        const p = fract(ph + off[0]);
        angle += walkW * legSwing(p, 0.62, 0.3);
        lift += walkW * legLift(p, 0.62) * 0.75;
      }
      if (trotW > 0) {
        const p = fract(ph + off[1]);
        angle += trotW * legSwing(p, 0.5, 0.42);
        lift += trotW * legLift(p, 0.5);
      }
      if (gallopW > 0) {
        const p = fract(ph + off[2]);
        angle += gallopW * legSwing(p, 0.38, 0.62);
        lift += gallopW * legLift(p, 0.38) * 1.25;
      }
      angle *= moving;
      lift *= moving;
      // Лежача тварина: ноги випрямлені й трохи витягнуті.
      const deadA = leg.front ? -0.45 : 0.4;
      if (leg.front) {
        leg.hip.rotation.x = lerp(-angle, deadA, dead);
        leg.knee.rotation.x = lerp(lift * 1.1, 0.15, dead);
      } else {
        leg.hip.rotation.x = lerp(-angle * 0.9, deadA, dead);
        leg.knee.rotation.x = lerp(-lift * 0.85, -0.1, dead);
      }
    }
    const stepBob = -Math.abs(Math.sin(TAU * ph * 2));
    const bob = moving * (walkW * stepBob * 0.018 + trotW * stepBob * 0.03 + gallopW * Math.sin(TAU * ph) * 0.06);
    // Загибель: тварина падає на бік (поворот навколо осі тіла) і лягає на землю.
    const fall = dead * dead * (3 - 2 * dead);
    this.body.position.y = lerp(this.bodyY + bob * (this.bodyY / 0.95), this.bodyY * 0.42, fall);
    this.body.rotation.z = fall * 1.42;
    this.body.rotation.x = (s.pitch + moving * gallopW * Math.sin(TAU * ph + 1.4) * 0.09) * (1 - fall);
    const feeding = pose.feeding ? Math.sin(this.feedPhase += dt * 6) * 0.06 : 0;
    const nod = moving * (walkW * Math.sin(TAU * ph * 2) * 0.05 + gallopW * Math.sin(TAU * ph + 2) * 0.12);
    this.neck.rotation.x = lerp(s.neck + nod + feeding, this.spec.neck.walk + 0.3, fall);
    this.neck.rotation.y = s.yaw * 0.55 * (1 - fall);
    this.head.rotation.x = lerp(s.headPitch - this.neck.rotation.x, 0.1, fall);
    this.head.rotation.y = s.yaw * 0.45 * (1 - fall);
    this.earTimer -= dt;
    if (this.earTimer <= 0) {
      this.earTimer = 1.5 + Math.random() * 4;
      this.twitchSide = Math.random() < 0.5 ? 0 : 1;
      this.twitch = 1;
    }
    this.twitch = Math.max(0, this.twitch - dt * 4);
    for (let i = 0; i < 2; i++) {
      const ear = this.ears[i];
      const tw = i === this.twitchSide ? Math.sin(this.twitch * 20) * this.twitch * 0.35 : 0;
      ear.pivot.rotation.set((-0.25 + s.alert * 0.45 + tw) * (1 - fall), 0, -ear.side * (0.95 - s.alert * 0.45) * (1 - fall * 0.5));
    }
    this.tailTimer -= dt;
    if (this.tailTimer <= 0) {
      this.tailTimer = 2 + Math.random() * 5;
      this.flick = 1;
    }
    this.flick = Math.max(0, this.flick - dt * 2.5);
    this.tail.rotation.x = lerp(0.22, 2.3, s.tail) * (1 - fall) + Math.sin(this.flick * 18) * this.flick * 0.25;
    this.tail.rotation.z = Math.sin(this.flick * 23) * this.flick * 0.3;
  }

  // Положення кісток для перевірки влучань (без зміни поточного кадру анімації).
  boneMatrix(name) {
    const b = this.bones[name];
    return b ? b.matrixWorld : null;
  }
}

/**
 * Поведінка тварини: пасеться (або риє землю, шукає їжу), стоїть, ходить територією,
 * насторожується і тікає. Помічає мисливця за шумом (біг, ходьба, присід), силуетом
 * (камуфляж, укриття, рух) і запахом — якщо вітер дме від мисливця до тварини.
 */
// Кути обходу перешкод (рад) — постійний масив, щоб не створювати новий щоразу.
const CLEAR_OFFSETS = [0.35, 0.7, 1.05, 1.45, 1.9, 2.5];

class Animal {
  constructor(world, species, model, opts = {}) {
    this.world = world;
    this.tmpP = { x: 0, z: 0 };
    this.species = species;
    this.spec = SPECIES[species];
    this.model = model;
    this.female = !!opts.female;
    this.group = opts.group || 0;
    this.id = opts.id || 0;
    this.homeBase = { ...opts.home };
    this.callbacks = opts.callbacks || {};
    const sc = this.spec.scale;
    this.scale = lerp(sc[0], sc[1], Math.random()) * (this.female ? this.spec.femaleScale : 1);
    this.model.object.scale.setScalar(this.scale);
    this.reset(opts.home);
  }

  get name() {
    return this.female ? this.spec.female : this.spec.short;
  }

  reset(home) {
    const h = home || this.homeBase;
    this.home = { x: h.x, z: h.z };
    this.x = h.x + (Math.random() - 0.5) * 10;
    this.z = h.z + (Math.random() - 0.5) * 10;
    for (let i = 0; i < 12 && !this.canStand(this.x, this.z, 0.9); i++) {
      this.x = h.x + (Math.random() - 0.5) * 30;
      this.z = h.z + (Math.random() - 0.5) * 30;
    }
    this.yaw = Math.random() * Math.PI * 2 - Math.PI;
    this.speed = 0;
    this.desiredSpeed = 0;
    this.goalYaw = this.yaw;
    this.steerYaw = this.yaw;
    this.state = 'graze';
    this.stateTime = 0;
    this.timer = 4 + Math.random() * 8;
    this.target = null;
    this.awareness = 0;
    this.detectRadius = 0;
    this.distance = 999;
    this.phase = Math.random();
    this.lookYaw = 0;
    this.lookTimer = 0;
    this.lookTarget = 0;
    this.vigilance = 0;
    this.vigilTimer = 3;
    this.avoidTimer = 0;
    this.stuckTime = 0;
    this.fleeBias = 0;
    this.lastSide = 1;
    this.pitch = 0;
    this.alive = true;
    this.health = 1;
    this.wounded = false;
    this.bleed = 0;
    this.dieTimer = 0;
    this.deadTime = 0;
    this.collected = false;
    this.lastHit = null;
    this.spotted = 0;
    this.seenAt = null;
    this.weight = Math.round(lerp(...(this.female ? this.spec.femaleWeight : this.spec.weight), clamp((this.scale - this.spec.scale[0]) / (this.spec.scale[1] - this.spec.scale[0] + 1e-6), 0, 1)) * (0.9 + Math.random() * 0.2));
    this.pose = { speed: 0, phase: 0, neck: this.spec.neck.feed, headPitch: this.spec.head.feed, lookYaw: 0, tail: 0, alert: 0, bodyPitch: 0, dead: 0, feeding: true };
    this.model.object.visible = true;
    this.place();
  }

  setState(next, duration) {
    const prev = this.state;
    this.state = next;
    this.stateTime = 0;
    this.timer = duration;
    if (prev !== next && this.callbacks.onStateChange) this.callbacks.onStateChange(prev, next, this);
  }

  canStand(x, z, r) {
    const lim = PLAY_HALF - 8;
    if (Math.abs(x) > lim || Math.abs(z) > lim) return false;
    const t = this.world.terrain;
    if (t.waterDepthAt(x, z) > -0.25) return false;
    if (t.slopeAt(x, z) > 0.75) return false;
    return !this.world.colliders.blocked(x, z, r);
  }

  pickTarget() {
    for (let i = 0; i < 24; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = 8 + Math.random() * (this.spec.homeRadius - 8);
      const x = this.home.x + Math.cos(a) * r;
      const z = this.home.z + Math.sin(a) * r;
      if (len2(x - this.x, z - this.z) < 10) continue;
      if (this.canStand(x, z, 0.9)) {
        this.target = { x, z };
        return;
      }
    }
    this.target = { x: this.home.x, z: this.home.z };
  }

  pathClear(yaw, look) {
    const sx = Math.sin(yaw);
    const sz = Math.cos(yaw);
    if (!this.canStand(this.x + sx * 1.2, this.z + sz * 1.2, 0.7)) return false;
    if (!this.canStand(this.x + sx * look * 0.55, this.z + sz * look * 0.55, 0.7)) return false;
    return this.canStand(this.x + sx * look, this.z + sz * look, 0.7);
  }

  findClearYaw(goal, look) {
    if (this.pathClear(goal, look)) return goal;
    for (let i = 0; i < CLEAR_OFFSETS.length; i++) {
      const off = CLEAR_OFFSETS[i];
      for (let k = 0; k < 2; k++) {
        const side = k === 0 ? this.lastSide : -this.lastSide;
        const yaw = goal + off * side;
        if (this.pathClear(yaw, look)) {
          this.lastSide = side;
          return yaw;
        }
      }
    }
    return goal + Math.PI;
  }

  // Слух (шум кроків і пострілів), зір (силует, рух, камуфляж) і нюх (вітер від мисливця).
  perceive(dt, player, dist, rel, wind) {
    const sp = this.spec;
    const inView = Math.abs(rel) < 2.3;
    const hearing = player.moving ? (8 + 34 * player.noise) * sp.hearing : 0;
    let sight = (player.crouching ? 6 : 12) * player.visibility * sp.detect;
    if (player.moving) sight *= 1.6;
    if (!inView) sight *= 0.35;
    if (player.onTower) sight *= 0.45;
    let radius = Math.max(hearing, sight);
    // Нюх: вітер дме від мисливця в бік тварини.
    let scent = 0;
    if (wind && dist > 1) {
      const fx = (this.x - player.x) / dist;
      const fz = (this.z - player.z) / dist;
      const along = fx * wind.x + fz * wind.y;
      if (along > 0.35) {
        scent = 75 * sp.scent * player.scentK * smoothstep(0.35, 0.95, along);
        if (player.onTower) scent *= 0.4;
      }
    }
    if (this.state === 'graze' && !this.vigilance) radius *= 0.8;
    if (this.state === 'alert') radius *= 1.25;
    radius = Math.max(radius, scent);
    this.detectRadius = radius;
    if (dist < radius) {
      const smell = scent >= radius - 1e-3 && dist < scent;
      this.awareness += (1 - dist / radius) * dt * (smell ? 0.9 : 0.55 + player.noise * 1.8);
    } else {
      this.awareness -= dt * (this.state === 'alert' ? 0.07 : 0.12);
    }
    this.awareness = clamp(this.awareness, 0, 1.2);
  }

  // Різкий звук (постріл): тварини поблизу тікають, далекі насторожуються.
  hearShot(dist) {
    if (!this.alive) return;
    if (dist < 160) this.startFlee();
    else if (dist < 320) {
      this.awareness = Math.max(this.awareness, 0.6);
      if (this.state !== 'flee' && this.state !== 'alert') this.setState('alert', 3 + Math.random() * 3);
    }
  }

  startFlee(fromX, fromZ) {
    if (!this.alive || this.state === 'dying') return;
    if (fromX !== undefined) this.fleeFrom = { x: fromX, z: fromZ };
    this.fleeBias = (Math.random() - 0.5) * 0.8;
    this.awareness = 1.2;
    this.target = null;
    this.setState('flee', 0);
  }

  /**
   * Влучання кулі: energy — сила набою, zone — частина тіла.
   * Повертає результат: смерть на місці, смертельне поранення (пробіжить кілька секунд) або поранення.
   */
  hit(zone, energy, shotDist) {
    if (!this.alive) return null;
    const dmg = (energy * ZONE_POWER[zone]) / this.spec.toughness;
    const res = { zone, dmg, dist: shotDist, kind: 'wound' };
    this.lastHit = { zone, dist: shotDist, dmg };
    if (dmg >= 2.4 || (zone === 'head' && dmg >= 1.6)) {
      res.kind = 'kill';
      this.die('instant');
    } else if (dmg >= 1.15) {
      res.kind = 'mortal';
      this.health = 0;
      this.dieTimer = 2.5 + Math.random() * 4;
      this.startFlee();
      this.setState('dying', this.dieTimer);
    } else {
      this.health -= dmg * 0.65;
      this.wounded = true;
      this.bleed = Math.max(this.bleed, dmg * 40);
      if (this.health <= 0) {
        res.kind = 'mortal';
        this.dieTimer = 8 + Math.random() * 10;
        this.startFlee();
        this.setState('dying', this.dieTimer);
      } else {
        this.startFlee();
      }
    }
    return res;
  }

  die(how) {
    if (!this.alive) return;
    this.alive = false;
    this.deathHow = how;
    this.speed = 0;
    this.desiredSpeed = 0;
    this.deadTime = 0;
    this.setState('dead', 1e9);
    if (this.callbacks.onDeath) this.callbacks.onDeath(this);
  }

  update(dt, player, active, wind) {
    this.stateTime += dt;
    this.timer -= dt;
    const dx = player.x - this.x;
    const dz = player.z - this.z;
    const dist = len2(dx, dz);
    this.distance = dist;
    if (!this.alive) {
      this.deadTime += dt;
      const pose = this.pose;
      pose.speed = 0;
      pose.dead = 1;
      pose.tail = 0;
      pose.alert = 0;
      pose.feeding = false;
      this.model.update(dt, pose);
      return;
    }
    const sp = this.spec;
    const toPlayer = Math.atan2(dx, dz);
    const rel = wrapAngle(toPlayer - this.yaw);
    if (active && this.state !== 'dying') this.perceive(dt, player, dist, rel, wind);
    else this.awareness = Math.max(0, this.awareness - dt * 0.2);
    if (this.bleed > 0) this.bleed -= dt;

    if (active && this.state !== 'flee' && this.state !== 'dying') {
      if (this.awareness >= 1 || dist < 6.5 || (player.running && dist < 22 * sp.hearing)) this.startFlee();
      else if (this.awareness > 0.32 && this.state !== 'alert') this.setState('alert', 3 + Math.random() * 3);
    }

    const N = sp.neck;
    const H = sp.head;
    let neck = N.idle;
    let headPitch = H.idle;
    let tail = 0;
    let alert = 0;
    let look = 0;
    let feeding = false;
    switch (this.state) {
      case 'idle':
        this.desiredSpeed = 0;
        this.goalYaw = this.yaw;
        this.lookTimer -= dt;
        if (this.lookTimer <= 0) {
          this.lookTimer = 1.2 + Math.random() * 2.5;
          this.lookTarget = (Math.random() - 0.5) * 1.8;
        }
        look = this.lookTarget;
        if (this.timer <= 0) {
          if (Math.random() < 0.5) this.setState('graze', 6 + Math.random() * 8);
          else {
            this.pickTarget();
            this.setState('walk', 30);
          }
        }
        break;
      case 'graze':
        this.desiredSpeed = sp.feed === 'root' ? 0.25 : 0;
        if (sp.feed === 'root' && Math.random() < dt * 0.3) this.goalYaw = this.yaw + (Math.random() - 0.5) * 1.2;
        else if (sp.feed !== 'root') this.goalYaw = this.yaw;
        this.vigilTimer -= dt;
        if (this.vigilTimer <= 0) {
          this.vigilance = this.vigilance ? 0 : 1;
          this.vigilTimer = this.vigilance ? 1.4 + Math.random() * 1.4 : 3.5 + Math.random() * 5;
          this.lookTarget = (Math.random() - 0.5) * 1.4;
        }
        if (this.vigilance) {
          neck = N.idle;
          headPitch = H.idle;
          look = this.lookTarget;
        } else {
          neck = N.feed;
          headPitch = H.feed;
          feeding = sp.feed !== 'graze';
          look = Math.sin(this.stateTime * 0.7) * 0.15;
        }
        if (this.timer <= 0) {
          this.vigilance = 0;
          if (Math.random() < 0.4) this.setState('idle', 2 + Math.random() * 3);
          else {
            this.pickTarget();
            this.setState('walk', 30);
          }
        }
        break;
      case 'walk': {
        if (!this.target) this.pickTarget();
        const tx = this.target.x - this.x;
        const tz = this.target.z - this.z;
        this.goalYaw = Math.atan2(tx, tz);
        this.desiredSpeed = sp.walk;
        neck = N.walk;
        headPitch = H.walk;
        look = clamp(wrapAngle(this.goalYaw - this.yaw), -0.5, 0.5);
        if (len2(tx, tz) < 1.8 || this.timer <= 0) {
          this.target = null;
          if (Math.random() < 0.6) this.setState('graze', 6 + Math.random() * 8);
          else this.setState('idle', 2 + Math.random() * 3);
        }
        break;
      }
      case 'alert':
        this.desiredSpeed = 0;
        neck = N.alert;
        headPitch = H.alert;
        alert = 1;
        tail = 0.25;
        look = clamp(rel, -1.5, 1.5);
        this.goalYaw = Math.abs(rel) > 1.3 ? toPlayer : this.yaw;
        if (this.timer <= 0) {
          if (this.awareness < 0.22) this.setState('idle', 2 + Math.random() * 2);
          else this.timer = 1.2;
        }
        break;
      case 'flee':
      case 'dying': {
        const from = this.fleeFrom && this.stateTime < 2 ? this.fleeFrom : player;
        const away = Math.atan2(this.x - from.x, this.z - from.z);
        this.fleeBias = clamp(this.fleeBias + (Math.random() - 0.5) * dt * 0.6, -0.6, 0.6);
        this.goalYaw = away + this.fleeBias;
        const hurt = this.state === 'dying' ? 0.8 - 0.4 * clamp(this.stateTime / Math.max(this.dieTimer, 0.1), 0, 1) : this.wounded ? 0.85 : 1;
        this.desiredSpeed = (this.stateTime < 5 ? sp.run : sp.run * 0.72) * hurt;
        neck = N.run;
        headPitch = H.run;
        tail = 1;
        alert = 0.6;
        if (this.state === 'dying') {
          if (this.timer <= 0) {
            this.die('ran');
            break;
          }
        } else if ((this.stateTime > 6 && dist > 70) || this.stateTime > 14) {
          this.home = { x: this.x, z: this.z };
          this.fleeFrom = null;
          this.setState('trot', 2.5 + Math.random() * 2);
        }
        break;
      }
      case 'trot': {
        this.goalYaw = Math.atan2(this.x - player.x, this.z - player.z) + this.fleeBias;
        this.desiredSpeed = sp.trot;
        neck = N.walk;
        headPitch = H.walk;
        tail = 0.6;
        alert = 0.5;
        if (this.timer <= 0) {
          this.awareness = Math.min(this.awareness, 0.45);
          this.setState('alert', 3);
        }
        break;
      }
      default:
        this.setState('idle', 2);
    }
    if (!this.alive) return;
    this.lookYaw = look;
    this.move(dt);
    const pose = this.pose;
    pose.speed = this.speed / Math.max(this.scale, 0.5);   // пороги ходи — для тварини розміру оленя
    pose.phase = this.phase;
    pose.neck = neck;
    pose.headPitch = headPitch;
    pose.lookYaw = this.lookYaw;
    pose.tail = tail;
    pose.alert = alert;
    pose.bodyPitch = this.pitch;
    pose.dead = 0;
    pose.feeding = feeding;
    this.model.update(dt, pose);
  }

  move(dt) {
    const sp = this.spec;
    const fleeing = this.state === 'flee' || this.state === 'dying';
    const look = fleeing ? 7 : this.state === 'trot' ? 4.5 : 3;
    this.avoidTimer -= dt;
    if (this.avoidTimer <= 0) {
      this.avoidTimer = fleeing ? 0.12 : 0.25;
      this.steerYaw = this.desiredSpeed > 0 ? this.findClearYaw(this.goalYaw, look) : this.goalYaw;
    }
    const diff = wrapAngle(this.steerYaw - this.yaw);
    const maxTurn = this.speed > 4 ? 2.6 : this.speed > 0.3 ? 1.6 : 1.1;
    this.yaw = wrapAngle(this.yaw + clamp(diff, -maxTurn * dt, maxTurn * dt));
    const target = this.desiredSpeed * (1 - Math.min(Math.abs(diff) / Math.PI, 1) * 0.6);
    const accel = target > this.speed ? (fleeing ? sp.accel : 1.6) : 4.5;
    this.speed += clamp(target - this.speed, -accel * dt, accel * dt);
    if (this.speed > 0.01) {
      const nx = this.x + Math.sin(this.yaw) * this.speed * dt;
      const nz = this.z + Math.cos(this.yaw) * this.speed * dt;
      if (this.canStand(nx, nz, 0.45)) {
        this.x = nx;
        this.z = nz;
        this.stuckTime = Math.max(0, this.stuckTime - dt);
      } else {
        this.speed *= 0.4;
        this.stuckTime += dt;
        this.avoidTimer = 0;
      }
    }
    const p = this.tmpP;
    p.x = this.x;
    p.z = this.z;
    this.world.colliders.resolve(p, 0.55 * this.scale);
    const lim = PLAY_HALF - 8;
    this.x = clamp(p.x, -lim, lim);
    this.z = clamp(p.z, -lim, lim);
    if (this.stuckTime > 1.5) {
      this.stuckTime = 0;
      if (this.state === 'walk') this.pickTarget();
      else this.fleeBias = clamp(-this.fleeBias + (Math.random() - 0.5), -1, 1);
    }
    const strides = sp.strides;
    const stride = (this.speed < 2 ? strides[0] : this.speed < 5 ? strides[1] : strides[2]) * this.scale;
    const prevPhase = this.phase;
    this.phase = fract(this.phase + (dt * this.speed) / stride);
    if (this.speed > 4.5 && this.phase < prevPhase && this.callbacks.onHoof) this.callbacks.onHoof(this);
    this.place();
  }

  place() {
    const t = this.world.terrain;
    this.y = t.heightAt(this.x, this.z);
    const fx = Math.sin(this.yaw) * 0.7 * this.scale;
    const fz = Math.cos(this.yaw) * 0.7 * this.scale;
    this.pitch = Math.atan2(t.heightAt(this.x - fx, this.z - fz) - t.heightAt(this.x + fx, this.z + fz), 1.4 * this.scale);
    this.model.object.position.set(this.x, this.y, this.z);
    this.model.object.rotation.y = this.yaw;
  }

  // Перетин променя кулі (відрізок a→b) з зонами влучання. Повертає найближче влучання.
  raycastZones(ax, ay, az, bx, by, bz, tmpM, tmpV) {
    if (this.collected) return null;
    const cx = this.x;
    const cy = this.y + 0.8 * this.scale;
    const cz = this.z;
    const dx = bx - ax;
    const dy = by - ay;
    const dz = bz - az;
    const lenSq = dx * dx + dy * dy + dz * dz;
    if (lenSq < 1e-8) return null;
    // Швидка перевірка: обмежувальна сфера тварини.
    let t = ((cx - ax) * dx + (cy - ay) * dy + (cz - az) * dz) / lenSq;
    t = clamp(t, 0, 1);
    const qx = ax + dx * t - cx;
    const qy = ay + dy * t - cy;
    const qz = az + dz * t - cz;
    const R = this.spec.bodyR * this.scale + 0.6;
    if (qx * qx + qy * qy + qz * qz > R * R) return null;
    this.model.object.updateMatrixWorld(true);
    const zones = HIT_ZONES[this.species];
    let best = null;
    const len = Math.sqrt(lenSq);
    for (const zn of zones) {
      const m = this.model.boneMatrix ? this.model.boneMatrix(zn.bone) : null;
      if (!m) continue;
      tmpV.set(zn.p[0], zn.p[1], zn.p[2]).applyMatrix4(m);
      const r = zn.r * this.scale;
      const fx = ax - tmpV.x;
      const fy = ay - tmpV.y;
      const fz = az - tmpV.z;
      const b = (fx * dx + fy * dy + fz * dz) / lenSq;
      const c = (fx * fx + fy * fy + fz * fz - r * r) / lenSq;
      const disc = b * b - c;
      if (disc < 0) continue;
      const s = -b - Math.sqrt(disc);
      if (s < 0 || s > 1) continue;
      if (!best || s < best.t) best = { t: s, zone: zn.zone, x: ax + dx * s, y: ay + dy * s, z: az + dz * s, dist: s * len };
    }
    return best;
  }
}

// ═══════════════════════════ 11b. ОЛЕНІ: ВЛАСНІ ДЕТАЛЬНІ МОДЕЛІ ═══════════════════════════
/*
 * Благородний олень (самець і самка) та козуля — власні моделі гри. Кожна — суцільна сітка зі
 * скелетом (28 кісток), створена генератором анатомії: скульптинг полями відстаней (м'язи,
 * суглоби, ратиці, очі, ніздрі, грива), спрощення сітки, ваги скіну, кольори хутра й затінення
 * западин. Дані сіток — у DEER_MODEL_DATA (base64). Два рівні деталізації ділять один буфер вершин.
 * Роги генеруються тут: кількість відростків дорівнює тій, що в картці трофея.
 * Анімація процедурна: крок, рись і галоп із копитами, що стоять на землі (обернена кінематика,
 * копита підлаштовуються під рельєф), випас, тривога, повороти голови, вуха, хвіст і падіння.
 * Це детальні моделі, а не фотореалістичні: без фототекстур і хутра з окремих волосин.
 */

const DEER_ASSETS = {};
let DEER_MATERIAL = null;

function deerDecodeIndices(bytes, count) {
  const out = new Uint16Array(count);
  let prev = 0;
  let p = 0;
  for (let i = 0; i < count; i++) {
    let zz = 0;
    let shift = 0;
    let b;
    do {
      b = bytes[p++];
      zz |= (b & 0x7f) << shift;
      shift += 7;
    } while (b & 0x80);
    prev += zz & 1 ? -((zz + 1) >>> 1) : zz >>> 1;
    out[i] = prev;
  }
  return out;
}

// Розбір формату WHD1: заголовок JSON, квантовані позиції, нормалі (октаедричні), кольори RGBA
// (гамма 2.2; альфа — шорсткість), кістки й ваги (uint8), індекси рівнів деталізації (дельта-varint).
function deerDecode(buf) {
  const dv = new DataView(buf);
  const pad4 = (n) => (n + 3) & ~3;
  if (dv.getUint32(0, true) !== 0x31444857) throw new Error('дані моделі оленя пошкоджено');
  const hl = dv.getUint32(4, true);
  const hdr = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 8, hl)));
  let off = 8 + pad4(hl);
  const n = hdr.n;
  const qpos = new Uint16Array(buf, off, n * 3);
  off += pad4(n * 6);
  const oct = new Int8Array(buf, off, n * 2);
  off += pad4(n * 2);
  const rgba = new Uint8Array(buf.slice(off, off + n * 4));
  off += n * 4;
  const joints = new Uint8Array(buf.slice(off, off + n * 4));
  off += n * 4;
  const weights = new Uint8Array(buf.slice(off, off + n * 4));
  off += n * 4;
  const lods = [];
  for (let l = 0; l < hdr.lods.length; l++) {
    const len = dv.getUint32(off, true);
    off += 4;
    lods.push(deerDecodeIndices(new Uint8Array(buf, off, len), hdr.lods[l] * 3));
    off += pad4(len);
  }
  const pos = new Float32Array(n * 3);
  const nrm = new Float32Array(n * 3);
  const mn = hdr.bmin;
  const mx = hdr.bmax;
  for (let i = 0; i < n; i++) {
    for (let k = 0; k < 3; k++) pos[i * 3 + k] = mn[k] + (qpos[i * 3 + k] / 65535) * (mx[k] - mn[k]);
    let x = oct[i * 2] / 127;
    let y = oct[i * 2 + 1] / 127;
    const z = 1 - Math.abs(x) - Math.abs(y);
    if (z < 0) {
      const ox = x;
      x = (1 - Math.abs(y)) * (ox >= 0 ? 1 : -1);
      y = (1 - Math.abs(ox)) * (y >= 0 ? 1 : -1);
    }
    const l = Math.sqrt(x * x + y * y + z * z) || 1;
    nrm[i * 3] = x / l;
    nrm[i * 3 + 1] = y / l;
    nrm[i * 3 + 2] = z / l;
  }
  const attrs = {
    position: new THREE.BufferAttribute(pos, 3),
    normal: new THREE.BufferAttribute(nrm, 3),
    color: new THREE.BufferAttribute(rgba, 4, true),
    skinIndex: new THREE.BufferAttribute(joints, 4),
    skinWeight: new THREE.BufferAttribute(weights, 4, true),
  };
  return { header: hdr, attrs, lods };
}

function deerAsset(kind) {
  if (DEER_ASSETS[kind]) return DEER_ASSETS[kind];
  const b64 = typeof DEER_MODEL_DATA !== 'undefined' ? DEER_MODEL_DATA[kind] : null;
  if (!b64) return null;
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const asset = deerDecode(bytes.buffer);
  // Геометрії рівнів деталізації — спільні атрибути вершин (один раз у пам'яті GPU).
  asset.geometries = asset.lods.map((idx) => {
    const g = new THREE.BufferGeometry();
    for (const [name, attr] of Object.entries(asset.attrs)) g.setAttribute(name, attr);
    g.setIndex(new THREE.BufferAttribute(idx, 1));
    g.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 0.9, 0), 1.6);
    return g;
  });
  const bones = asset.header.bones;
  asset.boneIndex = {};
  bones.forEach((b, i) => { asset.boneIndex[b.name] = i; });
  asset.parent = bones.map((b) => (b.parent ? asset.boneIndex[b.parent] : -1));
  asset.restWorld = bones.map((b) => new THREE.Vector3(b.pos[0], b.pos[1], b.pos[2]));
  asset.restLocal = bones.map((b, i) => {
    const p = asset.parent[i];
    return p < 0 ? asset.restWorld[i].clone() : asset.restWorld[i].clone().sub(asset.restWorld[p]);
  });
  DEER_ASSETS[kind] = asset;
  return asset;
}

function deerModelAvailable(kind) {
  try {
    return !!deerAsset(kind);
  } catch (err) {
    logWarn(err);
    return false;
  }
}

// Хутро: колір із вершин (гамма 2.2), шорсткість з альфа-каналу; дрібний видовжений ворс
// (уздовж тулуба й донизу на ногах) — у кольорі й нормалі; легке «пухнасте» підсвічування контуру.
function deerMaterial() {
  if (DEER_MATERIAL) return DEER_MATERIAL;
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0, envMapIntensity: 0.45 });
  m.onBeforeCompile = (sh) => {
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vRest;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvRest = position;');
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', `#include <common>
varying vec3 vRest;
float whFurH(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453); }
float whFurN(vec3 p) {
  vec3 i = floor(p); vec3 f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(whFurH(i), whFurH(i + vec3(1.0, 0.0, 0.0)), f.x), mix(whFurH(i + vec3(0.0, 1.0, 0.0)), whFurH(i + vec3(1.0, 1.0, 0.0)), f.x), f.y),
             mix(mix(whFurH(i + vec3(0.0, 0.0, 1.0)), whFurH(i + vec3(1.0, 0.0, 1.0)), f.x), mix(whFurH(i + vec3(0.0, 1.0, 1.0)), whFurH(i + vec3(1.0, 1.0, 1.0)), f.x), f.y), f.z);
}`)
      .replace('#include <color_fragment>', `
#if defined( USE_COLOR_ALPHA )
  vec3 whCol = pow(vColor.rgb, vec3(2.2));
  float whRough = vColor.a;
#else
  vec3 whCol = vColor;
  float whRough = 0.9;
#endif
  float whLegs = smoothstep(0.78, 0.6, vRest.y);
  vec3 whFp = mix(vec3(vRest.x * 240.0, vRest.y * 240.0, vRest.z * 60.0), vec3(vRest.x * 240.0, vRest.y * 60.0, vRest.z * 240.0), whLegs);
  float whStrand = whFurN(whFp) * 0.62 + whFurN(whFp * 2.3 + 7.1) * 0.38;
  float whFur = smoothstep(0.55, 0.8, whRough);
  diffuseColor.rgb *= whCol * mix(1.0, 0.8 + 0.4 * whStrand, whFur);
`)
      // Вологі ніс і очі — не глянцевіші за 0,4: у прицілі зі збільшенням вони не спалахують іскрами.
      .replace('#include <roughnessmap_fragment>', 'float roughnessFactor = max(whRough, 0.4);')
      .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
  normal = normalize(normal + whFur * 0.22 * (whStrand - 0.5) * normalize(vec3(0.6, -0.4, 0.7)));`)
      .replace('#include <opaque_fragment>', `
  // Пухнастий контур: світло, що проходить крізь ворс по краях силуету.
  float whRim = pow(1.0 - saturate(dot(normal, normalize(vViewPosition))), 3.0) * whFur;
  outgoingLight += diffuseColor.rgb * whRim * 0.35 * (totalDiffuse + 0.15);
#include <opaque_fragment>`);
  };
  m.customProgramCacheKey = () => 'wh-deer-fur-3';
  DEER_MATERIAL = m;
  return m;
}

// ─── Роги: трубки вздовж кривих (головна гілка й відростки), перли біля основи, світлі кінчики ───

// Робочі вектори створюються після завантаження Three.js (на рівні модуля THREE ще недоступний).
let ANTLER_TMP = null;
let DEER_V = null;
let DEER_Q = null;
let DEER_E = null;
let DEER_AX = null;
function deerInitTemps() {
  if (DEER_V) return;
  ANTLER_TMP = { a: new THREE.Vector3(), b: new THREE.Vector3(), t: new THREE.Vector3(), n: new THREE.Vector3(), q: new THREE.Vector3() };
  DEER_V = Array.from({ length: 12 }, () => new THREE.Vector3());
  DEER_Q = Array.from({ length: 6 }, () => new THREE.Quaternion());
  DEER_E = new THREE.Euler();
  DEER_AX = new THREE.Vector3(1, 0, 0);
}

function antlerCurve(points, segs) {
  const curve = new THREE.CatmullRomCurve3(points, false, 'centripetal');
  return curve.getSpacedPoints(segs);
}

/**
 * Будує геометрію пари рогів. kind — 'stag' або 'roe'; perSide — відростків на кожному розі
 * (разом із вершиною гілки); size — розмір (0..1); lod — 0 (детально) або 1 (просто).
 * Координати — у системі моделі відносно основи рогу (пеньочка); x дзеркалиться для боків.
 */
function buildAntlerGeometry(kind, perSide, size, lod, seed, half) {
  deerInitTemps();
  const rand = mulberry32(seed);
  const pos = [];
  const nrm = [];
  const col = [];
  const idx = [];
  const sides = lod ? 5 : 8;
  const base = kind === 'roe' ? [0x55, 0x43, 0x32] : [0x4e, 0x3d, 0x2c];
  const mid = kind === 'roe' ? [0x77, 0x62, 0x4b] : [0x70, 0x5c, 0x45];
  const tip = [0xea, 0xe1, 0xcc];
  const fur = kind === 'roe' ? [0x8a, 0x5c, 0x3e] : [0x5a, 0x46, 0x34];
  const T = ANTLER_TMP;
  // Трубка вздовж точок pts з радіусом r(t) і кольором c(t).
  const tube = (pts, rFn, cFn, pearl, s) => {
    const n = pts.length;
    const start = pos.length / 3;
    let normal = new THREE.Vector3(1, 0, 0);
    for (let i = 0; i < n; i++) {
      const p = pts[i];
      const tan = i < n - 1 ? T.t.subVectors(pts[i + 1], p) : T.t.subVectors(p, pts[i - 1]);
      tan.normalize();
      // Паралельне перенесення рамки: нормаль лишається перпендикулярною до дотичної.
      normal.sub(T.q.copy(tan).multiplyScalar(normal.dot(tan))).normalize();
      if (normal.lengthSq() < 1e-6) normal.set(0, 0, 1);
      const binormal = T.b.crossVectors(tan, normal).normalize();
      const t = i / (n - 1);
      const r = rFn(t);
      const c = cFn(t);
      for (let j = 0; j < sides; j++) {
        const a = (j / sides) * Math.PI * 2;
        const ca = Math.cos(a);
        const sa = Math.sin(a);
        const bump = pearl > 0 ? 1 + pearl * Math.pow(1 - t, 3) * (valueNoise3(p.x * 55 + ca * 1.3, p.y * 55 + sa * 1.3, p.z * 55 + s * 13) - 0.5) : 1;
        const nx = normal.x * ca + binormal.x * sa;
        const ny = normal.y * ca + binormal.y * sa;
        const nz = normal.z * ca + binormal.z * sa;
        pos.push((half + p.x + nx * r * bump) * s, p.y + ny * r * bump, p.z + nz * r * bump);
        nrm.push(nx * s, ny, nz);
        col.push(c[0], c[1], c[2], c[3]);
      }
    }
    for (let i = 0; i < n - 1; i++) {
      for (let j = 0; j < sides; j++) {
        const a = start + i * sides + j;
        const b = start + i * sides + ((j + 1) % sides);
        const c2 = a + sides;
        const d = b + sides;
        if (s > 0) idx.push(a, c2, b, b, c2, d);
        else idx.push(a, b, c2, b, d, c2);
      }
    }
    // Загострений кінчик.
    const tipP = pts[n - 1];
    const tanEnd = T.t.subVectors(pts[n - 1], pts[n - 2]).normalize();
    const tipI = pos.length / 3;
    const tl = rFn(1) * 1.6;
    pos.push((half + tipP.x + tanEnd.x * tl) * s, tipP.y + tanEnd.y * tl, tipP.z + tanEnd.z * tl);
    nrm.push(tanEnd.x * s, tanEnd.y, tanEnd.z);
    const ce = cFn(1);
    col.push(ce[0], ce[1], ce[2], ce[3]);
    const last = start + (n - 1) * sides;
    for (let j = 0; j < sides; j++) {
      const a = last + j;
      const b = last + ((j + 1) % sides);
      if (s > 0) idx.push(a, tipI, b);
      else idx.push(a, b, tipI);
    }
  };
  const mixc = (c1, c2, t, rough) => [c1[0] + (c2[0] - c1[0]) * t, c1[1] + (c2[1] - c1[1]) * t, c1[2] + (c2[2] - c1[2]) * t, rough];
  const colAlong = (t, tipFrom) => {
    if (t < tipFrom) return mixc(base, mid, Math.min(1, t / Math.max(tipFrom, 0.01)), 150);
    return mixc(mid, tip, smoothstep(tipFrom, 1, t), 120);
  };
  for (const s of [-1, 1]) {
    const V = (x, y, z) => new THREE.Vector3(x, y, z);
    if (kind === 'stag') {
      const k = 0.78 + 0.32 * size;
      const jitter = () => (rand() - 0.5) * 0.03;
      const beam = [V(0, 0, 0), V(0.045, 0.09, -0.09), V(0.12 + jitter(), 0.22, -0.22), V(0.21 + jitter(), 0.37, -0.31),
        V(0.28, 0.52, -0.33 + jitter()), V(0.32, 0.66, -0.28), V(0.32, 0.77 + jitter(), -0.19)].map((v) => v.multiplyScalar(k));
      const bpts = antlerCurve(beam, lod ? 9 : 16);
      const crownTines = Math.max(0, perSide - 4);
      const beamTipColor = crownTines > 0 ? 0.86 : 0.8;
      const beamR = (t) => (0.034 - 0.019 * t) * (0.85 + 0.25 * size);
      // Біля основи — розширення («розетка») з перлами.
      tube([V(0, -0.03, 0.01), ...bpts], (t) => beamR(t) * (1 + 0.42 * Math.exp(-t * 32)), (t) => colAlong(t, beamTipColor), lod ? 0 : 0.5, s);
      const along = (t) => {
        const i = Math.min(bpts.length - 1, Math.max(0, Math.round(t * (bpts.length - 1))));
        return bpts[i].clone();
      };
      const tines = [];
      const lenK = k * (0.8 + 0.25 * size);
      tines.push({ t: 0.06, dir: V(0.12, 0.15, 1), len: 0.3 * lenK, up: 0.22 });       // надочний
      if (perSide >= 4) tines.push({ t: 0.13, dir: V(0.2, 0.25, 0.95), len: 0.24 * lenK, up: 0.15 });   // другий
      tines.push({ t: 0.45, dir: V(0.15, 0.3, 0.95), len: 0.22 * lenK, up: 0.12 });  // середній
      // Корона: відростки догори вперед і назад біля вершини.
      const crown = [[0.82, V(0.15, 0.8, 0.55), 0.17], [0.88, V(-0.1, 0.85, -0.35), 0.15], [0.76, V(0.4, 0.75, 0.2), 0.14]];
      for (let c = 0; c < crownTines && c < crown.length; c++) tines.push({ t: crown[c][0], dir: crown[c][1], len: crown[c][2] * lenK, up: 0.05 });
      for (const tn of tines) {
        const p0 = along(tn.t);
        const d = tn.dir.clone().normalize();
        const p1 = p0.clone().addScaledVector(d, tn.len * 0.5);
        const p2 = p0.clone().addScaledVector(d, tn.len).add(V(0, tn.up * tn.len, 0));
        const pts = antlerCurve([p0.clone().addScaledVector(d, -0.01), p1, p2], lod ? 4 : 7);
        const r0 = beamR(tn.t) * 0.6;
        tube(pts, (t) => r0 * (1 - 0.72 * t), (t) => colAlong(0.25 + 0.75 * t, 0.62), lod ? 0 : 0.18, s);
      }
    } else {
      // Козуля: короткі вертикальні ріжки з грубими «перлами», пеньочок у хутрі.
      const k = 0.8 + 0.3 * size;
      const beam = [V(0, 0, 0), V(0.012, 0.1, -0.02), V(0.03, 0.2, -0.025), V(0.045, 0.29, -0.005), V(0.05, 0.34, 0.015)].map((v) => v.multiplyScalar(k));
      const bpts = antlerCurve(beam, lod ? 6 : 11);
      // Пеньочок у хутрі, широка розетка з грубими перлами, далі гілка.
      const roeR = (t) => (0.02 - 0.012 * t) * (0.9 + 0.2 * size);
      tube([V(0, -0.05, 0.006), V(0, -0.02, 0.004), ...bpts], (t) => roeR(t) * (1 + 0.55 * Math.exp(-Math.max(0, t - 0.1) * 28)),
        (t) => (t < 0.1 ? [...fur, 230] : colAlong(t, 0.82)), lod ? 0 : 0.7, s);
      const along = (t) => bpts[Math.min(bpts.length - 1, Math.round(t * (bpts.length - 1)))].clone();
      const tines = [];
      if (perSide >= 2) tines.push({ t: 0.55, dir: V(0.05, 0.45, 1), len: 0.09 * k });
      if (perSide >= 3) tines.push({ t: 0.78, dir: V(0, 0.4, -1), len: 0.075 * k });
      for (const tn of tines) {
        const p0 = along(tn.t);
        const d = tn.dir.clone().normalize();
        const pts = antlerCurve([p0.clone().addScaledVector(d, -0.006), p0.clone().addScaledVector(d, tn.len * 0.5), p0.clone().addScaledVector(d, tn.len).add(V(0, tn.len * 0.25, 0))], lod ? 3 : 5);
        tube(pts, (t) => 0.011 * (1 - 0.7 * t), (t) => colAlong(0.3 + 0.7 * t, 0.55), 0, s);
      }
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
  g.setAttribute('color', new THREE.BufferAttribute(new Uint8Array(col.map((v) => Math.round(clamp(v, 0, 255)))), 4, true));
  g.setIndex(idx);
  g.computeBoundingSphere();
  return g;
}

// ─── Модель ───

// Ходи: частка опори, зсуви фаз копит [FL, FR, BL, BR], підйом копита, згинання зап'ястка/скакального суглоба й бабки.
const DEER_GAITS = [
  { duty: 0.64, off: [0.25, 0.75, 0.0, 0.5], liftF: 0.065, liftB: 0.055, carpus: 1.0, hock: 0.45, fetlock: 0.7, bob: 0.012 },
  { duty: 0.46, off: [0.0, 0.5, 0.5, 0.0], liftF: 0.12, liftB: 0.1, carpus: 1.55, hock: 0.7, fetlock: 0.95, bob: 0.024 },
  { duty: 0.33, off: [0.44, 0.56, 0.0, 0.12], liftF: 0.16, liftB: 0.15, carpus: 1.9, hock: 0.85, fetlock: 1.1, bob: 0.05 },
];
const DEER_LEGS = [
  { name: 'FL', front: true, chain: ['scapFL', 'humFL', 'radFL', 'canFL', 'pasFL'] },
  { name: 'FR', front: true, chain: ['scapFR', 'humFR', 'radFR', 'canFR', 'pasFR'] },
  { name: 'BL', front: false, chain: ['femBL', 'tibBL', 'metBL', 'pasBL'] },
  { name: 'BR', front: false, chain: ['femBR', 'tibBR', 'metBR', 'pasBR'] },
];
// Зони влучання (HIT_ZONES) задано в системах «кісток» старої моделі — тут це допоміжні рамки
// на справжніх кістках: тулуб, шия (вісь y — уздовж шиї), голова (z — уздовж морди), ноги (−y — донизу вздовж кістки).
const DEER_FRAMES = [
  ['body', 'root', 'none'], ['neck', 'neck1', 'neck'], ['head', 'head', 'head'],
  ['hipFL', 'humFL', 'seg'], ['hipFR', 'humFR', 'seg'], ['kneeFL', 'canFL', 'seg'], ['kneeFR', 'canFR', 'seg'],
  ['hipBL', 'femBL', 'seg'], ['hipBR', 'femBR', 'seg'], ['kneeBL', 'metBL', 'seg'], ['kneeBR', 'metBR', 'seg'],
];


class DeerModel {
  constructor(spec, kind, opts = {}) {
    deerInitTemps();
    const asset = deerAsset(kind);
    this.spec = spec;
    this.kind = kind;
    this.asset = asset;
    this.terrain = opts.terrain || null;
    const hdr = asset.header;
    this.object = new THREE.Group();
    this.object.name = `animal-${kind}`;
    const n = hdr.bones.length;
    this.bones = [];
    this.byName = {};
    for (let i = 0; i < n; i++) {
      const b = new THREE.Bone();
      b.name = hdr.bones[i].name;
      b.position.copy(asset.restLocal[i]);
      this.bones.push(b);
      this.byName[b.name] = b;
    }
    for (let i = 0; i < n; i++) {
      const p = asset.parent[i];
      if (p >= 0) this.bones[p].add(this.bones[i]);
      else this.object.add(this.bones[i]);
    }
    this.object.updateMatrixWorld(true);
    this.skeleton = new THREE.Skeleton(this.bones);
    const mat = deerMaterial();
    this.meshes = asset.geometries.map((g) => {
      const m = new THREE.SkinnedMesh(g, mat);
      m.frustumCulled = false;
      m.castShadow = true;
      m.receiveShadow = true;
      this.object.add(m);
      return m;
    });
    this.object.updateMatrixWorld(true);
    for (const m of this.meshes) m.bind(this.skeleton, m.matrixWorld);
    this.lod = 0;
    this.meshes[1].visible = false;
    this.antlers = [];
    // Робочі масиви: локальні повороти кісток, положення й повороти в системі моделі.
    this.lq = Array.from({ length: n }, () => new THREE.Quaternion());
    this.oq = Array.from({ length: n }, () => new THREE.Quaternion());
    this.op = Array.from({ length: n }, () => new THREE.Vector3());
    this.rootPos = asset.restWorld[0].clone();
    this.I = asset.boneIndex;
    this.legs = DEER_LEGS.map((L) => this.legSetup(L));
    this.restPitch = hdr.headPitch;
    const neck1 = asset.restWorld[this.I.neck1];
    const neck2 = asset.restWorld[this.I.neck2];
    const head = asset.restWorld[this.I.head];
    this.neckRest = Math.atan2(head.z - neck1.z, head.y - neck1.y);
    this.neckLen = neck1.distanceTo(neck2) + neck2.distanceTo(head);
    // Кінчик носа відносно потилиці (у системі моделі в спокої) — для дотягування до трави.
    this.noseLocal = new THREE.Vector3(...hdr.nose).sub(head);
    this.frames = {};
    for (const [name, boneName, mode] of DEER_FRAMES) this.addFrame(name, boneName, mode);
    const n0 = spec.neck;
    const h0 = spec.head;
    this.s = { neck: n0.feed, headPitch: h0.feed, yaw: 0, tail: 0, alert: 0, pitch: 0, dead: 0, moving: 0, graze: 1 };
    this.gw = [1, 0, 0];
    this.earTimer = 2;
    this.twitch = 0;
    this.twitchSide = 0;
    this.tailTimer = 3;
    this.flick = 0;
    this.chew = Math.random() * 10;
    this.fallSide = Math.random() < 0.5 ? 1 : -1;
    this.skipFrames = 0;
  }

  legSetup(L) {
    const I = this.I;
    const R = this.asset.restWorld;
    const c = L.chain.map((nm) => I[nm]);
    const pas = c[c.length - 1];
    const foot = R[pas].clone().add(DEER_V[0].set(0, -R[pas].y, 0.045));      // підошва під копитом
    if (L.front) {
      const [scap, hum, rad, can] = c;
      return {
        front: true, scap, hum, rad, can, pas, foot,
        l1: R[hum].distanceTo(R[rad]), l2: R[rad].distanceTo(R[can]),
        dirCan: R[pas].clone().sub(R[can]), dirPas: foot.clone().sub(R[pas]),
        rest: { hum: R[rad].clone().sub(R[hum]).normalize(), rad: R[can].clone().sub(R[rad]).normalize(), can: R[pas].clone().sub(R[can]).normalize(), pas: foot.clone().sub(R[pas]).normalize() },
        target: new THREE.Vector3(), ground: 0,
      };
    }
    const [fem, tib, met] = c;
    return {
      front: false, fem, tib, met, pas, foot,
      l1: R[fem].distanceTo(R[tib]), l2: R[tib].distanceTo(R[met]),
      dirMet: R[pas].clone().sub(R[met]), dirPas: foot.clone().sub(R[pas]),
      rest: { fem: R[tib].clone().sub(R[fem]).normalize(), tib: R[met].clone().sub(R[tib]).normalize(), met: R[pas].clone().sub(R[met]).normalize(), pas: foot.clone().sub(R[pas]).normalize() },
      target: new THREE.Vector3(), ground: 0,
    };
  }

  addFrame(name, boneName, mode) {
    const bone = this.byName[boneName];
    if (!bone) return;
    const f = new THREE.Object3D();
    f.name = `zone-${name}`;
    const I = this.I;
    const R = this.asset.restWorld;
    if (mode === 'neck') f.quaternion.setFromAxisAngle(DEER_AX, this.neckRest);
    else if (mode === 'head') f.quaternion.setFromAxisAngle(DEER_AX, this.restPitch);
    else if (mode === 'seg') {
      const child = this.bones.find((b) => b.parent === bone);
      const dir = child ? R[I[child.name]].clone().sub(R[I[boneName]]).normalize() : new THREE.Vector3(0, -1, 0);
      f.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir);
    } else if (name === 'body') {
      f.position.set(0, 0.95 - R[I.root].y, 0 - R[I.root].z);
    }
    bone.add(f);
    this.frames[name] = f;
  }

  setShadow(on) {
    for (const m of this.meshes) m.castShadow = on;
    for (const a of this.antlers) a.castShadow = on;
  }

  // Рівень деталізації: 0 — повна сітка, 1 — спрощена (для далеких тварин).
  setLod(level) {
    if (level === this.lod) return;
    this.lod = level;
    this.meshes[0].visible = level === 0;
    this.meshes[1].visible = level === 1;
    if (this.antlers.length === 2) {
      this.antlers[0].visible = level === 0;
      this.antlers[1].visible = level === 1;
    }
  }

  // Роги за кількістю відростків трофея (усього на обох рогах) і розміром особини (0..1).
  setAntlers(points, size, seed = 1) {
    for (const a of this.antlers) {
      a.parent.remove(a);
      a.geometry.dispose();
    }
    this.antlers = [];
    if (!points || !this.asset.header.antlerBase) return;
    const perSide = Math.max(1, Math.round(points / 2));
    const head = this.byName.head;
    const hb = this.asset.restWorld[this.I.head];
    const base = this.asset.header.antlerBase;
    const kind = this.kind === 'roe' ? 'roe' : 'stag';
    for (let lod = 0; lod < 2; lod++) {
      const g = buildAntlerGeometry(kind, perSide, size, lod, seed, base[1][0]);
      const mesh = new THREE.Mesh(g, deerMaterial());
      // Основи рогів — на пеньочках; праву половину побудовано на +x, ліву — дзеркально.
      mesh.position.set(-hb.x, base[1][1] - hb.y, base[1][2] - hb.z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      mesh.frustumCulled = false;
      mesh.visible = lod === this.lod;
      head.add(mesh);
      this.antlers.push(mesh);
    }
  }

  boneMatrix(name) {
    const f = this.frames[name];
    return f ? f.matrixWorld : null;
  }

  // ── Кінематика ──

  fk(i) {
    const p = this.asset.parent[i];
    if (p < 0) {
      this.oq[i].copy(this.lq[i]);
      this.op[i].copy(this.rootPos);
    } else {
      this.oq[i].multiplyQuaternions(this.oq[p], this.lq[i]);
      this.op[i].copy(this.asset.restLocal[i]).applyQuaternion(this.oq[p]).add(this.op[p]);
    }
  }

  // Повернути кістку i так, щоб її сегмент (у спокої — restDir) дивився в напрямку dir (система моделі).
  aim(i, restDir, dir) {
    const p = this.asset.parent[i];
    const q = DEER_Q[0].setFromUnitVectors(restDir, DEER_V[11].copy(dir).normalize());
    this.oq[i].copy(q);
    this.lq[i].copy(DEER_Q[1].copy(this.oq[p]).invert()).multiply(q);
    this.op[i].copy(this.asset.restLocal[i]).applyQuaternion(this.oq[p]).add(this.op[p]);
  }

  // Дві кістки: від A до цілі B з довжинами a, b; коліно/лікоть — у бік bend (у площині ноги).
  solve2(A, B, a, b, bendSign, out) {
    const d = DEER_V[1].subVectors(B, A);
    let len = d.length();
    const maxL = (a + b) * 0.999;
    const minL = Math.abs(a - b) * 1.01 + 1e-4;
    if (len > maxL) {
      d.multiplyScalar(maxL / len);
      len = maxL;
    } else if (len < minL) {
      d.multiplyScalar(minL / Math.max(len, 1e-6));
      len = minL;
    }
    const u = DEER_V[9].copy(d).divideScalar(len);
    const cosA = clamp((a * a + len * len - b * b) / (2 * a * len), -1, 1);
    const sinA = Math.sqrt(1 - cosA * cosA);
    // Перпендикуляр у сагітальній площині (вісь x моделі — бокова).
    const w = DEER_V[2].set(0, -u.z, u.y).multiplyScalar(bendSign);
    w.sub(DEER_V[3].copy(u).multiplyScalar(w.dot(u))).normalize();
    out.copy(A).addScaledVector(u, a * cosA).addScaledVector(w, a * sinA);
    return out;
  }

  update(dt, pose) {
    const s = this.s;
    s.neck = damp(s.neck, pose.neck, 3.2, dt);
    s.headPitch = damp(s.headPitch, pose.headPitch, 3.6, dt);
    s.yaw = damp(s.yaw, pose.lookYaw, 4, dt);
    s.tail = damp(s.tail, pose.tail, 6, dt);
    s.alert = damp(s.alert, pose.alert, 4, dt);
    s.pitch = damp(s.pitch, pose.bodyPitch, 6, dt);
    s.dead = pose.dead > s.dead ? Math.min(pose.dead, s.dead + dt * 1.3) : pose.dead;
    const v = pose.speed;
    s.moving = damp(s.moving, smoothstep(0.04, 0.35, v) * (1 - s.dead), 6, dt);
    s.graze = damp(s.graze, smoothstep(1.7, 2.3, pose.neck) * (1 - smoothstep(0.1, 0.6, v)), 3, dt);
    const gw = this.gw;
    gw[0] = 1 - smoothstep(1.8, 3.0, v);
    gw[2] = smoothstep(4.8, 7.0, v);
    gw[1] = Math.max(0, 1 - gw[0] - gw[2]);
    this.earTimer -= dt;
    this.tailTimer -= dt;
    if (this.earTimer <= 0) {
      this.earTimer = 1.5 + Math.random() * 4;
      this.twitchSide = Math.random() < 0.5 ? 0 : 1;
      this.twitch = 1;
    }
    this.twitch = Math.max(0, this.twitch - dt * 4);
    if (this.tailTimer <= 0) {
      this.tailTimer = 2 + Math.random() * 5;
      this.flick = 1;
    }
    this.flick = Math.max(0, this.flick - dt * 2.5);
    this.chew += dt;
    // Невидимі тварини: позу не рахуємо (стани вище оновлюються, тож поява буде плавною).
    if (!this.object.visible) return;
    if (this.lod === 1 && this.skipFrames++ % 2 === 1) return;     // далекі — пів частоти
    this.pose(pose);
  }

  pose(pose) {
    const s = this.s;
    const I = this.I;
    const A = this.asset;
    const R = A.restWorld;
    const TAU = Math.PI * 2;
    const ph = pose.phase;
    const gw = this.gw;
    const moving = s.moving;
    const dead = s.dead;
    const fall = dead * dead * (3 - 2 * dead);
    const strides = this.spec.strides;
    const lq = this.lq;
    for (const q of lq) q.identity();
    // ── Тулуб: підскок, розгойдування в галопі, нахил за рельєфом, падіння на бік ──
    let bob = 0;
    let rock = 0;
    for (let g = 0; g < 3; g++) {
      if (gw[g] <= 0) continue;
      const G = DEER_GAITS[g];
      bob += gw[g] * (g === 2 ? G.bob * Math.sin(TAU * ph + 0.6) : G.bob * Math.cos(TAU * ph * 2));
      if (g === 2) rock += gw[g] * 0.075 * Math.sin(TAU * ph + 1.4);
    }
    bob *= moving;
    rock *= moving;
    const lyingY = 0.21 + (this.kind === 'roe' ? 0.02 : 0);
    this.rootPos.copy(R[I.root]);
    this.rootPos.y = lerp(R[I.root].y + bob - s.graze * 0.035, lyingY, fall);
    DEER_E.set((s.pitch + rock) * (1 - fall), 0, fall * 1.45 * this.fallSide, 'YXZ');
    lq[I.root].setFromEuler(DEER_E);
    // Хребет: згинання й розгинання в галопі.
    const flex = gw[2] * moving * 0.07 * Math.sin(TAU * ph + 0.3);
    lq[I.chest].setFromAxisAngle(DEER_AX, -flex);
    lq[I.pelvis].setFromAxisAngle(DEER_AX, flex * 0.8);
    this.fk(I.root);
    this.fk(I.pelvis);
    this.fk(I.chest);
    // ── Ноги: цілі копит за ходою, обернена кінематика ──
    const scale = this.object.scale.x || 1;
    const terrain = this.terrain;
    const useTerrain = terrain && this.lod === 0 && fall < 0.5;
    const ox = this.object.position.x;
    const oz = this.object.position.z;
    const oy = this.object.position.y;
    const yaw = this.object.rotation.y;
    const cy = Math.cos(yaw);
    const sy = Math.sin(yaw);
    for (let li = 0; li < 4; li++) {
      const leg = this.legs[li];
      const foot = leg.foot;
      let dz = 0;
      let lift = 0;
      let flexA = 0;
      let flexF = 0;
      for (let g = 0; g < 3; g++) {
        if (gw[g] <= 0) continue;
        const G = DEER_GAITS[g];
        const sweep = Math.min(G.duty * strides[g], 0.9);
        const p = fract(ph + G.off[li]);
        let z;
        let l = 0;
        let fa = 0;
        let ff = 0;
        if (p < G.duty) {
          z = sweep * (0.5 - p / G.duty);
        } else {
          const t = (p - G.duty) / (1 - G.duty);
          const e = t * t * (3 - 2 * t);
          z = sweep * (-0.5 + e);
          l = Math.sin(Math.PI * t) * (leg.front ? G.liftF : G.liftB);
          fa = Math.pow(Math.sin(Math.PI * Math.min(1, t * 1.15)), 1.3) * (leg.front ? G.carpus : G.hock);
          ff = Math.sin(Math.PI * t) * G.fetlock;
        }
        dz += gw[g] * z;
        lift += gw[g] * l;
        flexA += gw[g] * fa;
        flexF += gw[g] * ff;
      }
      dz *= moving;
      lift *= moving;
      flexA *= moving;
      flexF *= moving;
      // Під час випасу передні ноги трохи розставлені: одна попереду.
      if (leg.front) dz += s.graze * (li === 0 ? 0.09 : -0.03);
      const T = leg.target.set(foot.x, 0, foot.z + dz);
      let ground = 0;
      if (useTerrain) {
        const wx = ox + (T.x * cy + T.z * sy) * scale;
        const wz = oz + (-T.x * sy + T.z * cy) * scale;
        ground = clamp((terrain.heightAt(wx, wz) - oy) / scale, -0.35, 0.35);
      }
      leg.ground = damp(leg.ground, ground, 18, 1 / 60);
      T.y = leg.ground + lift;
      // Бабка над копитом: пута відхиляється назад під час перенесення ноги.
      const F = DEER_V[4].copy(leg.dirPas).applyAxisAngle(DEER_AX, flexF * 0.9).negate().add(T);
      if (leg.front) {
        lq[leg.scap].setFromAxisAngle(DEER_AX, -dz * 0.55);
        this.fk(leg.scap);
        this.fk(leg.hum);
        const S = this.op[leg.hum];
        const C = DEER_V[5].copy(leg.dirCan).applyAxisAngle(DEER_AX, flexA).negate().add(F);
        const E = this.solve2(S, C, leg.l1, leg.l2, 1, DEER_V[6]);
        this.aim(leg.hum, leg.rest.hum, DEER_V[7].subVectors(E, S));
        this.aim(leg.rad, leg.rest.rad, DEER_V[7].subVectors(C, E));
        this.aim(leg.can, leg.rest.can, DEER_V[7].subVectors(F, C));
        this.aim(leg.pas, leg.rest.pas, DEER_V[7].subVectors(T, F));
      } else {
        this.fk(leg.fem);
        const H = this.op[leg.fem];
        const J = DEER_V[5].copy(leg.dirMet).applyAxisAngle(DEER_AX, -flexA * 0.6).negate().add(F);
        const K = this.solve2(H, J, leg.l1, leg.l2, -1, DEER_V[6]);
        this.aim(leg.fem, leg.rest.fem, DEER_V[7].subVectors(K, H));
        this.aim(leg.tib, leg.rest.tib, DEER_V[7].subVectors(J, K));
        this.aim(leg.met, leg.rest.met, DEER_V[7].subVectors(F, J));
        this.aim(leg.pas, leg.rest.pas, DEER_V[7].subVectors(T, F));
      }
    }
    // ── Шия й голова ──
    const neckTarget = s.neck + moving * gw[0] * 0.04 * Math.sin(TAU * ph * 2) + moving * gw[2] * 0.12 * Math.sin(TAU * ph + 2);
    let dn = neckTarget - this.neckRest - 0.05;
    const yawN = s.yaw * (1 - fall);
    DEER_E.set(dn * 0.55, yawN * 0.3, 0, 'YXZ');
    lq[I.neck1].setFromEuler(DEER_E);
    DEER_E.set(dn * 0.45, yawN * 0.35, 0, 'YXZ');
    lq[I.neck2].setFromEuler(DEER_E);
    const headAbs = clamp(s.headPitch + 0.42, 0.25, lerp(1.6, 1.42, s.graze));
    let headRel = headAbs - this.restPitch - dn - (s.pitch + rock) * 0.7;
    DEER_E.set(headRel, yawN * 0.35, 0, 'YXZ');
    lq[I.head].setFromEuler(DEER_E);
    this.fk(I.neck1);
    this.fk(I.neck2);
    this.fk(I.head);
    // Випас: дотягнути морду до трави (ще трохи нахилити шию, якщо не дістає).
    if (s.graze > 0.02 && fall < 0.5) {
      for (let it = 0; it < 2; it++) {
        const nose = DEER_V[8].copy(this.noseLocal).applyQuaternion(this.oq[I.head]).add(this.op[I.head]);
        const gap = nose.y - 0.03;
        if (Math.abs(gap) < 0.01) break;
        const extra = clamp(gap / Math.max(this.neckLen, 0.3), -0.3, 0.6) * s.graze;
        dn += extra;
        headRel -= extra;
        DEER_E.set(dn * 0.55, yawN * 0.3, 0, 'YXZ');
        lq[I.neck1].setFromEuler(DEER_E);
        DEER_E.set(dn * 0.45, yawN * 0.35, 0, 'YXZ');
        lq[I.neck2].setFromEuler(DEER_E);
        DEER_E.set(headRel, yawN * 0.35, 0, 'YXZ');
        lq[I.head].setFromEuler(DEER_E);
        this.fk(I.neck1);
        this.fk(I.neck2);
        this.fk(I.head);
      }
    }
    // ── Вуха, хвіст ──
    for (let i = 0; i < 2; i++) {
      const side = i === 0 ? -1 : 1;
      const ear = i === 0 ? I.earL : I.earR;
      const tw = i === this.twitchSide ? Math.sin(this.twitch * 20) * this.twitch * 0.4 : 0;
      const flee = gw[2] * moving;
      DEER_E.set((0.3 * s.alert - 0.45 * flee + tw - 0.1) * (1 - fall), side * (-0.3 * s.alert) * (1 - fall), side * (0.08 * s.alert - 0.1 - fall * 0.6), 'XYZ');
      lq[ear].setFromEuler(DEER_E);
    }
    const tailUp = lerp(0.0, 1.25, s.tail) * (1 - fall) + Math.sin(this.flick * 18) * this.flick * 0.3;
    DEER_E.set(tailUp, 0, Math.sin(this.flick * 23) * this.flick * 0.35, 'XYZ');
    lq[I.tail1].setFromEuler(DEER_E);
    lq[I.tail2].setFromAxisAngle(DEER_AX, tailUp * 0.35);
    // ── Загибель: ноги розслаблені й витягнуті, шия лягає на землю ──
    if (fall > 0) {
      const lim = DEER_Q[2];
      const relax = (name, x) => {
        const i = I[name];
        if (i === undefined) return;
        lim.setFromAxisAngle(DEER_AX, x);
        lq[i].slerp(lim, fall);
      };
      for (const sd of ['L', 'R']) {
        const k = sd === 'L' ? 1 : 0.8;
        relax(`humF${sd}`, 0.5 * k);
        relax(`radF${sd}`, -0.35 * k);
        relax(`canF${sd}`, 0.35);
        relax(`pasF${sd}`, 0.4);
        relax(`femB${sd}`, -0.45 * k);
        relax(`tibB${sd}`, 0.55);
        relax(`metB${sd}`, -0.35);
        relax(`pasB${sd}`, 0.4);
        relax(`scapF${sd}`, 0.1);
      }
      relax('neck1', 0.75);
      relax('neck2', 0.35);
      relax('head', 0.15);
    }
    // ── Запис у кістки ──
    const bones = this.bones;
    for (let i = 0; i < bones.length; i++) bones[i].quaternion.copy(lq[i]);
    bones[I.root].position.copy(this.rootPos);
  }
}

// Кількість відростків рогів — та сама формула, що й у картці трофея.
function antlerPointsFor(an) {
  const spec = an.spec;
  const sc = spec.scale;
  const k = clamp((an.scale / (an.female ? spec.femaleScale : 1) - sc[0]) / (sc[1] - sc[0]), 0, 1);
  if (an.female) return { points: 0, k };
  if (an.species === 'deer') return { points: 2 * Math.round(3 + k * 4), k };
  if (an.species === 'roe') return { points: 2 * Math.round(1 + k * 2), k };
  return { points: 0, k };
}

// Дані сіток оленів (формат WHD1, base64): створено генератором анатомії deer-gen (див. розділ 11b).
const DEER_MODEL_DATA = {
  stag: '',
  hind: '',
  roe: '',
};

// ═══════════════════════════ 12. ЗБРОЯ: МОДЕЛЬ, ПРИЦІЛ, ПОСТРІЛ, ВЛУЧАННЯ ═══════════════════════════
/*
 * Спорядження (магазин і вибір у меню), вид від першої особи (моделі карабінів і прицілів —
 * у розділі 12a, їх можна замінити на GLB), балістика кулі (швидкість, падіння, опір повітря),
 * зони влучання тварин і сліди влучань.
 */

